/* ÇEVİRİ fr · olay — arac/ceviri.py ile YAZILDI, elle düzenleme: py arac/ceviri.py uygula.
   Kayıt: id → [metin, kaynak_ozet] (olayda alan başına). Tasarım: denetim/CEVIRI-1103/TASARIM.md */
Ceviri.ekle("fr","olay",{
"OLAYLAR:1299-01:0":{"b": ["Fondation de la principauté ottomane", "9f0b7c0a"], "d": ["Le fait qu'Osman Gazi, de la tribu des Kayı, ait commencé à agir de manière indépendante dans la région de Söğüt et de Domaniç est tenu pour le point de départ traditionnel de la fondation de l'État ottoman ; certains historiens considèrent la victoire de Bapheus, en 1302, comme le véritable tournant. Grâce à sa position dans la zone marchesque byzantine, la principauté gagna rapidement en puissance par ses raids de ghaza. Dans ce contexte de dissolution de l'héritage seldjoukide, Osman Gazi rassembla autour de lui des ahis, des ghazis et des Turkmènes nomades ; le lien qu'il noua avec le cheikh Edebali est considéré comme le fondement de la légitimité spirituelle de la principauté. Autres lieux rattachés à la même date : İnegöl, Yarhisar.", "9d689d45"]},
"OLAYLAR:1326-04-06:0":{"b": ["Prise de Bursa", "98c727fa"], "d": ["Bursa, tenue en état de blocus pendant des années, se rendit à Orhan Gazi, qui dirigeait la phase finale du siège ; la ville devint la première grande capitale de la principauté. On rapporte que la nouvelle de la conquête fut portée à Osman Gazi sur son lit de mort ; conformément à son testament, Osman Gazi fut enterré à Bursa. La ville fut rapidement dotée de mosquées, d'imarets et de médersas, et devint le modèle de l'urbanisme ottoman des origines.", "9ede6ee9"]},
"OLAYLAR:1331-03-02:0":{"b": ["Prise de Nicée", "a846a811"], "d": ["Nicée (İznik, Nikaia), l'un des centres les plus importants de Byzance en Anatolie, perdit tout espoir de résister après la victoire de Pelekanon en 1329 et se rendit à Orhan Gazi. La première médersa ottomane y fut fondée et des savants tels que Dâvûd-i Kayserî commencèrent à y enseigner ; la ville devint le centre intellectuel de la période initiale. L'église Sainte-Sophie fut transformée en mosquée, offrant un des premiers exemples de la tradition de la conquête.", "8fd3bfb5"]},
"OLAYLAR:1337-01-01:0":{"b": ["Prise d'İzmit", "06a35035"], "d": ["Avec la chute d'İzmit (Nicomédie), la dernière grande forteresse byzantine de la rive anatolienne passa elle aussi sous l'administration ottomane ; toute la péninsule de Kocaeli, jusqu'à la rive opposée de Constantinople, devint terre ottomane. La principauté, qui dominait ainsi l'ensemble des côtes sud et est de la Marmara, préparait de la sorte les bases de son passage en Roumélie.", "f677745c"]},
"OLAYLAR:1352-03-01:0":{"b": ["Forteresse de Çimpe — passage en Roumélie", "c2f0a07d"], "d": ["Süleyman Pacha, fils d'Orhan Gazi, avait pris pour base en 1352 la forteresse de Çimpe, qui lui avait été donnée lors de la guerre civile byzantine ; après le grand tremblement de terre qui ruina Gallipoli en mars 1354, les forteresses évacuées furent rapidement fortifiées et la péninsule fut transformée en une tête de pont ottomane durable. Soutenue par l'installation de populations turkmènes amenées d'Anatolie, cette étape marque le début d'une présence ottomane sur le continent européen qui devait dépasser les 550 ans.", "4857333a"]},
"OLAYLAR:1361-05-05:0":{"b": ["Prise d'Andrinople (Edirne)", "2f54ebb0"], "d": ["La prise d'Edirne (Andrinople, Adrianopolis), ville clé de la Thrace, détermina la base principale et l'orientation des conquêtes balkaniques ; la date de la conquête est discutée dans les sources, entre 1361 et 1369. La ville fut peu après érigée en capitale, proclamant que le centre de gravité de l'État s'était déplacé vers la Roumélie ; elle resta le siège du pouvoir (payitaht) pendant environ 90 ans, jusqu'à la prise de Constantinople.", "25bd644f"]},
"OLAYLAR:1362-03:0":{"b": ["Avènement de Murad Ier", "f8d48a26"], "d": ["Murad Ier (Hüdavendigâr), monté sur le trône à la mort d'Orhan Gazi, fit passer l'État, au cours de ses 27 années de règne, du statut de principauté marchesque à celui de charpente d'un empire. Avec le système du pençik, les bases du corps des janissaires furent posées, le régime du timar fut généralisé, le beylerbeylik de Roumélie fut créé et l'institution du vizirat fut renforcée. Les conquêtes balkaniques devinrent sous son règne une politique d'État systématique.", "d463078a"]},
"OLAYLAR:1389-06-15:0":{"b": ["Première bataille de Kosovo — martyre de Murad Ier", "10b8ddc9"], "d": ["La coalition balkanique conduite par le knez Lazar fut définitivement vaincue dans la plaine de Kosovo ; la Serbie passa sous la suzeraineté ottomane. Murad Ier, qui parcourait le champ de bataille, fut poignardé par le noble serbe Miloš Obilić et tomba en martyr — il est le seul sultan ottoman mort sur un champ de bataille. Bayezid le Foudre fut mis à sa place dans le camp ; son frère Yakub Çelebi fut étranglé, ce qui constitue l'un des premiers exemples connus de la pratique du fratricide.", "153449fe"]},
"OLAYLAR:1396-09-25:0":{"b": ["Victoire de Nicopolis", "75716e96"], "d": ["La grande armée croisée, réunie à l'appel du roi de Hongrie Sigismond et à laquelle participaient aussi des chevaliers français et bourguignons, fut lourdement défaite par Bayezid le Foudre devant Nicopolis, sur les bords du Danube. La victoire consolida la domination ottomane sur la Bulgarie ; pendant toute une génération, aucune grande croisade ne put être organisée en Europe.", "0d06e36c"]},
"OLAYLAR:1402-07-28:0":{"b": ["Bataille d'Ankara — début de l'Interrègne", "b4a99d96"], "d": ["Dans la lourde défaite subie dans la plaine de Çubuk face à l'armée de Tamerlan, Bayezid le Foudre fut fait prisonnier et mourut en captivité quelques mois plus tard. Tamerlan fit renaître les principautés d'Anatolie ; les terres ottomanes furent morcelées entre les fils de Bayezid, et une lutte pour le trône qui devait durer 11 ans (l'Interrègne, Fetret Devri) commença. Cette période, la crise la plus grave que l'État ait connue depuis sa fondation, grava dans la mémoire ottomane l'importance de la structure centralisée. Autres établissements perdus à la même date : Datça, Marmaris, Fethiye (Makri), Söke, Kütahya, Afyon, Isparta, Manisa, Aydın, Denizli, Muğla, Antalya, Konya, Karaman, Kayseri, Kastamonu, Bartın, Safranbolu, Samsun, Sivas, Malatya, Beyşehir, Sivrihisar, Kırşehir, Çorum, Çankırı, Yenişehir (Bursa), İnegöl, la forteresse d'Aydos, Geyve, Köprühisar (Yenişehir), Marmaracık, Akhisar (Pamukova), Mekece, Kestel, Ulubat, Harmankaya, Akyazı, l'île d'İmralı, Kandıra, Mudanya, Yalova, Karamürsel, Armutlu, Gemlik (Kios), Söğüt, Bilecik, Eskişehir, Bursa, Nicée (İznik), İzmit, Balıkesir, Çanakkale, Bergama, Amasya, Tokat, Çorlu, Lüleburgaz, Malkara, Keşan, İpsala, Kilitbahir, Çirmen, Stara Zagora (Eski Zağra), Tatarpazarcığı, İhtiman, Köstendil, Petriç, Nevrokop (Gotse Delchev), Drama, Gallipoli (Gelibolu), Çimpe, Andrinople (Edirne), Dimetoka, Kırklareli, Tekirdağ, Plovdiv (Filibe), Sofia, Niš, Vidin, Tărnovo, Varna, Şumnu, Silistra, Nicopolis (Niğbolu), Roussé (Rusçuk), Thessalonique, Serrès, Kavala, Skopje (Üsküp), Monastir, Ohrid, Yenişehir (Larissa), Trikala (Tırhala), Izdin (Lamia), Plevne, Gümülcine, Biga, Domaniç, Kulacahisar, Karacahisar, Yarhisar, Dimbos, Kite (Kete), Lefke (Osmaneli), Leblebicihisar, Karaçepüş, Karatigin, Absu (Hypsu), Adranos (Orhaneli), Pelekanon (Eskihisar), Gebze, Hereke, Samandıra, Kirmasti (M. Kemalpaşa), Mihaliç (Karacabey), Köstence, Gölyazı (Apollonia).", "d34e55d5"]},
"OLAYLAR:1413-07:0":{"b": ["Çelebi Mehmed rétablit l'unité", "03413dfd"], "d": ["Mehmed Ier, qui vainquit Mûsâ Çelebi à Çamurlu lors du dernier règlement de comptes entre les frères, réunit les terres du pays sous une administration unique ; c'est pourquoi il est considéré comme le « second fondateur de l'État ». Au cours de son règne, la structure usée de l'État fut réparée, les relations avec les principautés d'Anatolie furent rééquilibrées et une politique de paix prudente fut suivie en Roumélie.", "d8f535c2"]},
"OLAYLAR:1416-05-01:0":{"b": ["Révolte du cheikh Bedreddin", "e0a072ca"], "d": ["Le mouvement religieux et social qui se développa autour du cheikh Bedreddin, grand juriste et mystique qui avait exercé la charge de cadi-asker pendant l'Interrègne, éclata en même temps que les soulèvements de Börklüce Mustafa à Karaburun et de Torlak Kemal à Manisa. Les révoltes furent réprimées dans le sang ; Bedreddin, capturé dans le Deliorman, fut exécuté à Serrès. L'événement, premier grand soulèvement social et mahdiste de l'histoire ottomane, laissa une trace profonde dans la littérature et l'historiographie.", "1cf72ec4"]},
"OLAYLAR:1444-11-10:0":{"b": ["Victoire de Varna", "f739eedc"], "d": ["L'armée croisée hungaro-polonaise, qui avait rompu la paix de Szeged et descendu vers le sud, fut anéantie à Varna par Murad II, qui avait abdiqué mais était revenu à la tête de l'armée ; le jeune roi Ladislas III périt sur le champ de bataille. La victoire écarta la dernière grande chance d'intervention extérieure visant à liquider la présence ottomane dans les Balkans et assura la voie menant à la prise de Constantinople.", "43adf0fb"]},
"OLAYLAR:1448-10-17:0":{"b": ["Seconde bataille de Kosovo", "ebe0b662"], "d": ["L'armée de János Hunyadi, qui voulait venger Varna, fut définitivement vaincue par Murad II lors d'un combat acharné de trois jours. C'est la dernière grande bataille rangée que les croisés aient engagée dans les Balkans contre les Ottomans ; avec cette victoire, la domination ottomane au sud du Danube s'établit de manière irréversible.", "ea3ae23b"]},
"OLAYLAR:1453-05-29:0":{"b": ["La prise de Constantinople", "583d5e3e"], "d": ["Après un siège de cinquante-quatre jours (6 avril – 29 mai 1453), l'armée ottomane franchit les murailles au matin du 29 mai et entra dans la ville ; le dernier empereur, Constantin XI, mourut au combat, et l'Empire romain d'Orient, vieux de 1100 ans, disparut de l'histoire. Le jeune sultan prit le titre de « Fâtih » (le Conquérant), fit de la ville sa capitale et transforma Sainte-Sophie en mosquée ; la ville fut rapidement ranimée par le repeuplement et les constructions. La fonte de canons gigantesques, le transport des navires par voie terrestre et le dispositif de siège devant les murailles sont considérés comme le sommet de l'ingénierie militaire de l'époque. Dans l'historiographie européenne, la conquête est comptée parmi les dates symboliques de la fin du Moyen Âge.", "3664c5fe"]},
"OLAYLAR:1461-08-15:0":{"b": ["Prise de Trébizonde", "15f52403"], "d": ["À l'issue de la difficile campagne de la mer Noire que Mehmed le Conquérant mena simultanément par terre et par mer, l'Empire grec de Trébizonde se rendit ; avec la liquidation de ce dernier vestige du monde byzantin en Anatolie, toute la côte méridionale de la mer Noire passa sous la domination ottomane. La fin de la dynastie des Comnènes renforça la prétention du Conquérant au titre de « souverain des deux mers et des deux terres ». Autres lieux rattachés à la même date : Giresun, Rize.", "ca6ead13"]},
"OLAYLAR:1473-01-01:0":{"b": ["Conquête définitive de Silifke — brisure de la dernière résistance des Karamanides", "d988bee4"], "d": ["La forteresse de Silifke s'était rendue une première fois à Gedik Ahmed Pacha en 1472, mais la même année le Karamanoğlu Kasım Bey, avec l'aide de la flotte croisée en Méditerranée, l'avait reprise. Après la victoire d'Otlukbeli, le Conquérant chargea son fils et Gedik Ahmed Pacha de s'emparer définitivement de la région ; avec l'aide des anciens artilleurs ottomans, le dépôt de poudre fut incendié et la forteresse tomba rapidement. La dernière résistance des Karamanides dans les montagnes du Taşeli et de l'İçel fut ainsi brisée ; la liquidation de la principauté devait s'achever en 1474.", "e9814184"]},
"OLAYLAR:1473-08-11:0":{"b": ["Bataille d'Otlukbeli", "42c7194e"], "d": ["Uzun Hasan, souverain des Aqqoyunlu devenu une grande puissance en Orient et allié de Venise, subit à Otlukbeli une lourde défaite face à l'armée du Conquérant équipée d'armes à feu. La victoire confirma la supériorité ottomane en Anatolie ; elle fut aussi une des premières preuves de la supériorité d'une armée centrale utilisant canons et fusils face à une armée classique.", "9c59ac50"]},
"OLAYLAR:1475-06-06:0":{"b": ["Mise de la Crimée sous protection ottomane", "44e3f7c8"], "d": ["La flotte placée sous le commandement de Gedik Ahmed Pacha conquit les villes de la côte méridionale de la Crimée, à commencer par Caffa, aux mains de Gênes ; ces côtes furent érigées en sandjak ottoman direct. Le khanat de Crimée devint avec Mengli Giray un État vassal privilégié reconnaissant la suzeraineté ottomane, et fut pendant trois siècles la pierre angulaire de la politique ottomane dans le Nord ; la mer Noire se transformait désormais, de fait, en mer intérieure ottomane. Autres lieux rattachés à la même date : Bahçesaray, Kertch, Azak (Azov).", "a3448d71"]},
"OLAYLAR:1481-05-03:0":{"b": ["Mort du Conquérant — l'affaire du prince Djem", "190ecf01"], "d": ["À la mort soudaine du Conquérant en campagne, Bayezid II monta sur le trône ; son frère, le prince Djem, revendiquant le sultanat, fit dire la khutba et frapper monnaie en son nom à Bursa. Vaincu, il se réfugia d'abord chez les Mamelouks, puis chez les chevaliers de Rhodes ; devenu entre les mains des chevaliers et de la papauté un atout de marchandage de la diplomatie européenne, Djem mourut à Naples en 1495. Cette affaire contraignit la politique extérieure ottomane à la prudence pendant quinze ans.", "7e488d7b"]},
"OLAYLAR:1514-08:0":{"b": ["Victoire de Çaldıran", "fea64ebb"], "d": ["Désireux de résoudre à la racine la menace créée en Anatolie par la propagande séfévide, le sultan Selim le Terrible infligea une lourde défaite à l'armée du chah Ismaïl dans la plaine de Çaldıran, grâce à la supériorité de son artillerie et de ses fusils. Tabriz fut occupée ; l'Anatolie orientale et sud-orientale ainsi que la ligne Mossoul–Diyarbakır furent rattachées à l'administration ottomane. Le ralliement des beys kurdes à l'Empire ottoman, obtenu par les efforts d'İdrîs-i Bitlisî, établit le cadre de la frontière orientale pour des siècles.", "67b03a64"]},
"OLAYLAR:1516-08-24:0":{"b": ["Victoire de Mardj Dabiq", "07d254d3"], "d": ["L'armée mamelouke fut dispersée en quelques heures à Mardj Dabiq, au nord d'Alep ; le vieux sultan Qansuh al-Ghawri mourut pendant la bataille. Cette victoire, qui ouvrit grand les portes d'Alep et de Damas, fit passer la Syrie, le Liban et la Palestine sous l'administration ottomane ; la voie de la campagne d'Égypte, qui devait mettre fin à l'État mamelouk, était ouverte.", "c4b15f39"]},
"OLAYLAR:1517-01-22:0":{"b": ["Ridaniyya — conquête de l'Égypte et califat", "caf378d6"], "d": ["L'armée ottomane, qui avait rapidement traversé le désert du Sinaï, perça la ligne de défense de Tomanbay à Ridaniyya et entra au Caire ; Tomanbay, qui poursuivait la résistance, fut capturé et exécuté, et l'État mamelouk disparut de l'histoire. L'Égypte, le Hedjaz et les villes saintes passèrent sous l'administration ottomane ; le calife abbasside et les saintes reliques furent emmenés à Istanbul. Avec le passage du califat à la dynastie ottomane, les sultans assumèrent la prétention à la direction du monde islamique ; le contrôle de la route des épices procura aussi à l'Empire de grands revenus. Autres lieux rattachés à la même date : Acre, Ma'an, Sidon, Kerak.", "a0cc8fdc"]},
"OLAYLAR:1520-09-30:0":{"b": ["Avènement de Soliman le Législateur", "f6512269"], "d": ["Soliman Ier, monté sur le trône à la mort de Selim le Terrible en tant que seul fils mâle, connut un règne de 46 ans considéré comme le sommet politique, militaire, juridique et culturel de l'Empire. Les kanunnâme qui systématisèrent le droit coutumier (örf) lui valurent le surnom de « Kanunî » (le Législateur) ; en Occident, on le désigna sous le nom de « Magnifique ». Les œuvres de l'architecte Sinan, l'âge d'or de la littérature de divan et la suprématie de la flotte en Méditerranée sont les symboles de cette période.", "cda7a2fb"]},
"OLAYLAR:1521-08-29:0":{"b": ["Prise de Belgrade", "59ef5cec"], "d": ["Belgrade, que le Conquérant n'avait pu prendre en 1456 et que l'on tenait pour la « clé de l'Europe centrale », tomba lors de la première campagne de Soliman, à la suite d'un siège au confluent du Danube et de la Save. La ligne de défense méridionale de la Hongrie s'effondrait ; cette conquête ouvrit la porte de la campagne d'Europe centrale qui devait mener, cinq ans plus tard, à Mohács et, vingt ans plus tard, à l'annexion de Bude.", "69dbb7cc"]},
"OLAYLAR:1522-12-21:0":{"b": ["Prise de Rhodes", "807bbb1e"], "d": ["Rhodes, base des chevaliers de Saint-Jean qui menaçaient les routes maritimes de la Méditerranée orientale et l'itinéraire du pèlerinage, se rendit par capitulation (vire) après un siège sanglant de plusieurs mois ; les chevaliers furent autorisés à quitter librement l'île (ils s'établirent par la suite à Malte). La sécurité des côtes anatoliennes fut assurée et la ligne maritime Istanbul–Égypte passa sous le contrôle ininterrompu des Ottomans.", "aeedfb16"]},
"OLAYLAR:1526-08-29:0":{"b": ["Bataille de Mohács", "f3418b0d"], "d": ["L'armée hongroise fut anéantie en environ deux heures dans la plaine de Mohács par le tir des canons et la supériorité de manœuvre ; le roi Louis II mourut dans un marais en s'enfuyant. Mohács, l'une des grandes batailles rangées les plus rapidement gagnées de l'histoire ottomane, mit fin de fait au royaume indépendant de Hongrie et ouvrit en Europe centrale l'ère de la rivalité ottomano-habsbourgeoise.", "48967894"]},
"OLAYLAR:1529-09:0":{"b": ["Premier siège de Vienne", "dc49ea4f"], "d": ["Lors de la campagne menée contre la mainmise des Habsbourg sur le trône de Hongrie, l'armée ottomane assiégea Vienne ; à cause de l'abandon des canons lourds en chemin, de l'hiver précoce et des difficultés de ravitaillement, le siège fut levé au bout de trois semaines. Bien que la ville n'ait pu être prise, l'influence ottomane sur la Hongrie fut préservée ; les abords de Vienne marquèrent la limite d'accès logistique de l'Empire en Europe centrale.", "a49fc760"]},
"OLAYLAR:1534-12-04:0":{"b": ["Prise de Bagdad — campagne des Deux Irak", "897092c3"], "d": ["Lors de la campagne organisée contre les « Deux Irak » (Irak arabe et Irak persan), on entra d'abord à Tabriz, puis, sans combat, à Bagdad ; la prise de l'ancienne capitale des Abbassides valut au souverain ottoman un grand prestige dans le monde islamique. Le mausolée de l'imam Abû Hanîfa fut restauré ; avec le rattachement de Bagdad et de Bassora, les terres ottomanes atteignirent le golfe Persique. Autres lieux rattachés à la même date : Kirkouk, Kerbela.", "f3f80434"]},
"OLAYLAR:1538-09:0":{"b": ["Victoire navale de Préveza", "30dc0f97"], "d": ["La flotte croisée constituée sous la direction du pape, bien que supérieure en nombre, fut dispersée au large de Préveza par la tactique de Barberousse, qui utilisa habilement le vent et la côte ; Andrea Doria quitta le champ de bataille. La victoire établit pour environ 33 ans une suprématie navale ottomane incontestée en Méditerranée ; elle est la date symbolique de la fête de la marine dans la tradition maritime turque. Autres lieux rattachés à la même date : Aden, Bender.", "0411d92f"]},
"OLAYLAR:1541-08-29:0":{"b": ["Annexion de Bude — la Hongrie, province ottomane", "db53b244"], "d": ["Soliman, parti en campagne à la suite du siège de Bude par les Habsbourg, délivra la ville, puis plaça la Hongrie centrale sous administration ottomane directe en créant le beylerbeylik de Bude ; la Transylvanie fut faite principauté autonome vassale de l'Empire. Cette organisation de la Hongrie en trois parties dura environ 150 ans et constitua la charpente durable de l'administration ottomane en Europe centrale.", "1eb63e33"]},
"OLAYLAR:1555-05-29:0":{"b": ["Paix d'Amasya", "a5afe0d1"], "d": ["C'est le premier traité de paix officiel qui mit fin aux guerres ottomano-séfévides de longues années. Bagdad et l'Irak restèrent à l'Empire ottoman, et la frontière de l'Anatolie orientale fut pour la première fois reconnue de part et d'autre ; les Séfévides s'engagèrent à cesser la propagande chiite dans les terres ottomanes, et les Ottomans à garantir la sécurité du passage des pèlerins iraniens. Le traité fut le premier exemple de cadre juridique des relations entre les deux États.", "220b198f"]},
"OLAYLAR:1566-09-07:0":{"b": ["Szigetvár — mort de Soliman le Législateur", "e2917ed2"], "d": ["Soliman, âgé de 72 ans, mourut sous sa tente quelques heures avant la chute de la forteresse de Szigetvár, qu'il assiégeait lors de sa treizième campagne ; Sokollu Mehmed Pacha cacha sa mort pendant des semaines pour éviter la dispersion de l'armée. La forteresse fut prise, mais l'État avait perdu le plus long et le plus glorieux de ses sultans ; son fils Selim II monta sur le trône et le poids des grands vizirs dans l'administration de l'État commença à croître.", "62c468a1"]},
"OLAYLAR:1571-08:0":{"b": ["Conquête de Chypre", "e364a2b3"], "d": ["Un débarquement eut lieu en 1570 sur Chypre, alors sous administration vénitienne ; Nicosie tomba rapidement, tandis que Famagouste ne se rendit qu'en août 1571, après un siège de onze mois. L'île, d'importance critique pour la sécurité des routes commerciales et des routes du pèlerinage de la Méditerranée orientale, fut organisée en beylerbeylik et peuplée de populations venues d'Anatolie ; la conquête fut aussi le motif de la grande alliance croisée qui aboutit à Lépante.", "6dcfdc0f"]},
"OLAYLAR:1571-10-07:0":{"b": ["Défaite de Lépante (İnebahtı)", "6a1d44a9"], "d": ["La flotte croisée, unie à la suite de la conquête de Chypre, surprit la flotte ottomane dans le golfe de Lépante et en détruisit la plus grande partie ; le grand amiral (kapudan-ı derya) Müezzinzâde Ali Pacha tomba en martyr et seule la flotte d'Uluç Ali échappa. Après le désastre, le grand vizir Sokollu Mehmed Pacha nomma Uluç Ali Pacha grand amiral, le chargea de rassembler la flotte dispersée et fit commencer la construction d'une nouvelle flotte dans tous les arsenaux, d'Istanbul à Alanya ; toutefois, la suprématie absolue en Méditerranée était psychologiquement ébranlée.", "4cb5c93e"]},
"OLAYLAR:1596-10-26:0":{"b": ["Bataille de Mezőkeresztes (Haçova)", "da308ec5"], "d": ["Lors de la plus grande bataille rangée de la Longue Guerre (1593–1606), l'armée, que Mehmed III commandait en personne, se ressaisit, à l'instant où elle était sur le point de se disperser, sur les conseils de Hoca Sâdeddin Efendi, et mit en déroute l'armée des Habsbourg. Elle est tenue pour la dernière grande bataille rangée classique gagnée par les Ottomans ; mais le fait qu'elle n'ait pas changé le cours général de la guerre fut aussi considéré comme un signe de l'usure du système militaire.", "77f2a384"]},
"OLAYLAR:1606-11-11:0":{"b": ["Traité de Zsitvatorok", "39c01142"], "d": ["Par le traité qui mit fin à treize ans de guerre épuisante, le souverain des Habsbourg fut pour la première fois reconnu comme l'égal du sultan sous le titre d'« empereur romain », et le tribut annuel fut supprimé. Les pertes territoriales furent presque nulles ; mais ce changement du langage diplomatique est lu comme le symbole de la fin de la prétention ottomane à une supériorité absolue face à l'Europe.", "99a455e7"]},
"OLAYLAR:1639-05-17:0":{"b": ["Traité de Qasr-i Chirin (Kasr-ı Şirin)", "c1acf3af"], "d": ["Signé à la suite de la reprise de Bagdad par Murad IV (1638), le traité mit fin à plus d'un siècle de guerres ottomano-séfévides. Bagdad et l'Irak restèrent définitivement à l'Empire ottoman, Erevan fut laissée aux Séfévides ; la ligne tracée, avec de légères modifications, devint le fondement de l'actuelle frontière turco-iranienne, tenue pour l'une des frontières les plus durables du monde. Le traité laissa aux Ottomans Bedre, Cessân, Mendelî, Derteng et Derne ; la forteresse frontière de Zencir devait être démolie, les villages situés à l'ouest revenant à l'Empire ottoman, ceux de l'est à l'Iran. Les environs de la forteresse de Zalim, près de Şehrizor, et Kızılca Kale restèrent aux Ottomans, Avroman et Mihriban à l'Iran ; les forteresses de Kotur, de Mâkû et de Mağazberd devaient être démolies par les deux parties.", "c2d59f3f"]},
"OLAYLAR:1669-09-06:0":{"b": ["Achèvement de la conquête de la Crète", "e0d85604"], "d": ["Le siège de Candie, dernier acte de la guerre de Crète commencée en 1645, s'acheva par la campagne résolue de trois ans de Fâzıl Ahmed Pacha ; le commandant vénitien Morosini remit la ville par traité. La lutte, qui dura environ un quart de siècle, entra dans l'histoire comme le plus long siège de l'histoire ottomane ; la dernière grande forteresse latine de la Méditerranée orientale passa sous l'administration ottomane. Trois petites forteresses rocheuses de la côte nord de l'île — Suda, Spinalonga et Grambousa — restaient encore à Venise ; comme elles sont établies sur des îlots distincts, elles ne peuvent être figurées sur la carte séparément du reste de la Crète.", "314efa97"]},
"OLAYLAR:1672-10-18:0":{"b": ["Traité de Buczacz (Bucaş) — frontières les plus étendues", "b17b6e5a"], "d": ["Par le traité de Buczacz, signé après la conquête de Kamieniec lors de la campagne de Pologne, la Podolie fut rattachée à l'Empire ottoman et une partie de l'Ukraine fut placée sous protection. L'Empire atteignit ainsi ses frontières les plus étendues en Europe ; ce point est tenu pour le sommet de l'ère d'expansion et en même temps pour son dernier maillon.", "6d489670"]},
"OLAYLAR:1683-09-12:0":{"b": ["Déroute du second siège de Vienne", "7d889252"], "d": ["Le siège de Vienne, qui durait depuis deux mois sous Merzifonlu Kara Mustafa Pacha, tourna à la déroute sous le coup soudain que le roi de Pologne Jean Sobieski porta depuis les hauteurs du Kahlenberg ; l'armée se retira en abandonnant ses bagages, et Merzifonlu fut exécuté à Belgrade. La guerre qui suivit, avec la Sainte-Ligue formée après la victoire, dura 16 ans ; cette déroute est désignée comme le moment où débuta le grand recul de l'histoire ottomane.", "88ceb19f"]},
"OLAYLAR:1692-01-01:0":{"b": ["Prise de la forteresse de Grambousa — l'une des forteresses rocheuses de Crète restées à Venise", "3ddf9eeb"], "d": ["Bien que la conquête de la Crète soit considérée comme largement achevée avec la reddition de Candie en 1669, Grambousa, forteresse insulaire rocheuse à l'extrémité nord-ouest de l'île, resta vingt-trois ans de plus aux mains de Venise. Sa prise en 1692 éliminait l'un des trois vestiges vénitiens de Crète ; Suda et Spinalonga devaient attendre la campagne de Morée de 1715.", "05e94fe9"]},
"OLAYLAR:1699-01-26:0":{"b": ["Traité de Karlowitz — première grande perte territoriale", "8f7e2546"], "d": ["Par Karlowitz, qui mit fin à seize ans de guerres contre la Sainte-Ligue, la Hongrie et la Transylvanie furent cédées à l'Autriche, la Podolie à la Pologne, la Morée et les côtes de Dalmatie à Venise. Pour la première fois dans l'histoire ottomane, un territoire de cette ampleur était perdu à la table des négociations et de façon définitive ; le traité est tenu pour l'acte inaugural de l'ère nouvelle où l'Empire passa à la défensive face à l'Europe, et marque aussi un tournant de l'histoire de la diplomatie ottomane.", "54bb2eee"]},
"OLAYLAR:1711-07-19:0":{"b": ["Victoire du Prut", "2583572f"], "d": ["Dans la guerre déclenchée à propos du roi de Suède réfugié chez les Ottomans après la défaite de Poltava, l'armée du tsar Pierre Ier fut encerclée sur les bords du Prut et dut se rendre. Par le traité signé, Azak (Azov) fut reprise ; le fait de n'avoir pas détruit l'armée et d'avoir laissé le tsar en liberté est entré dans l'histoire comme une décision discutée depuis lors.", "ce9c2996"]},
"OLAYLAR:1715-01-01:0":{"b": ["Prise des forteresses de Suda et de Spinalonga — effacement de la dernière trace vénitienne en Crète", "7261f7ba"], "d": ["Vingt-trois ans après la chute de Grambousa en 1692, les forteresses de Suda et de Spinalonga, les deux derniers points d'appui de Venise en Crète, furent elles aussi conquises, par une branche annexe de la campagne de Morée. La conquête de la Crète, commencée en 1645, fut ainsi achevée, au bout de quarante-six ans, jusqu'au dernier pouce de l'île.", "d2044cae"]},
"OLAYLAR:1730-09-25:0":{"b": ["Révolte de Patrona Halil", "100941a4"], "d": ["L'échec sur le front iranien, les impôts et la colère suscitée par le luxe de l'entourage du palais se transformèrent en un grand soulèvement sous la conduite de Patrona Halil, masseur de hammam. Le grand vizir İbrahim Pacha fut tué, Ahmed III fut déposé et l'Ère des tulipes prit fin ; le fait que les insurgés aient dominé la ville pendant des mois montra de manière saisissante la fragilité de l'autorité centrale.", "d87eea77"]},
"OLAYLAR:1739-09-18:0":{"b": ["Traité de Belgrade — reprise de Belgrade, de Smederevo et de la Serbie du Nord", "ba7f8e46"], "d": ["À l'issue de la guerre menée sur deux fronts contre l'Autriche et la Russie (1736–1739), Belgrade et la Serbie du Nord furent reprises ; la Russie accepta de démanteler Azak (Azov) et de ne pas entretenir de flotte en mer Noire. Considéré comme le dernier grand succès de la diplomatie et de l'armée ottomanes du XVIIIe siècle, le traité procura à l'Empire une période de paix d'un quart de siècle.", "5b399dd2"]},
"OLAYLAR:1770-07-06:0":{"b": ["Incendie de Çeşme", "840b30bd"], "d": ["La flotte russe, qui était entrée en Méditerranée avec le soutien des Anglais, attaqua avec des brûlots la flotte ottomane réfugiée dans le port de Çeşme et la brûla presque entièrement. La Russie apparaissait pour la première fois en Méditerranée comme grande puissance navale ; ce désastre fut l'un des coups qui décidèrent du sort de la guerre menant à Küçük Kaynarca en 1774, et mit en évidence la nécessité d'une réforme radicale de la flotte.", "5b133a56"]},
"OLAYLAR:1774-07-21:0":{"b": ["Traité de Küçük Kaynarca", "2776dcdb"], "d": ["Par Küçük Kaynarca, qui mit fin à la guerre de 1768–1774 et compte parmi les traités les plus lourds de l'histoire ottomane, le khanat de Crimée reçut l'« indépendance » — ce qui créait en fait une zone d'influence russe. La Russie s'établit sur la côte de la mer Noire et obtint pour ses navires marchands le droit de passage par les Détroits ainsi qu'une ambassade permanente à Istanbul ; la clause ambiguë de protection sur les sujets orthodoxes entrouvrit la porte aux prétextes d'intervention du siècle suivant. Pour la première fois, un territoire peuplé de musulmans sortait de la domination ottomane.", "b677ebfc"]},
"OLAYLAR:1783-04-19:0":{"b": ["Annexion de la Crimée par la Russie", "bdf6faa8"], "d": ["La Crimée « indépendante » créée par Küçük Kaynarca fut annexée à la Russie par le manifeste de Catherine II, sous prétexte des troubles survenus sous le dernier khan, Şahin Giray. L'association ottomano-criméenne de trois siècles prit fin ; la perte des steppes du Nord supprima la profondeur défensive d'Istanbul et déclencha la première grande vague d'émigration de dizaines de milliers de Tatars de Crimée vers les terres ottomanes.", "8d4fcb03"]},
"OLAYLAR:1789-04:0":{"b": ["Selim III et le Nizâm-ı Cedîd", "d53aec21"], "d": ["Selim III, monté sur le trône en pleine guerre, comprit que les défaites étaient structurelles et lança, sous le nom de « Nizâm-ı Cedîd » (Ordre nouveau), un vaste programme de réformes : une armée nouvelle exercée à l'européenne, un trésor distinct qui la finançait (Îrâd-ı Cedîd), le renforcement des écoles d'ingénieurs et les premières ambassades permanentes dans les capitales européennes. Le programme est considéré comme le début de la tradition réformatrice turque moderne ; mais, du fait de la résistance des corps (ocak) et des notables provinciaux (âyan), il devait être renversé en 1807.", "87394990"]},
"OLAYLAR:1798-06-12:0":{"b": ["Liquidation des chevaliers de Malte — étape de la flotte française en route", "d62f901d"], "d": ["La flotte française en route pour l'Égypte fit escale à Malte, sur son chemin ; les chevaliers de Saint-Jean (de Malte) remirent l'île sans grande résistance. Le dernier bastion de l'ordre de chevalerie, chassé de Rhodes en 1522 et établi ici, prenait ainsi fin. Malte devait passer aux mains de l'Angleterre deux ans plus tard, tandis que Napoléon se dirigeait de l'île directement vers Alexandrie.", "aac1fe49"]},
"OLAYLAR:1798-07-01:0":{"b": ["Invasion de l'Égypte par Napoléon", "93fede5f"], "d": ["L'armée du général Bonaparte débarqua à Alexandrie et envahit l'Égypte ; cette expédition, qui visait la route des Indes de l'Angleterre, fut la première attaque directe d'une puissance européenne contre les terres centrales de l'Empire ottoman. Le raid de Nelson à Aboukir et la défense d'Acre par Cezzâr Ahmed Pacha brisèrent la marche française ; l'occupation prit fin en 1801, mais dans le vide qu'elle laissa commencèrent l'ascension de Kavalalı Mehmed Ali Pacha et l'ère de la « Question d'Orient ».", "b1ca7226"]},
"OLAYLAR:1808-10-07:0":{"b": ["Pacte d'alliance (Sened-i İttifak)", "cce49ef5"], "d": ["Document signé entre le palais et les puissantes familles de notables provinciaux, sous la direction d'Alemdar Mustafa Pacha, âyan de Rusçuk qui avait porté Mahmud II sur le trône ; les âyan s'engageaient à la fidélité envers le sultan et à lui fournir des soldats, tandis que l'État reconnaissait leur existence et leurs droits. Comme il s'agit du premier exemple, dans l'histoire ottomane, d'une limitation de l'autorité du sultan par un document, certains historiens y voient le lointain commencement de la tradition constitutionnelle ; dans les faits, il devint inopérant en quelques mois.", "2d97fdfe"]},
"OLAYLAR:1821-03-25:0":{"b": ["Début de l'insurrection grecque", "a7293715"], "d": ["Le soulèvement préparé par l'organisation de la Philikí Etaireía éclata d'abord en Valachie, puis, avec sa force principale, en Morée ; l'État, occupé par l'affaire d'Ali Pacha de Tepelen, tarda à intervenir. Grâce à la vive sympathie des opinions publiques européennes pour les Grecs (philhellénisme), l'insurrection devint en peu de temps une cause internationale ; ainsi fut allumée la mèche du premier mouvement d'indépendance victorieux de l'ère des nationalismes sur les terres ottomanes. Autres établissements perdus à la même date : Athènes, Patras (Balyabadra), Thèbes (İstefe), Livadia.", "316e2ac7"]},
"OLAYLAR:1826-06-15:0":{"b": ["Vak'a-i Hayriyye — abolition du corps des janissaires", "08c9372a"], "d": ["Les janissaires, qui s'étaient mutinés (renversement des marmites) contre l'instruction du corps des Eşkinci nouvellement créé, furent anéantis à coups de canon, dans leurs casernes de l'Et Meydanı, par des troupes fidèles que Mahmud II avait préparées d'avance ; le corps fut aboli avec toutes ses branches et les tekkes bektachis qui lui étaient liés. Cette opération, entrée dans l'histoire sous le nom de « événement heureux », en liquidant une institution vieille de quatre siècles, ouvrit la voie à l'armée des Asâkir-i Mansûre-i Muhammediyye et à toutes les réformes centralisatrices qui suivirent.", "9ee152dd"]},
"OLAYLAR:1827-10-20:0":{"b": ["Bataille navale de Navarin", "ee579e7f"], "d": ["La flotte ottomano-égyptienne, qui réprimait l'insurrection grecque, fut incendiée à Navarin par la flotte combinée anglo-franco-russe entrée dans le port sans déclaration de guerre ; près de soixante navires et des milliers de marins furent perdus. Écartée par la diplomatie européenne comme un « événement fâcheux », l'attaque garantit de fait l'indépendance grecque et ouvrit la voie à la guerre russo-ottomane de 1828–1829.", "0d4b2c6f"]},
"OLAYLAR:1839-11-03:0":{"b": ["Édit du Tanzimat", "5042ce7b"], "d": ["Par le Hatt-ı Hümâyun lu à Gülhane, la sécurité de la vie, des biens et de l'honneur de tous les sujets, sans distinction de religion, fut placée sous la garantie de l'État ; furent proclamés les principes de justice dans l'impôt, d'ordre dans le service militaire et d'absence de peine sans jugement. L'édit, œuvre de Mustafa Reşid Pacha, est considéré comme le premier grand document à caractère constitutionnel de la modernisation ottomane et a donné son nom à l'ère de réformes du « Tanzimat » (1839–1876) ; une restructuration profonde de l'administration, du droit, de l'enseignement et des finances fut menée dans ce cadre.", "6ace4b82"]},
"OLAYLAR:1853-10-04:0":{"b": ["Début de la guerre de Crimée", "3b9ca3c8"], "d": ["La crise née de la question des Lieux saints et de la prétention de la Russie à protéger les sujets orthodoxes se transforma en conflit ouvert par la déclaration de guerre ottomane ; après l'attaque de Sinope, l'Angleterre et la France (puis le Piémont) entrèrent en guerre aux côtés des Ottomans. La guerre, qui fut gagnée grâce au débarquement des armées alliées en Crimée et à la prise de Sébastopol, s'acheva par le traité de Paris de 1856 ; mais le premier emprunt extérieur contracté pendant les années de guerre (1854) enferma l'Empire dans une spirale de dépendance financière qui devait durer un demi-siècle.", "bae16135"]},
"OLAYLAR:1856-02-18:0":{"b": ["Édit de réforme (Islahat Fermanı)", "78ff234d"], "d": ["L'édit, proclamé avant les négociations de paix de Paris, élargit les principes du Tanzimat et reconnut aux sujets non musulmans de larges droits d'égalité, y compris l'accès à la fonction publique, au service militaire et l'ouverture d'écoles ; les organisations communautaires furent réaménagées. Par le traité de Paris signé ensuite, l'État ottoman fut officiellement admis dans la famille du droit public européen et son intégrité territoriale fut placée sous la garantie collective des grandes puissances — garantie qui devait devenir, dans la pratique, une nouvelle porte ouverte aux interventions.", "cfe6d847"]},
"OLAYLAR:1876-12-23:0":{"b": ["Kanûn-ı Esâsî — première monarchie constitutionnelle", "0fe052c1"], "d": ["Le jour de l'ouverture de la conférence internationale réunie à Istanbul pour discuter de la crise balkanique, la première constitution ottomane fut proclamée à coups de canon ; par le Kanûn-ı Esâsî, œuvre du mouvement des « Nouveaux Ottomans » conduit par Midhat Pacha, un parlement à deux chambres fut institué. Le Meclis-i Meb'ûsan s'ouvrit en mars 1877 ; mais Abdülhamid II, invoquant la guerre de 93, ajourna l'assemblée sans limite de durée en février 1878, et la constitution resta suspendue pendant trente ans.", "c0f01a41"]},
"OLAYLAR:1877-04:0":{"b": ["Guerre de 93 (guerre russo-ottomane de 1877–1878)", "5bd96af7"], "d": ["Dans la guerre appelée « guerre de 93 » parce qu'elle coïncidait avec l'année 1293 du calendrier rûmî, les armées russes attaquèrent sur deux fronts ; bien que la défense de Plevna par Gazi Osman Pacha et les batailles du Caucase d'Ahmed Muhtar Pacha soient devenues légendaires, le front s'effondra et les Russes avancèrent jusqu'à Yeşilköy (San Stefano, Ayastefanos). La guerre déclencha de grandes vagues d'émigration musulmane des Balkans et du Caucase vers Istanbul, dont les effets se prolongent jusqu'à nos jours ; la structure démographique et financière de l'Empire ne retrouva jamais son état antérieur.", "3a2b2296"]},
"OLAYLAR:1878-07-13:0":{"b": ["Traité de Berlin", "47f76a49"], "d": ["Le Congrès de Berlin, qui révisa au nom de l'équilibre des grandes puissances la « Grande Bulgarie » créée par San Stefano (Ayastefanos), laissa néanmoins un tableau lourd : la Serbie, le Monténégro et la Roumanie devinrent indépendants ; la principauté autonome de Bulgarie fut créée ; la Bosnie-Herzégovine fut laissée à l'occupation autrichienne, Chypre à l'administration britannique, Kars-Ardahan-Batoum à la Russie. L'ordre ottoman cinq fois séculaire en Roumélie se dissolut en grande partie ; la « question d'Orient » devint un sujet permanent de la diplomatie européenne. Autres établissements perdus à la même date : Plovdiv (Filibe), Vidin, Tărnovo, Varna, Şumnu, Silistra, Roussé (Rusçuk), Bucarest, Iași (Yaş), Constanța (Köstence).", "076697b6"]},
"OLAYLAR:1881-05-12:0":{"b": ["Occupation de la Tunisie et Dette publique ottomane (Düyûn-ı Umûmiyye)", "c7e25598"], "d": ["La France, prenant prétexte d'incidents à la frontière algérienne, occupa la Tunisie et la plaça sous son protectorat par le traité du Bardo ; la présence ottomane en Afrique du Nord se réduisit à la Tripolitaine. Par le décret de Muharrem promulgué la même année, l'Administration de la Dette publique ottomane (Düyûn-ı Umûmiyye), où étaient représentés les créanciers, fut instituée pour gérer les dettes extérieures en faillite : des revenus essentiels tels que le sel, le tabac et la soie furent directement rattachés à cette administration étrangère, et la souveraineté financière fut gravement restreinte. Autres établissements perdus à la même date : Kairouan, Gabès, Sfax, Djerba.", "64f23b86"]},
"OLAYLAR:1882-09:0":{"b": ["Occupation britannique de l'Égypte", "f1269768"], "d": ["Le mouvement d'Urabi Pacha, qui s'était dressé en Égypte contre la faillite financière et le contrôle étranger, fut écrasé par la victoire de Tell el-Kébir de l'armée britannique débarquée après le bombardement d'Alexandrie, et Le Caire fut occupé. Bien que l'Égypte soit restée juridiquement rattachée à l'Empire ottoman, elle passa de fait sous administration britannique ; le contrôle du canal de Suez s'installa au centre de la stratégie impériale de la Grande-Bretagne.", "b7bcf2d2"]},
"OLAYLAR:1908-07-23:0":{"b": ["Proclamation de la seconde monarchie constitutionnelle", "95ee2fd2"], "d": ["Face au mouvement qui avait grandi lorsque des officiers liés au Comité Union et Progrès avaient pris le maquis en Macédoine, Abdülhamid II remit en vigueur le Kanûn-ı Esâsî ; la « proclamation de la liberté » fut accueillie avec enthousiasme et l'on alla aux élections. Mais la stabilité ne vint pas : après la répression de l'incident du 31 Mars (avril 1909), Abdülhamid fut déposé ; l'indépendance de la Bulgarie, l'annexion de la Bosnie et l'orientation de la Crète vers la Grèce eurent lieu elles aussi au cours de ces mois agités.", "370f359f"]},
"OLAYLAR:1911-09-29:0":{"b": ["Guerre de Tripolitaine", "ed441994"], "d": ["L'Italie, en quête de colonies, déclara la guerre à la Tripolitaine, dernière terre ottomane d'Afrique du Nord, et occupa les côtes ; l'État, privé de flotte, ne pouvant envoyer d'armée régulière, de jeunes officiers tels que Mustafa Kemal et Enver Bey gagnèrent secrètement la région et organisèrent avec les tribus senoussis une résistance efficace. Par le traité d'Ouchy (18 octobre 1912), signé à la suite du déclenchement de la guerre des Balkans, la Libye fut laissée à l'Italie ; l'Italie occupa en outre Rhodes et le Dodécanèse.", "9820482a"]},
"OLAYLAR:1913-05-30:0":{"b": ["Traité de Londres — perte de la Roumélie", "f3f976df"], "d": ["Par le traité de Londres, qui mit fin à la première guerre des Balkans, toutes les terres à l'ouest de la ligne Midye-Enez ainsi que les îles de l'Égée furent perdues ; l'Albanie devint indépendante. De la Roumélie, centre de gravité démographique, économique et culturel de l'Empire depuis plus de cinq cents ans, seule la Thrace orientale devait rester (Edirne fut reprise lors de la seconde guerre des Balkans) ; cette perte durcit de manière radicale la politique de guerre et de peuplement du gouvernement unioniste.", "077da59d"]},
"OLAYLAR:1914-11-01:0":{"b": ["Entrée dans la Première Guerre mondiale", "05a0252e"], "d": ["L'admission dans le détroit des cuirassés Goeben et Breslau, échappés devant les Anglais et présentés comme achetés, attira peu à peu l'État aux côtés de l'Allemagne ; la guerre commença de fait lorsque la flotte placée sous le commandement de l'amiral Souchon bombarda les ports russes (29 octobre), et les déclarations réciproques vinrent au début de novembre. Malgré la proclamation du Grand Djihad, l'effet attendu ne se produisit pas ; pendant quatre ans, l'Empire s'engagea dans une guerre d'existence sur cinq fronts distincts, du Caucase à la Palestine.", "a9f179e7"]},
"OLAYLAR:1915-03-18:0":{"b": ["Victoire des Dardanelles (Çanakkale)", "95d888e8"], "d": ["L'armada alliée, qui visait à faire tomber Istanbul et à joindre la Russie, fut repoussée du détroit le 18 mars par les lignes de mines et le feu des batteries ; la ligne posée par le mouilleur de mines Nusret décida du sort de la bataille. L'opération terrestre de Gallipoli, commencée en avril, fut elle aussi arrêtée à Anafartalar et à Conkbayırı ; les Alliés évacuèrent entièrement la péninsule en janvier 1916. Le nom du lieutenant-colonel Mustafa Kemal fut connu sur ce front ; cette victoire, acquise au prix d'environ un quart de million de martyrs et de disparus, est considérée comme le lieu de naissance des cadres et de l'esprit de la Lutte nationale.", "005303c3"]},
"OLAYLAR:1916-06-10:0":{"b": ["Révolte du chérif Hussein", "75f7c58c"], "d": ["L'émir de La Mecque, le chérif Hussein, se souleva à la suite de la correspondance secrète qu'il entretenait avec les Anglais, sur la promesse d'un royaume arabe indépendant ; le chemin de fer du Hedjaz devint la cible de raids. Bien que la légendaire défense de Médine par Fahreddin Pacha, qui se prolongea jusqu'après l'armistice, soit restée le symbole de la résistance, la révolte, conjuguée à l'avancée britannique sur le front de Palestine, hâta la dissolution de la domination ottomane dans les provinces arabes. Autres établissements perdus à la même date : Taïf.", "a0e859bd"]},
"OLAYLAR:1918-10-30:0":{"b": ["Armistice de Moudros", "9e87c767"], "d": ["L'État ottoman, dont les fronts avaient été coupés les uns des autres par l'effondrement de la Bulgarie, se retira de la guerre par l'armistice signé à bord du cuirassé Agamemnon. L'article 7, qui prévoyait l'ouverture des Détroits et permettait d'occuper les lieux dont la sécurité serait menacée, fut bientôt transformé en couverture juridique d'un partage de fait : Mossoul, Alexandrette, puis Izmir et Istanbul furent occupées. L'armistice est considéré comme l'acte de la fin de fait de l'Empire. Autres établissements perdus à la même date : Hama, Damas, Homs.", "261b57f2"]},
"OLAYLAR:1919-05-19:0":{"b": ["Mustafa Kemal à Samsun — Lutte nationale", "09a8f784"], "d": ["Dans le climat d'indignation créé par l'occupation d'Izmir, Mustafa Kemal Pacha, qui débarqua à Samsun en qualité d'inspecteur de la 9e armée, tourna sa mission officielle vers l'organisation de la résistance en Anatolie. La circulaire d'Amasya et les congrès d'Erzurum et de Sivas sont la suite de cette démarche ; le principe selon lequel « seuls la détermination et la décision de la nation sauveront l'indépendance de la nation » devint le noyau du programme politique de la Lutte nationale.", "330e4c51"]},
"OLAYLAR:1920-04:0":{"b": ["Ouverture de la Grande Assemblée nationale de Turquie et Sèvres", "2008feec"], "d": ["À la suite de l'occupation officielle d'Istanbul et de la dissolution du Meclis-i Meb'ûsan, la Grande Assemblée nationale s'ouvrit à Ankara le 23 avril 1920 ; réunissant en elle des pouvoirs extraordinaires, l'assemblée devint le noyau du nouvel État fondé sur la volonté nationale. Le traité de Sèvres, signé en août par le gouvernement d'Istanbul, partageait l'Anatolie ; la Grande Assemblée déclara traîtres à la patrie ceux qui l'avaient signé, et Sèvres ne put jamais être appliqué.", "9b4f7c0b"]},
"OLAYLAR:1921-09-13:0":{"b": ["Bataille de la Sakarya", "f2f970a6"], "d": ["L'offensive grecque, qui s'était approchée à 50 kilomètres d'Ankara, fut brisée lors du combat de 22 jours et 22 nuits mené par Mustafa Kemal Pacha, qui avait assumé le commandement en chef, selon l'ordre « il n'y a pas de ligne de défense, il y a une surface de défense ». L'armée grecque passa pour la première fois à la défensive stratégique ; la victoire valut à Mustafa Kemal les titres de gazi et de maréchal (müşir), et ouvrit la porte à l'accord d'Ankara avec la France ainsi qu'à la reconnaissance extérieure.", "f3372310"]},
"OLAYLAR:1922-09-09:0":{"b": ["Grande Offensive et libération d'Izmir", "172a50c4"], "d": ["L'offensive lancée le 26 août au matin depuis Kocatepe aboutit, le 30 août, à la destruction des forces principales grecques à Dumlupınar, lors de la bataille du Commandant en chef ; dans la poursuite menée selon l'ordre « Armées, votre premier objectif est la Méditerranée, en avant ! », Izmir fut libérée le 9 septembre. Par l'armistice de Mudanya (11 octobre), la Thrace orientale fut récupérée sans combat ; la victoire militaire détermina la force à la table des négociations du nouvel État qui serait établi à Lausanne.", "02bd94a5"]},
"OLAYLAR:1922-11-01:0":{"b": ["Abolition du sultanat", "9f36a9f6"], "d": ["À la suite de l'invitation adressée aussi au gouvernement d'Istanbul pour les négociations de Lausanne, la Grande Assemblée nationale sépara, le 1er novembre 1922, le sultanat du califat et abolit le sultanat ; le règne de la dynastie ottomane, long de 623 ans, prit fin juridiquement. Mehmed VI Vahideddin quitta le pays le 17 novembre à bord d'un cuirassé britannique ; par décision de la Grande Assemblée, Abdülmecid Efendi fut porté à la charge de calife, laquelle devait être abolie à son tour le 3 mars 1924.", "910b763d"]},
"OLAYLAR:1923-07-24:0":{"b": ["Traité de Lausanne", "38c27f7d"], "d": ["Par le traité de paix de Lausanne, signé au terme de huit mois de dures négociations, les frontières, la pleine indépendance et la souveraineté du nouvel État turc furent reconnues sur le plan international ; les capitulations furent abolies, la Dette publique ottomane fut engagée dans un processus de liquidation, et l'échange de populations fut réglé. Lausanne, qui annula de fait Sèvres, est considéré comme la victoire diplomatique de la Lutte nationale et comme le document extérieur fondateur de la République.", "6d498c3f"]},
"OLAYLAR:1923-10:0":{"b": ["Proclamation de la République", "d5bfcdfb"], "d": ["La République fut proclamée lorsque la Grande Assemblée nationale adopta, par une modification constitutionnelle, la disposition selon laquelle « la forme de gouvernement de l'État turc est la république » ; Mustafa Kemal Pacha fut élu premier président. L'aventure ottomane de 624 ans, commencée en 1299 comme principauté marchesque, se refermait ainsi ; un État nouveau, où la souveraineté appartient sans condition ni réserve à la nation, était fondé sur l'héritage de l'Empire.", "f5cabb8c"]},
"OLAYLAR_EK16:1922-02-28:0":{"b": ["La Grande-Bretagne mit fin à son protectorat sur l'Égypte et proclama son indépendance", "f8faab66"], "d": ["Par la déclaration du 28 février 1922, la Grande-Bretagne mit fin unilatéralement au protectorat en vigueur depuis 1914 et proclama l'Égypte État indépendant, en se réservant notamment la défense, les communications impériales et le Soudan. Deux semaines plus tard (15 mars 1922), le sultan Ahmed Fouad prit le titre de roi. Sur la carte, la couche d'occupation britannique sur les villes égyptiennes prend fin ce jour-là.", "8cde4005"]},
"OLAYLAR_EK16:1955-12-01:0":{"b": ["Les forces du sultan d'Oman entrèrent dans les principaux centres de l'Oman intérieur ; l'imamat ibadite prit fin de fait", "9a9962a5"], "d": ["En décembre 1955, le sultan d'Oman entreprit de rétablir son autorité et ses forces entrèrent dans les principaux centres habités de l'Oman intérieur (Bahla, Izki, Nizwa) ; la domination de l'imamat ibadite sur l'intérieur prit fin de fait. La source ne donne que le mois ; la carte affiche le 1er décembre 1955.", "31f8761e"]},
"OLAYLAR_EK16:1961-06-19:0":{"b": ["Le Koweït sortit de la protection britannique et devint pleinement indépendant", "e9a86d04"], "d": ["Par l'échange de notes du 19 juin 1961 entre le Koweït et le Royaume-Uni prit fin la protection britannique en vigueur depuis l'accord de 1899, et le Koweït devint pleinement indépendant. Sur la carte, la couche britannique sur le Koweït prend fin ce jour-là.", "eb64fb65"]},
"OLAYLAR_EK16:1971-09-03:0":{"b": ["Le Qatar proclama son indépendance à l'expiration de ses traités avec la Grande-Bretagne", "8f288cc6"], "d": ["Après la date d'expiration des traités de protection conclus avec la Grande-Bretagne, le Qatar proclama son indépendance le 3 septembre 1971. Sur la carte, la couche britannique sur Doha prend fin ce jour-là.", "997a4b35"]},
"OLAYLAR_EK2:1327-01-01:0":{"b": ["Frappe du premier akçe ottoman", "38d2d638"], "d": ["Le premier akçe d'argent frappé au nom d'Orhan Gazi est la proclamation monétaire de la souveraineté indépendante de la principauté ; l'akçe resta pendant cinq siècles l'unité monétaire de base.", "8729ab5b"]},
"OLAYLAR_EK2:1362-09-01:0":{"b": ["Création du beylerbeylik de Roumélie", "ffa16089"], "d": ["Les conquêtes de la rive européenne furent rassemblées sous un seul cadre militaire et administratif ; le régime du beylerbeylik devint l'ossature de l'organisation provinciale de l'Empire.", "9c13c8c3"]},
"OLAYLAR_EK2:1390-01-15:0":{"b": ["Mariage de Bayezid le Foudre et de Despina Hatun", "4b10dc6c"], "d": ["La vassalité établie avec le despotat serbe après Kosovo fut scellée par le mariage d'Olivera, fille de Lazar, avec Bayezid — exemple typique de la diplomatie matrimoniale des origines.", "7d87810a"]},
"OLAYLAR_EK2:1393-01-01:0":{"b": ["Création du beylerbeylik d'Anatolie", "5ef8d3a7"], "d": ["Le beylerbeylik d'Anatolie fut organisé pour administrer les terres des principautés annexées ; le système administratif à deux ailes, Roumélie-Anatolie, était achevé.", "55429c02"]},
"OLAYLAR_EK2:1399-06-01:0":{"b": ["Achèvement de la Grande Mosquée de Bursa (Ulu Camii)", "27bcc4a5"], "d": ["La grande mosquée à vingt coupoles, construite avec le butin de Nicopolis, est un monument de l'architecture ottomane des origines et un musée en plein air de l'art de la calligraphie.", "b0e811e6"]},
"OLAYLAR_EK2:1453-06-01:0":{"b": ["Destitution et exécution de Çandarlı Halil Pacha", "5e19438f"], "d": ["Après la conquête, le grand vizir issu de la vieille famille des Çandarlı, qui s'était tenu à distance du siège, fut exécuté ; pour la première fois un grand vizir était mis à mort sur ordre du sultan, et l'ère des vizirs d'origine devchirmé s'ouvrait.", "557b77f5"]},
"OLAYLAR_EK2:1456-06-01:0":{"b": ["Mise de la Moldavie sous tribut", "25bd3693"], "d": ["Le voïvodat de Moldavie accepta de payer tribut ; avec la Valachie et la Transylvanie, la triple ceinture vassale au nord du Danube devint le tampon septentrional de l'Empire. Autres lieux rattachés à la même date : Iași (Yaş).", "7cea09ea"]},
"OLAYLAR_EK2:1459-03-07:0":{"b": ["Tribut de Raguse (Dubrovnik)", "d127c78a"], "d": ["La république marchande de Raguse assura son autonomie et ses privilèges commerciaux en contrepartie d'un tribut ; elle s'enrichit comme fenêtre de l'Empire sur l'Adriatique. L'île de Mljet (Mliyet), terre de la république, partagea ce statut.", "812b9f2b"]},
"OLAYLAR_EK2:1462-06-01:0":{"b": ["Campagne de Valachie : Vlad l'Empaleur", "fd4530bb"], "d": ["La campagne menée contre Vlad Țepeș, qui avait refusé de payer le tribut et fait tuer les envoyés, ramena la Valachie à la vassalité ; l'attaque nocturne et les scènes d'horreur des empalements devinrent légendaires en Europe. Autres lieux rattachés à la même date : Bucarest.", "6ae089b4"]},
"OLAYLAR_EK2:1470-12-01:0":{"b": ["Inauguration du complexe Fatih (Fatih Külliyesi)", "a150ea55"], "d": ["Avec ses huit médersas (Sahn-ı Semân), le complexe fut la première grande étape du programme visant à faire d'Istanbul le centre savant du monde islamique.", "cbec7a2f"]},
"OLAYLAR_EK2:1472-01-01:0":{"b": ["Ali Kuşçu à Istanbul", "8508229d"], "d": ["Ali Kuşçu, dernier grand représentant de l'observatoire de Samarcande, devint, sur l'invitation du Conquérant, professeur à la médersa de Sainte-Sophie ; il fonda à Istanbul la tradition des mathématiques et de l'astronomie.", "fd325f60"]},
"OLAYLAR_EK2:1477-01-01:0":{"b": ["Kanunnâme de Mehmed le Conquérant (Fâtih Kanunnâmesi)", "b08944c9"], "d": ["Premier kanunnâme coutumier de grande ampleur, qui compile l'organisation de l'État, le protocole et les peines ; il est resté discuté pour son célèbre article autorisant le fratricide « pour l'ordre du monde » (nizâm-ı âlem).", "0e654de1"]},
"OLAYLAR_EK2:1478-06-01:0":{"b": ["Frappe de la première pièce d'or ottomane (sultani)", "2fd5c0dd"], "d": ["La première monnaie d'or ottomane, équivalente au ducat vénitien, fut frappée ; les finances de l'Empire entraient dans l'ordre monétaire international.", "cac00614"]},
"OLAYLAR_EK2:1478-09-01:0":{"b": ["Installation au palais de Topkapı", "b9cd6a5e"], "d": ["Avec l'achèvement du Nouveau Palais (Topkapı), le centre de l'administration de l'État y fut transféré ; le palais demeura pendant quatre siècles le cerveau de l'Empire.", "748ada37"]},
"OLAYLAR_EK2:1532-04-27:0":{"b": ["La République de Florence devient duché — Alessandro de' Medici", "c08764e1"], "d": ["Sous la pression du pape Clément VII, la commission de gouvernement de Florence (la Balìa) adopta une nouvelle constitution ; le régime républicain de cinq siècles fut supprimé et Alessandro de' Medici fut proclamé duc héréditaire, montant effectivement sur le trône le 1er mai. Florence passa ainsi de cité-république indépendante à duché héréditaire de la dynastie des Médicis.", "92da65c9"]},
"OLAYLAR_EK2:1534-01-01:0":{"b": ["Mariage de Soliman et de Hürrem Sultan", "abc05f26"], "d": ["Le mariage officiel de Soliman avec Hürrem changea radicalement la tradition du palais ; l'institution de la « Haseki Sultan » naquit et la porte de l'ère des femmes dans la politique dynastique s'ouvrit.", "db1f832b"]},
"OLAYLAR_EK2:1536-02-18:0":{"b": ["Premières capitulations étendues en faveur de la France", "e2264e48"], "d": ["Dans le cadre de l'alliance française contre l'étau des Habsbourg, des privilèges commerciaux furent signés entre Jean de La Forêt et Makbul İbrâhim Pacha ; les capitulations, alors instrument diplomatique, devaient au fil des siècles se transformer en porte de la dépendance financière.", "e7c6fd84"]},
"OLAYLAR_EK2:1538-06-13:0":{"b": ["Expédition de l'océan Indien : siège de Diu", "fcd1217a"], "d": ["La flotte partie de Suez traversa la mer Rouge et assiégea Diu, au Gujarat ; bien que la forteresse n'ait pu être prise, la puissance ottomane s'étendit pour la première fois à l'océan Indien et le monopole portugais fut ébranlé.", "ce118bf7"]},
"OLAYLAR_EK2:1553-12-07:0":{"b": ["Voyage de Seydi Ali Reis aux Indes", "e5da3b2c"], "d": ["Seydi Ali Reis, chargé de ramener en Égypte la flotte de Bassora, fut emporté par les tempêtes jusqu'aux Indes ; le Mir'âtü'l-memâlik, où il raconte l'aventure de son retour, est l'un des premiers récits de voyage ottomans.", "bb472cec"]},
"OLAYLAR_EK2:1554-01-01:0":{"b": ["Exécution de Pîrî Reis", "63026444"], "d": ["Le grand marin et cartographe, qui était revenu de la campagne d'Ormuz en laissant la flotte à Bassora, fut exécuté à l'âge de 84 ans — l'une des décisions les plus discutées de notre histoire des sciences.", "e3d1ac3f"]},
"OLAYLAR_EK2:1557-10-16:0":{"b": ["Inauguration du complexe de la Süleymaniye", "1c6458b2"], "d": ["Le complexe que l'architecte Sinan appelait son « œuvre de compagnon » devint, avec ses médersas, son hôpital (dârüşşifâ) et sa bibliothèque, le plus grand complexe d'enseignement et de bienfaisance de l'époque classique.", "0c203c6b"]},
"OLAYLAR_EK2:1565-05-18:0":{"b": ["Siège de Malte", "f57f6a85"], "d": ["Malte, verrou de la Méditerranée, fut assiégée pendant quatre mois ; Turgut Reis tomba en martyr et le siège fut levé. Ce fut le premier grand recul de la marine de l'époque de Soliman.", "860ee1bc"]},
"OLAYLAR_EK2:1575-03-01:0":{"b": ["Achèvement de la mosquée Selimiye", "3b0484e1"], "d": ["La Selimiye, que Sinan appelait son « œuvre de maître » et où une coupole unique domine l'espace, est considérée comme le sommet de l'architecture classique ottomane (patrimoine mondial de l'UNESCO).", "9d7cd43c"]},
"OLAYLAR_EK2:1577-01-01:0":{"b": ["Fondation de l'observatoire d'Istanbul", "169bdf5d"], "d": ["L'observatoire de Takiyyüddin, l'un des mieux équipés de l'époque, fut démoli en 1580 à la suite des controverses nées après la comète de 1577 ; l'astronomie institutionnelle prit trois siècles de retard.", "7fb471aa"]},
"OLAYLAR_EK2:1578-08-09:0":{"b": ["Victoire de Çıldır — début de la guerre à l'est", "13125a54"], "d": ["Avec la défaite de l'armée séfévide à Çıldır, les portes du Caucase s'ouvrirent ; Tiflis fut prise et la Géorgie passa sous la domination ottomane.", "0bf34d05"]},
"OLAYLAR_EK2:1583-05-09:0":{"b": ["Bataille des Torches — le Širvan définitivement ottoman", "3bbc23bc"], "d": ["Dans la bataille appelée ainsi parce qu'elle se poursuivit la nuit à la lueur des torches, les Séfévides furent définitivement vaincus ; la domination ottomane sur le Širvan et sur Bakou fut consolidée.", "e2aa6d1e"]},
"OLAYLAR_EK2:1585-01-01:0":{"b": ["Grande dévaluation — crise de l'akçe", "9205c3d4"], "d": ["Sous la pression des longues guerres et de l'argent américain, la teneur en argent de l'akçe fut réduite de moitié ; la révolution des prix alimenta la dissolution du système des sipahis et les troubles djelalis.", "bd2a508f"]},
"OLAYLAR_EK2:1585-09-25:0":{"b": ["Prise de Tabriz", "6506bdb9"], "d": ["Le sérasquier Özdemiroğlu Osman Pacha entra à Tabriz ; l'ancienne capitale des Séfévides fut placée sous administration ottomane. Osman Pacha mourut au camp quelques semaines plus tard.", "e54b35bd"]},
"OLAYLAR_EK2:1590-03-21:0":{"b": ["Traité de Ferhad Pacha — frontières les plus étendues à l'est", "c429972f"], "d": ["Par le traité conclu après l'arrivée à Istanbul de l'envoyé du chah Abbas, Haydar Mirza (18 janvier 1590), à la condition que les lieux conquis restent aux Ottomans, et qui mit fin à une guerre de 12 ans, Tabriz, le Karabagh, le Širvan, la Géorgie et le Luristan restèrent à l'Empire ottoman ; l'Empire atteignit à l'est les frontières les plus étendues de son histoire.", "41d8b058"]},
"OLAYLAR_EK2:1603-10-21:0":{"b": ["Début de la guerre ottomano-séfévide (1603-1612) — contre-offensive du chah Abbas, perte de Tabriz", "abf27dd8"], "d": ["Le chah Abbas, qui avait réorganisé son armée, passa à l'offensive en profitant des troubles djelalis ; Tabriz tomba et les acquisitions du Caucase furent perdues en quelques années. Autres établissements perdus lors de cette campagne et ensuite : Nakhitchevan, Khoy, Marand, Salmas ; les beys de Karadagh (Ahar) et du Mukri passèrent eux aussi du côté séfévide.", "b1757da9"]},
"OLAYLAR_EK2:1611-03-25:0":{"b": ["Naissance d'Evliya Çelebi", "2b6051ff"], "d": ["Evliya Çelebi, qui rassembla plus de cinquante ans de voyages dans le Seyahatnâme en dix volumes, laissa un panorama inégalé du monde ottoman du XVIIe siècle.", "bbd451a3"]},
"OLAYLAR_EK2:1612-11-20:0":{"b": ["Traité de Nasuh Pacha", "bb69e388"], "d": ["Par le traité qui mit fin à la guerre en cours depuis 1603, les gains de 1590 furent abandonnés et l'on revint à la frontière d'Amasya de 1555 ; l'équilibre fut rétabli sur le front oriental.", "f3ce47a7"]},
"OLAYLAR_EK2:1616-06-09:0":{"b": ["Inauguration de la mosquée du sultan Ahmed", "e39dfd43"], "d": ["Avec ses six minarets et ses faïences bleues d'Iznik, la « Mosquée bleue » est le dernier grand complexe sultanien de l'époque classique.", "c3e55fc5"]},
"OLAYLAR_EK2:1648-08-18:0":{"b": ["Assassinat du sultan Ibrahim", "bc4eb452"], "d": ["Pour cause de prodigalité et de crise de gouvernement, l'alliance des corps et des oulémas déposa Ibrahim sur le trône ; dix jours plus tard, il fut étranglé en vertu d'une fatwa. Mehmed IV, âgé de sept ans, monta sur le trône ; le pouvoir passa de fait aux mains de la grande validé Kösem Sultan.", "b90693f4"]},
"OLAYLAR_EK2:1657-10-06:0":{"b": ["Mort de Kâtib Çelebi", "e167e89d"], "d": ["Auteur de la bibliographie Keşfü'z-zunûn et de la géographie Cihannümâ, figure majeure de l'histoire du savoir ottoman ; il est connu pour sa démarche pionnière utilisant les sources européennes.", "786ec8d5"]},
"OLAYLAR_EK2:1703-08-22:0":{"b": ["Incident d'Edirne — déposition de Mustafa II", "0291c1cd"], "d": ["La colère suscitée par le séjour du sultan à Edirne et par l'influence de Feyzullah Efendi se transforma en un grand soulèvement de l'armée et des corporations ; le şeyhülislam fut lynché, le sultan fut déposé et le palais retourna à Istanbul.", "e8740499"]},
"OLAYLAR_EK2:1720-10-08:0":{"b": ["Ambassadeur à Paris : Yirmisekiz Mehmed Çelebi", "26312a3f"], "d": ["La grande ambassade envoyée en France fut la première observation systématique de l'Occident faite sur place ; son Sefâretnâme inspira le renouveau de l'Ère des tulipes.", "aa11c96a"]},
"OLAYLAR_EK2:1727-07-05:0":{"b": ["Fondation de la première imprimerie ottomane", "4943f7e5"], "d": ["L'autorisation d'imprimer des livres en turc fut accordée ; la première œuvre, le Vankulu Lügati, fut imprimée en 1729. L'imprimerie est l'héritage le plus durable du renouveau de l'Ère des tulipes.", "a33e45d0"]},
"OLAYLAR_EK2:1740-05-30:0":{"b": ["Les capitulations rendues permanentes", "d044a79e"], "d": ["Les privilèges accordés à la France cessèrent d'être limités à la personne du sultan et furent liés à un traité permanent ; le régime des capitulations, devenu impossible à dénoncer unilatéralement, ne put être aboli qu'à Lausanne.", "d50899dc"]},
"OLAYLAR_EK2:1773-01-01:0":{"b": ["Fondation de la Mühendishâne-i Bahrî-i Hümâyun", "9bf3f439"], "d": ["Fondée après le désastre de Çeşme pour former des officiers de marine modernes, l'école d'ingénieurs est la première institution durable d'enseignement technique à l'occidentale ; l'école d'ingénieurs de l'armée de terre suivit en 1795.", "b73b2ce6"]},
"OLAYLAR_EK2:1793-06-01:0":{"b": ["Première ambassade permanente à Londres", "6b5630eb"], "d": ["Dans le cadre du programme du Nizâm-ı Cedîd, des ambassades permanentes furent ouvertes dans les capitales européennes ; la diplomatie ottomane passa au principe de réciprocité.", "0321b899"]},
"OLAYLAR_EK2:1808-11-16:0":{"b": ["Mort d'Alemdar Mustafa Pacha", "4426534e"], "d": ["Assiégé à la Sublime Porte lors de la révolte des janissaires commencée dans la nuit du 15 novembre 1808, le grand vizir réformateur, le secours attendu n'étant pas venu, fit sauter le lendemain l'arsenal et mourut avec des centaines d'assaillants ; le régime du Sened-i İttifak et la première tentative de réforme furent enterrés avec lui.", "04420a26"]},
"OLAYLAR_EK2:1831-11-01:0":{"b": ["Premier journal officiel : Takvîm-i Vekāyi", "c637f623"], "d": ["Le journal officiel de l'État commença à paraître ; il marque le début de la tradition de l'opinion publique moderne et de la communication officielle.", "b4f1f627"]},
"OLAYLAR_EK2:1838-08-16:0":{"b": ["Traité de commerce de Balta Limanı", "e790b383"], "d": ["À l'Angleterre fut reconnue la position la plus privilégiée, même dans le commerce intérieur, et le système du yed-i vahit (monopole) fut aboli ; tandis que la production locale restait sans protection, le traité devint le document de l'ouverture complète du marché ottoman au libre-échange.", "14089a77"]},
"OLAYLAR_EK2:1842-01-01:0":{"b": ["Fin de l'émirat du Liban — destitution de Bachir III Chéhab", "f85ae454"], "d": ["L'émir Bachir II (III), incapable de contrôler la querelle entre chrétiens et Druzes et les équilibres internes de la région du Chouf, fut destitué en janvier 1842 ; le régime émiral local en vigueur depuis 1516 (par les Maan puis par les Chéhab) prit fin, et la région passa à l'administration ottomane directe, puis au système de la double caïmacamie.", "205abc18"]},
"OLAYLAR_EK2:1844-01-01:0":{"b": ["Tashîh-i sikke : le régime du Mecidiye", "c77be809"], "d": ["Par la réforme monétaire, les pièces dont le titre avait été altéré furent retirées ; un régime stable bimétallique fondé sur la livre d'or (Mecidiye) fut établi.", "e0642ec8"]},
"OLAYLAR_EK2:1850-01-01:0":{"b": ["Fin de la domination locale de la famille Harfûş à Baalbek", "8438f4ae"], "d": ["L'influence de la famille Harfûş, qui régnait à Baalbek depuis 1521 (après la révolte de Canbirdi Gazâlî) comme petite dynastie locale, prit fin avec le nouveau règlement administratif de la Sublime Porte ; la ville fut ramenée au rang de simple chef-lieu de caza rattaché au vilayet de Damas.", "106eabb2"]},
"OLAYLAR_EK2:1851-01-01:0":{"b": ["Fondation de la Şirket-i Hayriyye", "462830e7"], "d": ["La compagnie fondée pour exploiter des bateaux à vapeur sur le Bosphore est considérée comme la première société anonyme ottomane ; les embarcadères des vapeurs marquèrent la vie de la ville.", "b4203b61"]},
"OLAYLAR_EK2:1854-08-24:0":{"b": ["Premier contrat d'emprunt extérieur", "9017c579"], "d": ["Pour financer la guerre de Crimée, le premier emprunt extérieur fut contracté sur le marché de Londres ; le point auquel on parvint avec 15 emprunts en 21 ans fut le moratoire de 1875 et la Dette publique ottomane (Düyûn-ı Umûmiyye).", "1c4f9949"]},
"OLAYLAR_EK2:1855-09-14:0":{"b": ["La ligne télégraphique à Istanbul", "d320f39f"], "d": ["La première ligne télégraphique, établie pour les besoins de la guerre de Crimée, fut ouverte à l'exploitation ; en quelques décennies, l'Empire se dota de l'un des plus vastes réseaux télégraphiques du monde.", "f59439a3"]},
"OLAYLAR_EK2:1858-06-06:0":{"b": ["Code foncier (Arazi Kanunnâmesi)", "6bae243a"], "d": ["Le kanunnâme qui modernisa le droit foncier lia au registre foncier (tapu) la jouissance effective des terres mîrî ; il est l'un des documents fondamentaux du régime de la propriété du Moyen-Orient actuel.", "395494dc"]},
"OLAYLAR_EK2:1863-01-13:0":{"b": ["Premiers cours au Dârülfünun", "08f74066"], "d": ["Le Dârülfünun, appelé à dispenser un enseignement de niveau universitaire, commença à fonctionner par des cours publics ; l'institution, qui se poursuivit avec des interruptions, fut ouverte durablement en 1900 et devint le noyau de l'Université d'Istanbul.", "6218d070"]},
"OLAYLAR_EK2:1864-11-08:0":{"b": ["Règlement des vilayets (Vilâyet Nizamnâmesi)", "ad20853b"], "d": ["L'organisation en vilayets, sur le modèle français, fut établie à la place du régime des eyalets ; prenant pour exemple l'application de Midhat Pacha dans le vilayet du Danube, elle fut étendue à tout le pays.", "665b97d3"]},
"OLAYLAR_EK2:1867-06-21:0":{"b": ["Voyage d'Abdülaziz en Europe", "9ff0fa1e"], "d": ["Premier voyage en Europe d'un sultan ottoman à des fins pacifiques ; l'Exposition de Paris et les visites à Londres servirent à la fois de vitrine diplomatique et de vitrine de la modernisation.", "bd58ae5d"]},
"OLAYLAR_EK2:1868-09-01:0":{"b": ["Ouverture du Galatasaray Mekteb-i Sultânîsi", "f9688524"], "d": ["Le lycée dispensant un enseignement en français devint, par la composition de ses élèves sans distinction de religion ni de communauté, le symbole de l'idéal d'égalité dans l'éducation du Tanzimat.", "c9d5821d"]},
"OLAYLAR_EK2:1869-04-01:0":{"b": ["Entrée en vigueur du premier livre de la Mecelle", "6475461c"], "d": ["La Mecelle, qui compila par une technique législative moderne le domaine des obligations et des biens du droit islamique, est considérée comme le premier code civil islamique ; la commission présidée par Cevdet Pacha acheva les 16 livres en 1876.", "9669c96e"]},
"OLAYLAR_EK2:1876-05-30:0":{"b": ["Déposition d'Abdülaziz", "eb7397ea"], "d": ["Des hommes d'État constitutionnalistes et des chefs militaires déposèrent Abdülaziz par un coup d'État silencieux ; sa mort suspecte, cinq jours plus tard, puis les événements de Çırağan qui suivirent donnèrent naissance à des règlements de comptes qui durèrent des années.", "9523e81b"]},
"OLAYLAR_EK2:1878-05-20:0":{"b": ["Raid de Çırağan (affaire Ali Suâvi)", "d2a9ac87"], "d": ["Le journaliste Ali Suâvi attaqua le palais de Çırağan pour remettre Murad V sur le trône ; le raid fut réprimé dans le sang, et le régime d'Abdülhamid resserra durablement son cercle de sécurité.", "8bd8ba3f"]},
"OLAYLAR_EK2:1884-01-01:0":{"b": ["Création de la Régie (monopole du tabac)", "bad9b030"], "d": ["Les revenus du tabac furent cédés à la société de la Régie, à capitaux étrangers, rattachée à la Dette publique ottomane (Düyûn-ı Umûmiyye) ; les affrontements de la « contrebande de la Régie » entre paysans et gardes se prolongèrent pendant des décennies. Autres établissements perdus à la même date : Zeila.", "19e84e39"]},
"OLAYLAR_EK2:1898-10-18:0":{"b": ["Visite de l'empereur Guillaume II à Istanbul et à Jérusalem", "2988cd06"], "d": ["La seconde visite de l'empereur allemand scella le rapprochement ottomano-allemand ; la voie de la concession du chemin de fer de Bagdad fut ouverte, et à Damas fut prononcé le discours sur « l'ami de trois cents millions de musulmans ».", "2e385229"]},
"OLAYLAR_EK2:1908-09-01:0":{"b": ["Le chemin de fer du Hedjaz à Médine", "95009b9c"], "d": ["La ligne de 1464 km, construite uniquement avec des dons musulmans et par une ingénierie locale, atteignit Médine ; le voyage du pèlerinage passa de semaines à quelques jours. C'est la plus grande œuvre d'infrastructure de l'époque d'Abdülhamid II.", "a1c98c4c"]},
"OLAYLAR_EK2:1909-04-13:0":{"b": ["Incident du 31 Mars", "1d7c2bb2"], "d": ["Le grand soulèvement hostile à la monarchie constitutionnelle s'empara d'Istanbul ; l'Armée d'action (Hareket Ordusu), venue de Thessalonique, réprima la révolte et Abdülhamid II fut déposé.", "4885dfd1"]},
"OLAYLAR_EK2:1912-10-26:0":{"b": ["Début du siège d'Edirne", "234d9b28"], "d": ["La défense de cinq mois de Şükrü Pacha devint l'épopée de la résistance dans la catastrophe balkanique ; la ville tomba par la famine et fut reprise en juillet 1913.", "3c3ca395"]},
"OLAYLAR_EK2:1913-01-23:0":{"b": ["Raid contre la Sublime Porte (Bâb-ı Âli)", "b304d02d"], "d": ["Le gouvernement, qui se préparait à remettre Edirne, fut renversé par le raid armé des unionistes ; le ministre de la Guerre Nâzım Pacha fut tué. L'époque du plein pouvoir du Comité Union et Progrès commençait.", "a8a7af44"]},
"OLAYLAR_EK2:1915-07-11:0":{"b": ["Abolition de la moutasarrifiyya du Mont-Liban", "b5639051"], "d": ["Le régime de moutasarrifiyya autonome, fondé sur le Règlement organique de 1861 et sur le protocole international renouvelé en 1864, fut dénoncé unilatéralement par l'État ottoman pendant la Première Guerre mondiale ; le ministère de l'Intérieur commença à nommer directement dans la région des moutasarrifs musulmans. La période d'autonomie de 1861-1915, durant laquelle huit moutasarrifs exercèrent, se refermait ainsi.", "83ff35bc"]},
"OLAYLAR_EK3:1402-08-01:0":{"b": ["Partage du pays entre les princes", "82f26bfb"], "d": ["Après la déroute d'Ankara, Süleyman Çelebi passa en Roumélie et se proclama sultan à Edirne ; İsa Çelebi tint Bursa, et Çelebi Mehmed la région d'Amasya-Tokat-Sivas. Sur la carte, ces trois parts sont figurées en couleurs distinctes.", "08baaa0b"]},
"OLAYLAR_EK3:1403-02-01:0":{"b": ["Traité de Gallipoli : la côte de la mer Noire jusqu'à Misivri laissée à Byzance", "a4164eca"], "d": ["Après la déroute d'Ankara, l'émir Süleyman, qui voulait se maintenir en Roumélie, signa à Gallipoli un traité avec l'empereur byzantin Manuel. Il abandonna à Byzance Kartal, Pendik et Gebze ainsi que certaines îles, en Roumélie Thessalonique et la Thessalie, et sur la mer Noire la bande littorale s'étendant jusqu'à Misivri (Mésembrie) ; le tribut que Byzance payait aux Ottomans fut aussi supprimé. Ahtapolu, İğneada et Rezve, sur la côte de la Strandja (Istıranca), restèrent ainsi vingt et un ans sous administration byzantine ; Murad II reprit la plupart de ces lieux par la paix de 1424.", "ad1af28a"]},
"OLAYLAR_EK3:1403-03-09:0":{"b": ["Mort de Bayezid le Foudre en captivité", "7e968d83"], "d": ["Le sultan, prisonnier de Tamerlan, mourut à Akşehir ; sa dépouille fut ramenée à Bursa et inhumée. Sa mort rendit irréversible la lutte pour le trône entre les princes.", "af68bc4d"]},
"OLAYLAR_EK3:1403-06-15:0":{"b": ["Traité de Gallipoli — concessions à Byzance", "dfacbd00"], "d": ["Süleyman Çelebi, désireux d'assurer sa position en Roumélie, s'entendit avec Byzance et les États latins et restitua Thessalonique, les rivages de la Marmara et certaines îles ; il accepta même de payer tribut.", "0d91820c"]},
"OLAYLAR_EK3:1403-09-01:0":{"b": ["Combat d'Ulubat — défaite d'İsa Çelebi", "500c5d24"], "d": ["İsa Çelebi, qui tenait Bursa, fut vaincu à Ulubat par son frère Mehmed ; plusieurs tentatives de redressement restèrent aussi sans résultat.", "624072ce"]},
"OLAYLAR_EK3:1406-06-01:0":{"b": ["Disparition d'İsa Çelebi", "0effa11e"], "d": ["İsa Çelebi, qui était retourné plusieurs fois en Anatolie avec le soutien de Süleyman Çelebi, disparut après sa dernière défaite ; sa part passa à Çelebi Mehmed, et sur la carte le domaine de Mehmed s'étendit vers l'ouest.", "d164b447"]},
"OLAYLAR_EK3:1406-06-18:0":{"b": ["Musa Çelebi passe en Valachie", "8441267a"], "d": ["Çelebi Mehmed, qui avait perdu Bursa et Ankara face à Süleyman Çelebi et s'était replié sur Tokat-Amasya, encouragea son frère Musa à partir pour la Roumélie. Musa, acceptant l'invitation du voïvode de Valachie Mircea, atteignit la Valachie par mer ; de là, il devait engager une lutte qui placerait Süleyman entre deux fronts.", "e7866931"]},
"OLAYLAR_EK3:1410-05-06:0":{"b": ["Çelebi Mehmed reprend Bursa et Ankara — la part anatolienne échappe à Süleyman Çelebi", "bfb69f12"], "d": ["À la suite des succès de Mûsâ Çelebi en Roumélie (Yambol, 13 février 1410), l'émir Süleyman Çelebi, qui se trouvait en Anatolie, passa en Roumélie. Après le départ de Süleyman d'Anatolie, Mehmed Çelebi reprit la région de Bursa, Ankara comprise, et, en signe de son accession au trône, fit frapper une monnaie datée de 813. Sur la carte, la rive anatolienne de la Marmara passe de la part de l'émir Süleyman à la couleur de Çelebi Mehmed.", "bc148b8e"]},
"OLAYLAR_EK3:1410-06-15:0":{"b": ["Bataille de Kosmidion", "0efc2caa"], "d": ["Dans la bataille livrée devant les murailles de Constantinople avec le soutien de Byzance, Süleyman Çelebi vainquit son frère Musa ; mais son soutien en Roumélie avait commencé à fondre rapidement.", "ece5fe6b"]},
"OLAYLAR_EK3:1411-01-01:0":{"b": ["Siège de Constantinople par Musa Çelebi", "4932f586"], "d": ["Musa Çelebi, qui voulait punir Byzance d'avoir soutenu Süleyman, assiégea Constantinople ; ce siège poussa Byzance à s'allier avec Çelebi Mehmed.", "b52f942c"]},
"OLAYLAR_EK3:1411-02-17:0":{"b": ["Mort de l'émir Süleyman — Musa maître de la Roumélie", "325c1549"], "d": ["Süleyman Çelebi, capturé alors qu'il fuyait Edirne, fut tué ; toute la Roumélie passa aux mains de Musa Çelebi. Sur la carte, la Roumélie passe du bleu au violet.", "48aa849a"]},
"OLAYLAR_EK3:1413-07-05:0":{"b": ["Bataille de Çamurlu — rétablissement de l'unité", "0b23173e"], "d": ["Çelebi Mehmed, qui avait obtenu l'appui de Byzance, du despotat serbe et des beys de Roumélie, infligea une défaite décisive à son frère Musa à Çamurlu ; Musa fut tué dans sa fuite. La Roumélie que tenait Musa passa à Mehmed avec Edirne, et Mehmed Çelebi se proclama à Edirne seul souverain de l'État ottoman. L'Interrègne de onze ans prit fin, et les parts princières de la carte furent réunies en un seul corps.", "649e53b7"]},
"OLAYLAR_EK3:1683-01-01:0":{"b": ["Décision de la campagne de Vienne — la paix de Vasvár n'est pas renouvelée, l'objectif passe de Győr (Yanıkkale) à Vienne", "1bf278f2"], "d": ["L'empereur Léopold Ier voulait renouveler le traité de Vasvár, dont le terme n'était pas encore échu, et Mehmed IV semblait lui aussi favorable à la paix. Mais le grand vizir Merzifonlu Kara Mustafa Pacha, invoquant les plaintes d'Imre Thököly, qu'il avait fait proclamer roi de Hongrie centrale, ne laissa pas renouveler la paix ; il mit en mouvement les prédicateurs, au premier rang desquels Vânî Mehmed Efendi, et convainquit le sultan de faire la guerre. Au conseil tenu, il fut décidé que le sultan resterait à Belgrade et que le serdâr-ı ekrem avancerait pour prendre Győr (Yanıkkale) ; mais lors du conseil de Székesfehérvár (İstolni Belgrad), malgré l'opposition du khan de Crimée Murad Giray et du gouverneur de Bude Uzun İbrâhim Pacha, l'objectif fut changé en siège de Vienne.", "7a572168"]},
"OLAYLAR_EK3:1683-07-14:0":{"b": ["Début du second siège de Vienne — l'armée devant Vienne", "bb542e49"], "d": ["L'armée ottomane commandée par le grand vizir Kara Mustafa Pacha arriva devant Vienne le 14 juillet 1683. L'empereur Léopold Ier laissa la défense de la ville à Starhemberg et se retira à l'intérieur de l'Autriche. Ce second siège, préparé contrairement au premier en visant directement Vienne, devait durer jusqu'au 12 septembre.", "ecea5576"]},
"OLAYLAR_EK3:1683-10-09:0":{"b": ["Déroute de Párkány (Parkan) et perte d'Esztergom", "a7366740"], "d": ["L'armée qui se retirait de Vienne fut mise en déroute une seconde fois à Párkány ; puis Esztergom, une des forteresses clés de la Hongrie, tomba. La retraite commençait à tourner à l'effondrement.", "13a860f4"]},
"OLAYLAR_EK3:1683-12-25:0":{"b": ["Exécution de Merzifonlu Kara Mustafa Pacha", "ce8b10ac"], "d": ["Le grand vizir, tenu pour responsable de la déroute de Vienne, fut étranglé à Belgrade ; mais son exécution ne redressa pas le front ni ne rendit à l'État son prestige ébranlé.", "23449e61"]},
"OLAYLAR_EK3:1684-03-05:0":{"b": ["Formation de la Sainte-Ligue", "060280d0"], "d": ["Sous la direction de la papauté, la Sainte-Ligue (Mukaddes İttifak) fut formée contre l'Empire ottoman entre l'Autriche, la Pologne et Venise ; la Russie s'y joignit en 1686. L'Empire entrait ainsi dans une guerre sur plusieurs fronts qui devait durer seize ans.", "5f02a851"]},
"OLAYLAR_EK3:1684-07-14:0":{"b": ["Première défense de Bude", "ccc43630"], "d": ["Le premier siège de Bude par l'armée de la Sainte-Ligue fut repoussé par la défense acharnée de quatre mois de la forteresse ; mais les forteresses de Hongrie continuaient à tomber une à une.", "fb62dd75"]},
"OLAYLAR_EK3:1685-08-19:0":{"b": ["Perte d'Uyvar", "689ab78c"], "d": ["La forteresse d'Uyvar, restée vingt-deux ans aux mains des Ottomans et devenue proverbiale en Europe, tomba ; la présence ottomane en Haute-Hongrie se dissolvait.", "559f5062"]},
"OLAYLAR_EK3:1685-10-15:0":{"b": ["Arrestation de Thököly à Oradea (Varad) — dissolution du royaume de Hongrie centrale, reddition des forteresses de Haute-Hongrie", "1741aaaf"], "d": ["Après la déroute de Vienne, les Ottomans avaient commencé à compter Thököly parmi les responsables de la guerre et de la défaite. Le 15 octobre 1685, sur l'ordre du sérasquier Melek İbrâhim Pacha, le beylerbey de Varad, Ahmed Pacha, fit arrêter Thököly, venu à son secours ; on espérait, en le livrant aux Habsbourg, obtenir de meilleures conditions de paix. Quand la nouvelle de l'arrestation se répandit, toutes les forteresses et villes du royaume de Hongrie centrale, à l'exception de Munkács, défendue par son épouse Ilona Zrínyi, se rendirent aux Habsbourg ; la plupart des soldats kuruc passèrent dans l'armée des Habsbourg. Quand Thököly fut libéré à Belgrade, le 2 janvier 1686, le royaume avait cessé d'exister.", "1a00b9f3"]},
"OLAYLAR_EK3:1686-09-02:0":{"b": ["Perte de Bude — capitale hongroise de 145 ans", "70800e2b"], "d": ["Bude tomba au terme d'un siège de soixante-dix-huit jours ; le dernier beylerbey, Abdurrahman Abdi Pacha, tomba en martyr sur les remparts. La perte de la ville, sous administration ottomane depuis 1541, est considérée comme le symbole de la perte de la Hongrie. Autres établissements perdus à la même date : Pest (Peşte).", "e66f909f"]},
"OLAYLAR_EK3:1687-08-12:0":{"b": ["Seconde déroute de Mohács (Harsány) — perte de la Transylvanie et de Mohács", "a7922681"], "d": ["Dans la plaine où avait été remportée la grande victoire de 1526, une lourde défaite fut cette fois subie ; l'armée se dispersa, les soldats révoltés firent destituer le grand vizir. La défaite entraîna aussi la perte de la Transylvanie.", "6b95b7d0"]},
"OLAYLAR_EK3:1687-09-26:0":{"b": ["Perte d'Athènes et explosion du Parthénon", "b6691730"], "d": ["Une bombe lancée par l'artillerie vénitienne fit sauter le Parthénon, que les Ottomans utilisaient comme dépôt de munitions ; le temple vieux de deux mille ans fut réduit en ruines. La ville passa aux mains de Venise (elle devait être reprise en 1688).", "e28ad137"]},
"OLAYLAR_EK3:1687-11-08:0":{"b": ["Déposition de Mehmed IV et avènement de Soliman II", "9f53037c"], "d": ["À la suite des désastres du front et de la révolte de l'armée, Mehmed IV fut déposé après un règne de 39 ans ; à sa place fut porté son frère Soliman II, tenu en cage depuis quarante ans.", "6a7bb845"]},
"OLAYLAR_EK3:1688-09-06:0":{"b": ["Première perte de Belgrade — siège de la Sainte-Ligue", "c6b9b19a"], "d": ["Belgrade, aux mains des Ottomans depuis 1521, se rendit à l'armée de la Sainte-Ligue ; les portes de la Serbie furent ouvertes à l'ennemi et le danger atteignit la ligne Niš-Sofia.", "33c7db1f"]},
"OLAYLAR_EK3:1689-08-01:0":{"b": ["Baden franchit la Morava devant Pasarofça — Pasarofça tombe aux mains de l'Autriche", "bcf3fc59"], "d": ["Le margrave Louis de Bade franchit la Morava à Pasarofça en août 1689 et avança en direction de Niš ; la ville resta aux mains de l'Autriche jusqu'à l'été 1690 (le TDV « suleyman-ii » dit que Pasarofça fut reprise en 1690). La lecture de Gün et de Röder n'a pas été revérifiée lors de cette session.", "28e54b6c"]},
"OLAYLAR_EK3:1689-09-24:0":{"b": ["Perte de Niš — l'avance des Habsbourg (couronne du royaume de Hongrie), année la plus critique", "c5e27b3f"], "d": ["L'avance des Habsbourg (couronne du royaume de Hongrie) enleva aussi Niš à l'administration ottomane ; les raids s'étendirent jusqu'à Skopje et Priština. Vidin tomba ensuite, en octobre 1689 (entrée distincte). Dans l'année la plus sombre de la guerre, l'État sentit sa capitale même menacée.", "77de2b1f"]},
"OLAYLAR_EK3:1689-10-25:0":{"b": ["Orsova et Fethülislâm reçoivent une garnison autrichienne", "ee8dd875"], "d": ["Après la prise sans combat de Vidin (octobre 1689, TDV « vidin »), Baden répara et garnit Orsova et Fethülislâm le 25 octobre 1689 ; Orsova resta à l'Autriche jusqu'à l'automne 1690. Le jour repose sur Bánlaky/Röder et n'a pas été revérifié lors de cette session.", "4c6ebd2c"]},
"OLAYLAR_EK3:1690-09-27:0":{"b": ["Niš redevient ottomane", "0c4f44eb"], "d": ["Fâzıl Mustafa Pacha partit en campagne en juillet 1690 ; après la prise de Şehirköy, de Pasarofça et de Güvercinlik, Niš, assiégée, passa aux mains des Ottomans le 27 septembre 1690 (TDV « semendire »). Vidin avait été reprise à la même époque.", "f252f3ae"]},
"OLAYLAR_EK3:1690-10-01:0":{"b": ["Reddition des troupes autrichiennes à Smederevo", "90da20c4"], "d": ["Après la prise de Niš le 27 septembre 1690, les troupes autrichiennes de Smederevo se rendirent à la suite d'un siège de quatre jours (TDV « semendire »). Bánlaky/Röder donne le 24 septembre ; les sources se contredisent, le TDV a été retenu.", "9034a37d"]},
"OLAYLAR_EK3:1690-10-08:0":{"b": ["Belgrade reprise", "ab435838"], "d": ["Le grand vizir Köprülüzâde Fâzıl Mustafa Pacha reprit Belgrade à l'Autriche le 8 octobre 1690 ; la ville perdue en 1688 revint ainsi à l'Empire ottoman (TDV « suleyman-ii »).", "c93eeef6"]},
"OLAYLAR_EK3:1691-08-19:0":{"b": ["Déroute de Slankamen — Fâzıl Mustafa Pacha tombe en martyr", "10d626f1"], "d": ["Dans l'une des batailles rangées les plus sanglantes du siècle, le grand vizir tomba en martyr, frappé au front ; l'armée se dispersa. L'espoir d'un redressement s'éteignit avec cette bataille.", "36dfe6ea"]},
"OLAYLAR_EK3:1694-09-21:0":{"b": ["Perte de l'île de Chio", "07c084f8"], "d": ["La flotte vénitienne occupa Chio ; la domination ottomane en Égée se trouva menacée. L'île devait être reprise l'année suivante.", "f5f59c77"]},
"OLAYLAR_EK3:1695-02-11:0":{"b": ["Décision de Mustafa II de partir en personne en campagne", "61c3ba9c"], "d": ["Le nouveau sultan annonça qu'il partirait en campagne à la tête de l'armée, suivant la voie de ses ancêtres ; cette décision suscita le moral dans l'armée et ouvrit une période de campagnes personnelles qui devait durer deux ans.", "2794ae0f"]},
"OLAYLAR_EK3:1695-02-22:0":{"b": ["Reprise de Chio", "6b496fca"], "d": ["Mezomorto Hüseyin Pacha, qui avait battu la flotte vénitienne dans les combats navals des îles Oinousses (Koyun Adaları), reprit Chio ; ce fut le signe d'un bref renouveau de la marine ottomane.", "7638e074"]},
"OLAYLAR_EK3:1695-09-22:0":{"b": ["Victoire de Lugoj — « II. Him seferi »", "6527cee3"], "d": ["Lors de la première campagne à laquelle le sultan prit part en personne, Lipova fut reprise et les forces autrichiennes furent battues à Lugoj ; la chaîne de défaites qui durait depuis des années fut brisée pour la première fois.", "54aa0f54"]},
"OLAYLAR_EK3:1696-07-19:0":{"b": ["Perte de la forteresse d'Azak (Azov)", "2b78b5cd"], "d": ["Pierre Ier, qui visait la mer Noire, prit Azak lors de son second siège ; la Russie s'établit pour la première fois durablement dans une forteresse ottomane et fit son premier pas vers le statut de puissance navale.", "b765c903"]},
"OLAYLAR_EK3:1696-08-27:0":{"b": ["Victoire d'Ulaş (Olašin)", "02ac9ca8"], "d": ["La victoire remportée sur les bords du Danube lors de la seconde campagne du sultan fit échouer le plan autrichien de prendre Timișoara ; mais elle ne modifia pas l'équilibre général de la guerre.", "b6e2d27a"]},
"OLAYLAR_EK3:1697-09-11:0":{"b": ["Déroute de Zenta — le sort de la guerre est fixé", "475c4a7b"], "d": ["L'armée, qui franchissait la Tisza, fut surprise par l'attaque soudaine du prince Eugène ; les forces divisées sur les deux rives du fleuve furent anéanties en quelques heures, et des milliers de soldats et d'hommes d'État, dont le grand vizir Elmas Mehmed Pacha, périrent. Zenta, l'une des plus lourdes déroutes de l'histoire ottomane, rendit la table de paix inévitable.", "ced10fdc"]},
"OLAYLAR_EK3:1698-11-13:0":{"b": ["Début des négociations de paix de Karlowitz", "1f395cf3"], "d": ["Dans les négociations ouvertes sous la médiation de l'Angleterre et des Pays-Bas, la délégation ottomane dut pour la première fois accepter le principe de l'« uti possidetis » (chacun garde ce qu'il tient) ; les pourparlers, qui durèrent soixante-douze séances, sont considérés comme la naissance de la diplomatie ottomane moderne.", "1d41e9e8"]},
"OLAYLAR_EK4:1801-03-08:0":{"b": ["Kavalalı Mehmed Ali débarque en Égypte", "514c943f"], "d": ["Parmi l'armée ottomane envoyée pour reprendre l'Égypte occupée par les Français se trouvait aussi un corps de volontaires levé à Kavala. Mehmed Ali, alors dans la trentaine, était le commandant en second de ce corps ; il mit le pied en Égypte non comme gouverneur, mais comme officier d'une compagnie.", "b7e3bb36"]},
"OLAYLAR_EK4:1803-05-01:0":{"b": ["Les soldats albanais renversent le gouverneur d'Égypte", "c76a0ec2"], "d": ["Les troupes albanaises, dont la solde n'était pas versée, se soulevèrent et contraignirent le gouverneur Hüsrev Pacha à fuir la citadelle. Dans le vide créé par le départ des Français, les beys mamelouks, l'odjak albanais et les gouverneurs nommés par la Sublime Porte s'engagèrent dans une lutte à trois ; Méhémet-Ali s'imposa en établissant des équilibres au sein de ce triangle. Autre localité perdue à la même date : Taïf.", "669d61a0"]},
"OLAYLAR_EK4:1805-05:0":{"b": ["Les oulémas du Caire proclament Méhémet-Ali gouverneur", "a16752f2"], "d": ["Accablés par le poids de l'impôt, les artisans et les oulémas du Caire se soulevèrent sous la direction du naqîb al-ashrâf Omar Makram, déclarèrent ne pas reconnaître le gouverneur Hurchid Pacha et installèrent Méhémet-Ali dans la charge de gouverneur. Dans l'histoire ottomane, l'élection d'un gouverneur par la population est un fait rarement observé.", "1572b66f"]},
"OLAYLAR_EK4:1805-07-03:0":{"b": ["La Sublime Porte accepte le fait accompli : firman de gouvernement d'Égypte", "b86736a3"], "d": ["N'ayant pas la force d'imposer son propre candidat en Égypte, la Sublime Porte envoya à Méhémet-Ali un firman le nommant gouverneur d'Égypte avec le rang de vizir. Sur la carte, l'Égypte passe à partir de cette date dans la strate tributaire (teinte claire) : juridiquement terre ottomane, elle est de fait le pays de la dynastie de Kavala. Autres localités passées à la même date dans la strate tributaire : Le Caire, Alexandrie, Damiette, Assiout, Assouan, Ibrîm, Suez, Rachîd (Rosette).", "e769c607"]},
"OLAYLAR_EK4:1807-03-17:0":{"b": ["L'expédition britannique de Fraser débarque à Alexandrie", "4d6c31be"], "d": ["En réponse au rapprochement de l'Empire ottoman avec la France, l'Angleterre envoya un corps de débarquement en Égypte. Méhémet-Ali se trouvait alors en Haute-Égypte, occupé à combattre les Mamelouks ; il revint en hâte et organisa la défense.", "fd5f278f"]},
"OLAYLAR_EK4:1807-04-21:0":{"b": ["Défaite de Rachîd (Rosette) : les Britanniques sont repoussés", "3636004c"], "d": ["La colonne britannique qui était entrée dans la ville de Rachîd subit de lourdes pertes lors des combats de rues ; en septembre, les forces évacuèrent entièrement l'Égypte. Cette victoire consolida le prestige de Méhémet-Ali tant en Égypte qu'à Istanbul.", "68a2ba26"]},
"OLAYLAR_EK4:1811-03-01:0":{"b": ["L'affaire de la Citadelle : liquidation des beys mamelouks", "84030b97"], "d": ["Invités au cortège solennel organisé en vue de l'expédition du Hedjaz, les beys mamelouks furent pris au piège dans l'étroit passage de la Citadelle du Caire et éliminés. L'influence mamelouke, vieille de cinq siècles, prit ainsi fin et Méhémet-Ali ne se trouva plus de rival en Égypte.", "1ca00e33"]},
"OLAYLAR_EK4:1811-09-03:0":{"b": ["Début de l'expédition du Hedjaz : l'armée marche sur Yanbu, par mer depuis Suez et par terre sur la route du pèlerinage", "1c05c159"], "d": ["Reprendre les Lieux saints (Haramayn), placés depuis 1803 sous l'autorité saoudo-wahhabite, était pour Mahmud II le plus grand enjeu de légitimité ; la Sublime Porte n'en ayant pas les moyens, la mission fut confiée au gouverneur d'Égypte. Méhémet-Ali envoya à la tête de l'armée son fils Tosun, âgé de seize ans.", "5e614d69"]},
"OLAYLAR_EK4:1811-10-01:0":{"b": ["Prise de Yanbu : première base côtière de l'expédition du Hedjaz", "179bc78d"], "d": ["Environ deux mille fantassins albanais, partis de Suez sur des navires récemment construits, débarquèrent en octobre 1811 près de Yanbu ; la bourgade se rendit après deux jours d'une faible résistance. La cavalerie placée sous le commandement de Tosun, qui avait suivi par terre la route du pèlerinage, ne gagna Yanbu que deux semaines plus tard, par Akaba et Wadjh. Yanbu devint la première base de l'armée égyptienne au Hedjaz, d'où elle devait marcher sur Médine et La Mecque.", "cfc2ed8a"]},
"OLAYLAR_EK4:1812-01-01:0":{"b": ["Première défaite dans le défilé de Safra-Djedîda", "99ef804d"], "d": ["L'avant-garde égyptienne, prise en embuscade dans d'étroits passages montagneux, fut dispersée. La défaite fut la leçon tactique de l'expédition : on comprit qu'il était impossible de progresser au Hedjaz sans s'assurer le soutien des tribus bédouines.", "765dd19d"]},
"OLAYLAR_EK4:1812-12-03:0":{"b": ["Reprise de Médine", "6f6a5d55"], "d": ["Après un long siège, Médine se rendit. La reprise de la ville du Prophète fut célébrée à Istanbul par des salves de canon ; Méhémet-Ali reçut en récompense le gouvernement de Djeddah.", "45cc4c79"]},
"OLAYLAR_EK4:1813-01-23:0":{"b": ["Reprise de La Mecque : la route du pèlerinage est rouverte", "3d6d66a0"], "d": ["Entrées à La Mecque, les forces égyptiennes firent de nouveau réciter la khutba au nom du sultan ottoman à la Kaaba. Les caravanes de pèlerins, interrompues depuis dix ans, purent reprendre la route. Sur la carte, le Hedjaz revient sous la souveraineté ottomane, mais, son administration étant au Caire, il est figuré dans la teinte tributaire. Autre localité passée à la même date sous administration tributaire : Djeddah.", "f0970e28"]},
"OLAYLAR_EK4:1813-05-02:0":{"b": ["Reprise de Taïf : achèvement de l'expédition du Hedjaz", "6315fb31"], "d": ["Après Médine (décembre 1812) et La Mecque (janvier 1813), l'armée égyptienne placée sous le commandement de Tosun Pacha reprit enfin Taïf aux wahhabites. La domination saoudienne, qui avait duré dix ans, prit fin et les trois centres sacrés du Hedjaz passèrent de nouveau sous contrôle ottoman-égyptien.", "374bf563"]},
"OLAYLAR_EK4:1813-08-28:0":{"b": ["Méhémet-Ali passe en personne au Hedjaz", "fda0ea2d"], "d": ["Constatant que l'expédition traînait en longueur, le gouverneur prit directement l'administration en main ; marchandant avec les chefs de tribus, il s'efforça de résoudre de l'intérieur le front saoudien. La part de l'Égypte dans le commerce de la mer Rouge s'accrut également à la faveur de cette expédition.", "aeb051d1"]},
"OLAYLAR_EK4:1815-01-20:0":{"b": ["Bataille de Bissel : les forces saoudiennes sont mises en déroute", "9c9ab91f"], "d": ["Lourdement battus en bataille rangée, les Saoudiens se retirèrent vers les régions de l'intérieur. La trêve conclue ne fut pas durable ; deux ans plus tard, les opérations devaient être portées au cœur du Nadjd.", "4a8ae0e2"]},
"OLAYLAR_EK4:1816-09-01:0":{"b": ["Ibrahim Pacha part en expédition au Nadjd", "d5ed80d1"], "d": ["Ayant pris le commandement à la mort de son frère Tosun, Ibrahim Pacha entreprit dans le désert une marche pénible qui dura deux ans. Avançant de puits en puits et éliminant les tribus l'une après l'autre, l'armée parvint aux portes de la capitale saoudienne.", "e84c2cef"]},
"OLAYLAR_EK4:1818-09-09:0":{"b": ["Chute de Dir'iyya : fin du premier État saoudien", "aa96206d"], "d": ["Après un siège de six mois, Dir'iyya se rendit et fut détruite. L'émir Abdallah b. Saoud fut envoyé à Istanbul et exécuté. Pour la première fois, le drapeau ottoman pénétrait aussi profondément à l'intérieur de l'Arabie ; la garnison du Nadjd y demeura jusqu'en 1824. Autre localité rattachée à la même date : Dir'iyya (Nadjd).", "4b161cf5"]},
"OLAYLAR_EK4:1820-07-20:0":{"b": ["Début de l'expédition du Soudan", "b1fc6905"], "d": ["Le but de Méhémet-Ali était triple : recruter des soldats pour son armée, atteindre l'or du Sennar et détruire les restes des Mamelouks en fuite. La force placée sous le commandement de son fils Ismaïl Pacha descendit vers le sud en suivant le Nil.", "478563e9"]},
"OLAYLAR_EK4:1821-01-04:0":{"b": ["Prise de Dongola : les restes des Mamelouks sont dispersés", "ba6bc24b"], "d": ["Entrée à Dongola, dans la grande boucle du Nil, l'armée liquida le dernier groupe de Mamelouks qui s'y était réfugié. Sur la carte, le Soudan apparaît à partir de cette date dans la strate tributaire : c'est Le Caire qui conquiert, et c'est Le Caire qui gouvernera.", "bca7d521"]},
"OLAYLAR_EK4:1821-06-14:0":{"b": ["Le sultanat du Sennar (Fundj) se rend", "3cac7dd2"], "d": ["La dynastie fundj, vieille de trois siècles, se rendit sans combat. Le camp établi la même année au confluent des deux bras du Nil se transforma en peu de temps en centre administratif du Soudan, Khartoum. Autre localité rattachée à la même date : Sennar.", "1ad105c1"]},
"OLAYLAR_EK4:1821-08-19:0":{"b": ["Conquête du Kordofan", "06440602"], "d": ["La seconde colonne, envoyée vers l'ouest, battit les forces du Darfour à Bara et prit le Kordofan. La domination égyptienne au Soudan s'étendit ainsi de la vallée du Nil aux steppes de l'ouest.", "e18d449a"]},
"OLAYLAR_EK4:1822-06-28:0":{"b": ["Débarquement des forces égyptiennes en Crète", "835aee90"], "d": ["La révolte grecque s'étant étendue à la Crète, la Sublime Porte demanda que l'on envoyât une force égyptienne dans l'île. L'influence de Méhémet-Ali dans l'île commença avec cette intervention et s'acheva huit ans plus tard par l'attribution à son profit du gouvernement de Crète.", "8d651366"]},
"OLAYLAR_EK4:1822-10-24:0":{"b": ["Assassinat d'Ismaïl Pacha à Chendi", "223860c9"], "d": ["Irrité par les exigences excessives en impôts et en soldats, l'émir local Nimr mit le feu à la maison où logeait Ismaïl Pacha et brûla celui-ci avec sa suite. L'expédition de représailles transforma la région en un lac de sang ; l'administration du Soudan fut dès lors fondée sur la dureté.", "722af711"]},
"OLAYLAR_EK4:1824-07-19:0":{"b": ["Mahmud II demande l'aide de Méhémet-Ali pour la Morée", "03594a42"], "d": ["La révolte de Morée n'ayant pu être réprimée en trois ans par l'armée janissaire, le sultan eut recours à l'armée égyptienne, formée à l'européenne. En contrepartie, le gouvernement de Morée et la Crète lui furent promis. Cette demande fut le premier aveu manifeste que l'Empire en était réduit à avoir besoin de l'une de ses propres provinces.", "1b0ee342"]},
"OLAYLAR_EK4:1825-02-24:0":{"b": ["Ibrahim Pacha débarque à Modon", "9c993dba"], "d": ["Le corps de débarquement, protégé par la flotte égyptienne, prit pied à l'extrémité sud-ouest de la Morée. Équipée d'une infanterie nizâmî et d'une artillerie de campagne, cette armée acquit rapidement la supériorité sur les bandes insurgées.", "edf38fca"]},
"OLAYLAR_EK4:1825-06-22:0":{"b": ["Reprise de Tripolitza : le centre de la Morée tombe", "8a478c11"], "d": ["Avec la chute de Tripolitza, centre administratif de l'insurrection, la plus grande partie de la Morée repassa sous contrôle. Sur la carte, la péninsule apparaît dans la teinte tributaire, puisqu'elle est aux mains des forces égyptiennes.", "e7d9b818"]},
"OLAYLAR_EK4:1826-04-22:0":{"b": ["Chute de Missolonghi (Mesolongi)", "07257f87"], "d": ["La ville fut prise au terme d'un siège d'un an. Toutefois, l'écho que sa défense eut dans la presse européenne porta à son comble la sympathie pour la cause grecque et prépara le terrain de l'intervention des grandes puissances.", "9bf1efc2"]},
"OLAYLAR_EK4:1827-06-05:0":{"b": ["Reddition de l'Acropole d'Athènes", "3b19f946"], "d": ["Avec la chute de l'Acropole, la révolte grecque était pratiquement terminée sur le plan militaire. C'est précisément à ce moment que la question cessa d'être une révolte intérieure pour devenir un objet de la diplomatie européenne.", "e096fc52"]},
"OLAYLAR_EK4:1827-07-06:0":{"b": ["Traité de Londres : trois puissances imposent l'autonomie grecque", "7ce46fd8"], "d": ["L'Angleterre, la France et la Russie décidèrent d'agir de concert pour faire accepter à l'Empire ottoman et aux Grecs un armistice et le principe de l'autonomie ; il fut notifié que, en cas de refus, leurs flottes interviendraient. La Sublime Porte rejeta la proposition.", "8382f516"]},
"OLAYLAR_EK4:1828-08-06:0":{"b": ["Convention d'Alexandrie : décision du retrait égyptien de Morée", "cc978f37"], "d": ["Ayant perdu sa flotte à Navarin, Méhémet-Ali s'entendit directement avec l'amiral britannique, sans consulter Istanbul, et accepta de retirer ses forces de Morée. Qu'un gouverneur conclût un accord indépendant avec les grandes puissances annonçait la crise à venir.", "9430ea24"]},
"OLAYLAR_EK4:1828-10-05:0":{"b": ["Les forces égyptiennes évacuent la Morée", "8fb742dd"], "d": ["Les dernières troupes furent embarquées ; la péninsule échappa de fait à l'Empire et devint, avec le protocole de Londres de 1830, le noyau de la Grèce indépendante. Quant à Méhémet-Ali, il n'avait pas obtenu le gouvernement de Morée qui lui avait été promis, et y avait perdu une grande flotte et une armée. Autres localités perdues à la même date : Modon, Coron.", "7bfbefe0"]},
"OLAYLAR_EK4:1830-11-01:0":{"b": ["L'administration de la Crète est laissée à Méhémet-Ali", "7f76396d"], "d": ["En compensation de la perte de la Morée, le gouvernement de Crète fut attribué à Méhémet-Ali. L'île fut administrée depuis Le Caire pendant dix ans ; sur la carte, elle apparaît dans la teinte tributaire durant cette période. Autre localité rattachée à la même date : Candie (Crète).", "5b000d2b"]},
"OLAYLAR_EK4:1831-10-31:0":{"b": ["Ibrahim Pacha entre en Syrie : début de la première crise", "1a5cc386"], "d": ["Le prétexte était le gouverneur d'Acre, qui ne restituait pas les fellahs ayant fui l'Égypte ; la véritable raison était le besoin qu'avait Méhémet-Ali du bois, des ports et des ressources humaines de la Syrie. L'armée franchit le Sinaï et s'empara rapidement du littoral palestinien.", "9d41b0f9"]},
"OLAYLAR_EK4:1831-11-26:0":{"b": ["Début du siège d'Acre", "b211d96d"], "d": ["La forteresse qui avait arrêté Napoléon en 1799 résista pendant six mois. Le siège fut la première grande épreuve de l'artillerie moderne de l'armée égyptienne.", "97d9816b"]},
"OLAYLAR_EK4:1832-05-27:0":{"b": ["Chute d'Acre", "0f47917b"], "d": ["Les batteries qui battaient les remparts ayant ouvert une brèche, la forteresse fut prise. La porte de la Syrie était ouverte ; à ces mêmes jours, la Sublime Porte déclara Méhémet-Ali rebelle et lui retira son gouvernement.", "f92b4224"]},
"OLAYLAR_EK4:1832-06-16:0":{"b": ["Damas se rend", "48da3b62"], "d": ["La ville se rendit sans combat. Ibrahim Pacha s'efforça de gagner le soutien local en proclamant un nouveau régime fiscal et l'égalité accordée aux non-musulmans ; ces mêmes politiques devaient, quelques années plus tard, être aussi la cause des révoltes contre lui. Autres localités rattachées à la même période : Beyrouth, Tripoli de Syrie, Saïda.", "c67bd97e"]},
"OLAYLAR_EK4:1832-07-08:0":{"b": ["Bataille de Homs", "867810ee"], "d": ["L'armée ottomane envoyée pour sauver la Syrie fut mise en déroute en terrain découvert. On vit que la nouvelle armée, constituée six ans après l'abolition du corps des janissaires, n'était pas encore prête.", "f429ba2e"]},
"OLAYLAR_EK4:1832-07-15:0":{"b": ["Prise d'Alep", "9c0ead76"], "d": ["Le centre commercial et administratif de la Syrie du Nord tomba lui aussi. L'armée égyptienne atteignit ainsi le pied du Taurus et se dirigea vers les passages qui ouvrent sur l'Anatolie.", "b8b4a1bd"]},
"OLAYLAR_EK4:1832-07-29:0":{"b": ["Défaite du défilé de Belen (Beylan) : la Cilicie est ouverte", "4bae872b"], "d": ["La ligne de défense fut enfoncée dans l'étroit passage des monts Amanus. Antioche, Adana et Tarse passèrent aux forces égyptiennes (l'occupation de Marash date, selon le TDV, de 1833 ; notice distincte) ; sur la carte, la Cilicie passe à la teinte tributaire. La route de l'intérieur de l'Anatolie n'était désormais plus défendue.", "73cb1c5e"]},
"OLAYLAR_EK4:1832-09-13:0":{"b": ["Chute du défilé de Gülek : le littoral d'İçel (Mersin, Silifke) passe sous contrôle égyptien", "d9049b5b"], "d": ["Le défilé de Gülek, porte de la Cilicie dans le Taurus, tomba aux mains de l'armée égyptienne. Ibrahim Pacha nomma son propre mütesellim au sandjak d'İçel et tous les débarcadères de la côte passèrent sous contrôle égyptien. Sur la carte, Mersin et Silifke sont figurées comme rattachées à l'Égypte à partir de ce jour (borne inférieure ; la date de la nomination n'est pas donnée par la source) ; la décision de Kütahya ne transférant que la muhassıllık d'Adana, ce contrôle prend fin avec l'évacuation de l'Anatolie.", "fa650158"]},
"OLAYLAR_EK4:1832-09-13:1":{"b": ["Ereğli de Konya sous occupation égyptienne : l'entrée du Taurus sur la route de Konya à Adana", "fb908900"], "d": ["Ereğli, située sur la route de Konya que suivait l'armée égyptienne après avoir franchi le défilé de Gülek, passa en 1832 sous l'occupation d'Ibrahim Pacha ; évacuée à la suite de l'arrangement de Kütahya de 1833, elle fut de nouveau rattachée au vilayet de Karaman. Sur la carte, c'est le point intermédiaire, attesté par une source, de la ligne d'occupation entre Adana et Konya ; pour Ulukışla et Karapınar, aucun témoignage au niveau de la ville n'a été trouvé.", "c5c7c153"]},
"OLAYLAR_EK4:1832-11-21:0":{"b": ["L'armée égyptienne entre à Konya", "13952a2d"], "d": ["Ayant franchi le Taurus, l'armée atteignit l'Anatolie centrale. Pour la première fois, les forces d'un gouverneur ottoman avançaient dans les terres centrales de l'Empire. Autre localité rattachée à la même date : Karaman.", "569bd202"]},
"OLAYLAR_EK4:1832-12-21:0":{"b": ["Bataille de Konya : le grand vizir est fait prisonnier", "ec82cc9a"], "d": ["L'armée ottomane, dispersée dans le brouillard, subit une lourde défaite et le grand vizir Reşid Mehmed Pacha fut capturé. L'armée centrale de l'État n'existait plus ; aucune force ne se trouvait plus entre Istanbul et les troupes égyptiennes.", "30e73138"]},
"OLAYLAR_EK4:1833-01-01:0":{"b": ["Marash subit l'occupation égyptienne", "f558e383"], "d": ["Selon le TDV, Marash subit en 1833 l'occupation d'Ibrahim Pacha de Kavala et demeura près de dix-neuf mois sous son administration. Marash étant restée en dehors des limites provinciales fixées par l'arrangement de Kütahya, cette administration est de fait et non de droit.", "3d3c898a"]},
"OLAYLAR_EK4:1833-01-01:1":{"b": ["Karahisâr-ı Sâhib (Afyon) subit l'occupation égyptienne : route de Konya à Kütahya", "ae0c2c78"], "d": ["Karahisâr-ı Sâhib, située sur la route de l'armée égyptienne qui avançait vers Kütahya après la bataille de Konya, demeura quelque temps en 1833 aux mains d'Ibrahim Pacha. Sur la carte, c'est le point intermédiaire, attesté par une source, de la ligne d'occupation entre Konya et Kütahya ; pour Akşehir, Ilgın et İshaklı, aucun témoignage au niveau de la ville n'a été trouvé, et elles figurent dans la couleur ottomane.", "bce0b466"]},
"OLAYLAR_EK4:1833-02-02:0":{"b": ["L'armée égyptienne atteint Kütahya", "214f8df6"], "d": ["Ibrahim Pacha s'arrêta à Kütahya, à trois étapes d'Istanbul. S'il n'alla pas plus loin, ce fut non pour des raisons militaires mais politiques : l'intervention russe et la réaction de l'Europe avaient été prises en compte.", "0f1c5f03"]},
"OLAYLAR_EK4:1833-02-20:0":{"b": ["La flotte russe devant Büyükdere", "6f836d61"], "d": ["N'ayant obtenu aucune aide de l'Angleterre ni de la France, Mahmud II s'adressa à la Russie, son ennemi de la veille. Cette décision, rappelée par la phrase du sultan : « le noyé s'accroche au serpent », aboutit à la présence de soldats russes sur le Bosphore et fit sonner l'alarme en Europe.", "3e402e00"]},
"OLAYLAR_EK4:1833-05-06:0":{"b": ["Arrangement de Kütahya : la Syrie et Adana à l'homme de Kavala", "c16c5a94"], "d": ["La Sublime Porte laissa à Méhémet-Ali, outre l'Égypte, la Crète et le Hedjaz, les gouvernements de Damas, d'Alep, de Tripoli de Syrie et de Saïda, et à Ibrahim Pacha la muhassıllık d'Adana. En contrepartie, l'armée se retira au sud du Taurus. Il ne s'agissait pas d'un traité mais de firmans octroyés par le sultan à un gouverneur : la question n'était pas réglée, elle était ajournée.", "4160e4f4"]},
"OLAYLAR_EK4:1833-06-15:0":{"b": ["Le retrait de l'armée égyptienne d'Anatolie s'achève par Gülek", "a53ac2a3"], "d": ["Après l'arrangement de Kütahya, les forces égyptiennes évacuèrent l'Anatolie ; vers la mi-juin, la totalité de l'armée passa par le défilé de Gülek en Cilicie. Le littoral d'İçel (Mersin, Silifke) revient sous administration ottomane ; la muhassıllık d'Adana et la Syrie restent à l'Égypte.", "c5e13625"]},
"OLAYLAR_EK4:1833-07-08:0":{"b": ["Traité de Hünkâr İskelesi", "da741d5c"], "d": ["Une alliance défensive mutuelle de huit ans fut signée avec la Russie. Selon l'article secret, l'Empire ottoman fermerait les détroits aux navires de guerre au cas où la Russie serait attaquée. Ce fut l'une des décisions les plus controversées de la diplomatie ottomane, et elle rendit l'Angleterre active dans la question d'Égypte.", "43dc2c96"]},
"OLAYLAR_EK4:1834-05-19:0":{"b": ["Révolte de Palestine (Naplouse) contre l'administration égyptienne", "4fe43e27"], "d": ["La conscription obligatoire, la collecte des armes et les nouveaux impôts provoquèrent en Palestine un vaste soulèvement. La révolte fut durement réprimée ; le soutien dont l'administration égyptienne bénéficiait auprès de la population locale fondit rapidement.", "2a3301a2"]},
"OLAYLAR_EK4:1834-08-01:0":{"b": ["Fin (approximative) de l'administration égyptienne de Marash", "bb46ca42"], "d": ["Si la formule du TDV, « près de dix-neuf mois », est comptée à partir de l'occupation de 1833, l'administration égyptienne prend fin vers l'été 1834. Le fait que Mustafa Bey, des Küçükalioğulları, n'ait pu résister à l'armée égyptienne en 1834 et se soit replié du côté de Marash montre aussi que Marash était alors un refuge situé hors du contrôle égyptien.", "fbb6814a"]},
"OLAYLAR_EK4:1837-10-15:0":{"b": ["Soulèvement du Djabal al-Durûz", "12e74626"], "d": ["La résistance née dans la région druze dura deux ans. Le mécontentement accumulé en Syrie devait, en 1840, laisser l'armée égyptienne sans appui sur ses arrières lorsque les flottes alliées débarquèrent sur la côte.", "75c50707"]},
"OLAYLAR_EK4:1838-05-25:0":{"b": ["Méhémet-Ali fait connaître son intention d'indépendance", "48633bbd"], "d": ["Le gouverneur déclara aux consuls des grandes puissances qu'il envisageait de proclamer l'indépendance de l'Égypte et de la Syrie. L'Angleterre s'y opposa catégoriquement : la naissance en Méditerranée d'un État puissant et proche de la France menacerait la route des Indes.", "d6181bd9"]},
"OLAYLAR_EK4:1839-04-21:0":{"b": ["L'armée ottomane franchit l'Euphrate", "9af1ea69"], "d": ["Mahmud II lança son armée vers la frontière de Syrie pour reprendre ce qui avait été perdu à Kütahya. L'officier prussien Moltke, présent dans l'armée en qualité de conseiller, éleva des objections contre le choix de la position et l'attaque précoce ; ses objections ne furent pas écoutées.", "85d5db1c"]},
"OLAYLAR_EK4:1839-06-24:0":{"b": ["Bataille de Nizip : l'armée ottomane est dispersée", "156b3cdf"], "d": ["L'armée ottomane, mal déployée, fut mise en déroute en quelques heures. Le sultan mourut avant que la nouvelle de la défaite n'atteigne Istanbul ; en peu de jours, l'État devait perdre son armée, son souverain, puis sa flotte.", "fb8af82d"]},
"OLAYLAR_EK4:1839-06-28:0":{"b": ["Mort de Mahmud II", "07eccfff"], "d": ["Le sultan qui, au cours d'un règne de trente et un ans, avait aboli le corps des janissaires et rétabli l'administration centrale, mourut sans avoir pu vaincre son plus grand adversaire. Sa maladie n'avait pas été correctement diagnostiquée. Sa mort fut tenue secrète jusqu'au 30 juin, le temps que des mesures militaires soient prises dans la ville par crainte d'un réveil de l'esprit janissaire.", "3174d901"]},
"OLAYLAR_EK4:1839-07-01:0":{"b": ["Avènement d'Abdülmecid et funérailles de Mahmud II", "d0f3d2cc"], "d": ["À la mort de son père, Abdülmecid, âgé de seize ans, monta sur le trône. Le même jour, la dépouille de Mahmud II fut conduite au palais de Topkapı ; les troubles que l'on redoutait n'éclatèrent pas, et de larges foules, musulmanes et non musulmanes, se joignirent au cortège funèbre.", "7b398ea4"]},
"OLAYLAR_EK4:1839-07-14:0":{"b": ["Remise de la flotte à Alexandrie", "a53e6103"], "d": ["Le kapudan pacha Ahmed Fevzi Pacha, soupçonnant le grand vizir Koca Hüsrev Pacha de vouloir livrer la flotte à la Russie, conduisit l'escadre à Alexandrie et la remit à Méhémet-Ali. Dans le même mois, l'Empire ottoman se retrouva sans armée, sans sultan et sans flotte.", "78a26255"]},
"OLAYLAR_EK4:1839-07-27:0":{"b": ["Note collective des grandes puissances", "2a3b8316"], "d": ["Les cinq puissances remirent à la Sublime Porte une note lui demandant de ne pas conclure d'accord seule dans la question d'Égypte. Une affaire intérieure devint ainsi officiellement une « question européenne » ; l'État ottoman perdit de fait le pouvoir de décider du sort de l'une de ses propres provinces.", "979e7f0a"]},
"OLAYLAR_EK4:1840-07-15:0":{"b": ["Traité de Londres : quatre puissances aux côtés de l'Empire ottoman", "a517f775"], "d": ["Le traité, signé en laissant la France à l'écart, adressa un ultimatum à Méhémet-Ali : s'il l'acceptait dans les dix jours, il obtiendrait le gouvernement héréditaire de l'Égypte et, à titre viager, Acre ; s'il l'acceptait dans les vingt jours, l'Égypte seule ; s'il refusait, rien. Le gouverneur refusa.", "fc066f82"]},
"OLAYLAR_EK4:1840-09-10:0":{"b": ["Bombardement de Beyrouth et débarquement allié", "0905ce92"], "d": ["La flotte anglo-autrichienne bombarda Beyrouth ; des armes furent distribuées à la population des montagnes du Liban, soulevée contre l'administration égyptienne. Le contrôle d'Ibrahim Pacha sur la Syrie s'effondra entre la révolte intérieure et l'intervention extérieure.", "743ec7e2"]},
"OLAYLAR_EK4:1840-10-10:0":{"b": ["Beyrouth et les villes du littoral échappent aux Égyptiens", "09bdaf23"], "d": ["À la suite des combats en direction de Baalbek, les forces égyptiennes se retirèrent de la côte. Sur la carte, le littoral libanais sort de la teinte tributaire et revient à l'administration ottomane directe.", "fe5e95aa"]},
"OLAYLAR_EK4:1840-11-03:0":{"b": ["Acre tombe en deux heures", "5aec21f0"], "d": ["Sous le bombardement de la flotte alliée, l'arsenal de la forteresse explosa et Acre se rendit en quelques heures. La place qu'Ibrahim Pacha avait mis six mois à prendre huit ans plus tôt montra la supériorité de l'artillerie navale.", "5cf01edf"]},
"OLAYLAR_EK4:1840-11-27:0":{"b": ["Convention d'Alexandrie", "85cb47b0"], "d": ["Méhémet-Ali accepta de renoncer à la Syrie, à Adana, à la Crète et au Hedjaz, de restituer la flotte ottomane et de reconnaître la souveraineté du sultan ; en contrepartie, le gouvernement héréditaire de l'Égypte lui fut garanti.", "63d90626"]},
"OLAYLAR_EK4:1841-02-25:0":{"b": ["L'armée égyptienne évacue la Syrie et la Cilicie", "719a28dc"], "d": ["L'occupation, qui durait depuis neuf ans, prit fin ; l'armée d'Ibrahim Pacha regagna l'Égypte par le Sinaï. Sur la carte, une large bande allant d'Alep à Gaza et d'Adana à la Crète repasse sous administration ottomane directe. Autres localités perdues à la même date : Urfa, Marash, Tarse, Antioche, Candie (Crète), Hama, Damas, Jérusalem, Jaffa, Naplouse.", "a678b17a"]},
"OLAYLAR_EK4:1841-05-24:0":{"b": ["Firman : le gouvernement d'Égypte est laissé héréditairement à la famille de Kavala", "87b89ff8"], "d": ["Le firman du sultan reconnut le gouvernement comme transmissible de père en fils au sein de la dynastie ; en contrepartie, les effectifs de l'armée furent ramenés à dix-huit mille hommes, l'impôt fut rattaché à Istanbul, et le droit de battre monnaie et de conclure des traités fut supprimé. L'Égypte demeurait une province, mais elle était désormais le pays d'une dynastie distincte. L'administration du Hedjaz et des Lieux saints (Haramayn) revint à la Sublime Porte. Autres localités revenues à la même date de la strate tributaire à la strate directe : La Mecque, Médine, Djeddah, Yanbu.", "48099454"]},
"OLAYLAR_EK4:1841-07-13:0":{"b": ["Convention des Détroits de Londres", "0e95a1ea"], "d": ["La convention qui remplaça celle de Hünkâr İskelesi stipula que les détroits seraient fermés en temps de paix à tous les navires de guerre. Le privilège que la Russie avait acquis seule devint ainsi une garantie commune de l'Europe ; la question des détroits reçut un statut international.", "5bbbb459"]},
"OLAYLAR_EK4:1848-09-01:0":{"b": ["Ibrahim Pacha devient de fait gouverneur d'Égypte", "9e14f5d9"], "d": ["Méhémet-Ali vieillissant et ayant perdu ses facultés mentales, son fils Ibrahim Pacha fut porté au gouvernement à sa place. Quelques mois plus tard, toutefois, en novembre 1848, il mourut avant son père.", "338908f8"]},
"OLAYLAR_EK4:1849-08-02:0":{"b": ["Mort de Méhémet-Ali Pacha de Kavala", "871310e0"], "d": ["Le gouverneur, né à Kavala, fondateur d'une dynastie en Égypte et qui avait deux fois conduit l'Empire au bord du gouffre, mourut à quatre-vingts ans. La dynastie qu'il avait fondée régna en Égypte jusqu'en 1953 ; quant à l'État, voyant qu'il n'avait pu refermer la plaie ouverte par lui que grâce à l'intervention européenne, il s'engagea dans la voie des Tanzimat.", "c0877894"]},
"OLAYLAR_EK5:1281-01-01:0":{"b": ["Mort d'Ertuğrul Ghazi et passage d'Osman Bey à la tête du beylicat : l'héritage de Söğüt et de Domaniç", "395fb9fa"], "d": ["Selon le TDV, Ertuğrul Ghazi mourut en 680 (1281-82) ; la notice mentionne que les dates de 1288 et de 1289 sont également données. Osman Bey reçut de son père non une ville conquise, mais deux concessions que le sultan seldjoukide avait accordées à Ertuğrul en l'installant sur la ligne la plus avancée de la marche : un yurtluk (quartier d'hiver) à Söğüt et un yaylak (pâturage d'été) à Domaniç. Le beylicat n'a donc pas commencé avec un héritage de conquête, mais avec deux concessions de pâturages ; sur la carte, ces deux lieux sont figurés comme « héritage » et non comme « conquête ».", "37fbc33c"]},
"OLAYLAR_EK5:1282-03-30:0":{"b": ["Les Vêpres siciliennes : la maison d'Anjou perd l'île de Sicile", "547db635"], "d": ["Le soulèvement qui éclata à Palerme, à l'heure des vêpres du lundi de Pâques, contre le gouvernement de Charles Ier d'Anjou, détacha l'île de Sicile de la maison d'Anjou. Le royaume de Sicile fut scindé en deux : l'île se tourna vers l'Aragon, tandis que la maison d'Anjou se maintint dans le royaume continental centré sur Naples. Les possessions extérieures de la dynastie sur l'Adriatique et en Méditerranée restèrent aussi rattachées à ce royaume : Corfou, qu'elle tenait depuis 1267, et Durazzo, qu'elle tenait depuis les années 1270, subsistèrent comme parties du royaume de Naples ; les forteresses albanaises de Vlora, de Kanina et de Himara demeurèrent elles aussi dans le royaume centré sur Naples (le commandant de Vlora, John of Taxis, résista aux Byzantins tout au long de 1282 ; Durazzo, Vlora et Kanina passèrent très probablement à Byzance au début de 1285). Malte, en revanche, ne tomba aux mains des Aragonais qu'en 1284.", "7c8ea21d"]},
"OLAYLAR_EK5:1285-01-01:0":{"b": ["Raid de Kulacahisar : première opération militaire d'Osman Bey", "79b00b14"], "d": ["Notice Osman Ier du TDV : « Il pilla et incendia le petit château de Kulaca Hisarı, près d'İnegöl (684/1285). » C'est la première action militaire d'Osman Bey qui puisse être datée dans les sources. Aucun établissement durable ne fut pris, le château fut pillé et brûlé ; il s'agit donc moins d'une conquête que d'un raid classique de marche. Il est tenu pour le point de départ de l'activité militaire du beylicat.", "15ee9a09"]},
"OLAYLAR_EK5:1288-01-01:0":{"b": ["Conquête de Karacahisar : première ville acquise et mainmise sur Eskişehir", "178ae619"], "d": ["Notice Osman Ier du TDV : en 687 (1288), Osman Bey « conquit Karacahisar et devint maître d'Eskişehir ». C'est la première véritable acquisition urbaine du beylicat ; selon la tradition, Osman Bey fut par ce succès élevé à la dignité de sandjak beyi de la marche ; on rapporte que la première khutba du vendredi fut lue à Karacahisar en son nom et que le premier cadi y fut nommé. La notice Eskişehir du TDV indique que la tradition ottomane donne la date de 1291, mais que son exactitude est douteuse.", "90949e22"]},
"OLAYLAR_EK5:1291-05-18:0":{"b": ["Chute d'Acre aux mains des Mamelouks : élimination des croisés de la côte syrienne : Saïda et Beyrouth", "3ca7a464"], "d": ["Acre, longtemps centre du royaume croisé de Jérusalem, fut conquise par le sultan mamelouk al-Malik al-Achraf Khalîl, et la domination des croisés en Palestine prit fin. Les chevaliers templiers, qui s'étaient retirés d'Acre, se réfugièrent à Saïda ; à l'approche de l'armée mamelouke, ils abandonnèrent le château de mer et s'enfuirent à Chypre, et la ville passa aux Mamelouks le même été. Beyrouth, aux mains des croisés depuis 1197, fut elle aussi prise en 1291 par le gouverneur de Damas, Sandjar al-Chudjâ'î. La présence croisée, vieille de deux siècles, fut ainsi effacée de la côte syro-palestinienne.", "63b3c40c"]},
"OLAYLAR_EK5:1299-01-01:0":{"b": ["Conquête de Bilecik et de Yarhisar par un raid nocturne", "f461b0af"], "d": ["Notice Bilecik du TDV : « Les tekfurs de la région, dont celui de Bilecik, avaient ourdi un attentat contre Osman Ghazi, mais, le complot ayant été découvert, les forces ottomanes conquirent Yarhisar et Bilecik par une attaque soudaine (1299). » Les deux places furent prises en une seule opération, au cours du même raid nocturne. Cette date est le tournant tenu pour l'année de fondation de l'État ottoman. Autre localité rattachée à la même date : İnegöl.", "ec452c9e"]},
"OLAYLAR_EK5:1302-07-27:0":{"b": ["Bataille de Koyunhisar (Bapheus) : première grande victoire sur l'armée byzantine", "584a9512"], "d": ["Notice Osman Ier du TDV : le 27 juillet 1302, Osman Bey affronta et battit l'armée byzantine à Bapheus (Koyunhisar). Cette victoire est le tournant qui fit d'Osman Bey, de simple bey de marche régional, le fondateur d'une dynastie. À la suite de la bataille, la plaine de Bursa passa sous contrôle ottoman et le blocus de Nicée commença.", "b82fb787"]},
"OLAYLAR_EK5:1303-01-01:0":{"b": ["Victoire de Dimbos, puis prise de Kite et d'Ulubat", "e168ab64"], "d": ["Notice Osman Ier du TDV : en 702 (1303), la coalition formée par les tekfurs de Bursa, de Kestel, de Kite et d'Adranos fut battue au défilé de Dimbos ; l'ennemi, combattu pas à pas, fut refoulé jusqu'au défilé étroit et le tekfur de Kestel mourut sur le champ de bataille. Aussitôt après la victoire, les forteresses de Kite et d'Ulubat furent prises, ce qui coupa la liaison terrestre de Bursa et resserra son blocus. Le jeune Orhan participa lui aussi à cette bataille.", "4afb53bf"]},
"OLAYLAR_EK5:1304-01-01:0":{"b": ["Campagne de la Sakarya : prise de Leblebicihisar, Lefke, Mekece et Geyve", "a51ba4d3"], "d": ["La notice Osman Ier du TDV donne l'ordre de la campagne de la Sakarya de 704 (1304) : « Arrivé à Leblebüci Hisarı, le tekfur fit sa soumission... Il atteignit Lefke... Il parvint à Mekece... Il se rendit à Geyve et prit le château, qu'il trouva vide. » Lefke est la porte de la vallée de la Sakarya ouvrant sur Bilecik. Cette seule campagne, en plaçant sous contrôle ottoman la chaîne de forteresses qui s'étend le long de la vallée, ferma le flanc est du bassin de Nicée.", "ae2866c2"]},
"OLAYLAR_EK5:1305-01-01:0":{"b": ["Conquête des forteresses du défilé de Geyve : Karaçepüş, Karatigin et Absu", "76907c78"], "d": ["Notice Orhan du TDV : lors de la campagne de la Sakarya de 705 (1305), Orhan « conquit les forteresses de Karaçepüş (Katoikia), de Karatigin devant Nicée et d'Absu (Hypsu : dans le défilé de Geyve) ». Ces trois forteresses, en fermant le passage entre la vallée de la Sakarya et le bassin de Nicée, coupèrent entièrement Nicée de tout secours par terre. Gazi Abdurrahman fut établi à Karaçepüş et à Absu, dans le défilé de Geyve ; la ville ne pouvait plus désormais être réduite que par la famine.", "d330595f"]},
"OLAYLAR_EK5:1323-09-01:0":{"b": ["Campagne d'Adranos (Orhaneli) : dernière campagne d'Osman Bey", "4811546c"], "d": ["La notice Orhan du TDV consigne la campagne contre la forteresse d'Adranos, à l'automne 1323, comme la dernière campagne d'Osman Bey. Le tekfur d'Adranos avait fait partie de la coalition de tekfurs formée vingt ans plus tôt à Dimbos contre les Ottomans ; cette campagne signifiait le règlement de ce compte. Le jour exact de la conquête de la forteresse est inconnu ; les opérations furent poursuivies par Orhan Bey.", "1e8ea25a"]},
"OLAYLAR_EK5:1324-01-01:0":{"b": ["Mort d'Osman Ghazi et passage d'Orhan Bey à la tête du beylicat", "021487cd"], "d": ["Osman Ghazi, qui a donné son nom au beylicat, mourut en 724 (1324), comme l'attestent les actes de fondation pieuse (vakfiye) d'Asporça Hatun et de Mekece. Son fils Orhan, à la tête de l'armée dans les campagnes depuis 1305, prit la tête du beylicat à la mort de son père sans aucune querelle de succession. Que la génération fondatrice ait transmis l'étendard sans secousse montre que la dynastie passa dans le calme sa première grande épreuve sur la voie qui mène du beylicat de marche à l'État.", "6f95e64a"]},
"OLAYLAR_EK5:1329-06-01:0":{"b": ["Bataille de Pelekanon (Maltepe) et prise de tout le Kocaeli", "389e7bd4"], "d": ["Notice Orhan du TDV : le premier jour de la bataille, Orhan Ghazi envoya une force de trois cents hommes pour attirer l'armée byzantine ; le deuxième jour, la bataille s'étendit lorsque les troupes placées sous le commandement de Pazarlu descendirent dans la plaine, et la panique saisit l'armée byzantine quand l'empereur fut blessé d'une flèche. Le résultat est net : « Orhan s'empara de tout le Kocaeli ; après la victoire, les habitants de Nicée n'eurent plus aucun espoir. » Les bourgades côtières de Hereke à Üsküdar passèrent sous domination ottomane et Gebze devint le centre de la région. Ce fut la dernière armée impériale byzantine venue pour sauver Constantinople.", "73fe4332"]},
"OLAYLAR_EK5:1331-03-03:0":{"b": ["Fondation de la première médersa ottomane à Nicée", "c85fb625"], "d": ["Aussitôt après avoir pris Nicée, Orhan Bey y nomma Çandarlı Kara Halil cadi, transforma une basilique en mosquée et fit construire à ses côtés un imaret et une médersa, entamant ainsi l'aménagement de la ville. Selon la notice Dâvûd-i Kayserî du TDV, la construction de la médersa s'acheva en 1336 et Orhan Ghazi y fit venir Dâvûd-i Kayserî comme professeur, au traitement journalier de 30 akçes. Cette médersa est le premier pas institutionnel de la vie savante ottomane ; à la force de conquête, le beylicat ajoutait ainsi une tradition du savoir. La transformation d'une capitale byzantine conquise en centre du savoir islamique fut le premier signe concret de la prétention ottomane à être un État sédentaire.", "4f11a077"]},
"OLAYLAR_EK5:1333-08-01:0":{"b": ["Byzance devient tributaire : siège d'İzmit et traité", "0c1ec8d3"], "d": ["Notice Orhan du TDV : à l'été 733 (1333), Orhan assiégea İzmit avec une grande armée et des mangonneaux, et l'empereur consentit à un traité. En contrepartie de la levée du siège, Byzance accepta de verser à Orhan 12 000 pièces d'or (hyperpères) par an ; « ainsi, aux yeux de l'émir ottoman, Byzance était tombée à l'état de pays tributaire ». En échange, Orhan devait être l'ami de l'empereur et ne pas attaquer les villes dépendant de Byzance. Qu'un beylicat de marche soumît l'Empire romain d'Orient au tribut proclamait à quel point l'équilibre des forces s'était renversé.", "e2e3eeb4"]},
"OLAYLAR_EK5:1345-01-01:0":{"b": ["Annexion du beylicat de Karesi : Balıkesir, Bergama, Biga, Edremit et Erdek", "c7cb0511"], "d": ["La notice Orhan du TDV (İnalcık) place l'annexion en 735 (1334-35) : à la mort de Demirhan Bey, les ghazis de Karesi et Hadji İlbey invitèrent Dursun Bey à monter sur le trône et demandèrent l'aide d'Orhan. Orhan marcha d'abord sur Balıkesir ; Dursun Bey, qui se rendait à une négociation de paix, ayant été tué d'une flèche tirée de la forteresse de Bergama, le beylicat fut intégralement rattaché au territoire ottoman. Au cours de la même campagne, Kirmasti et Mihaliç firent leur soumission, Gölyazı fut prise et Ulubat, précédemment laissée sous sauvegarde, fut définitivement occupée. Orhan nomma Süleyman Pacha au sandjak de Karesi et fit de Biga le centre de la marche : les cadres marins nécessaires au passage en Roumélie étaient ainsi acquis. Remarque : la notice Karesioğulları du TDV donne pour le même événement la date de 746 (1345) ; l'encyclopédie se contredit donc elle-même. Autre localité rattachée à la même date : Çanakkale.", "f5ed82c2"]},
"OLAYLAR_EK5:1352-01-01:0":{"b": ["Première capitulation d'Orhan Ghazi avec les Génois", "e64cb196"], "d": ["S'étant accordé avec les Génois pendant la guerre vénéto-génoise, Orhan Ghazi envoya mille archers à la défense de Péra après la bataille du détroit de février 1352 et fournit 60 000 pièces d'or pour le transport de troupes ; en contrepartie, il accorda aux Génois la première capitulation. Le texte intégral du traité ne nous est pas parvenu. C'est le premier accord officiel conclu par les Ottomans avec une puissance maritime européenne ; il devait être renouvelé trente-cinq ans plus tard, en 1387.", "68c60677"]},
"OLAYLAR_EK5:1354-03-02:0":{"b": ["Prise de Gallipoli : tête de pont durable en Roumélie", "ba51a160"], "d": ["Les Ottomans prirent en 1354 Gallipoli, dont ils avaient reconnu les environs entre 1349 et 1352 en qualité d'alliés de Cantacuzène ; un grand tremblement de terre qui renversa les remparts de la ville leur en fournit l'occasion. L'étroite tête de pont de Çimpe devint ainsi une véritable base sur la rive roumeliote du détroit, et la porte ouvrant sur la Thrace fut largement entrebâillée. Gallipoli devait être perdue en 1366 lors de la croisade de Savoie, mais entrer définitivement sous domination ottomane lors de la seconde conquête de 1376. Autre localité rattachée à la même date : Kilitbahir.", "cac0192e"]},
"OLAYLAR_EK5:1357-09-01:0":{"b": ["Mort de Süleyman Pacha, conquérant de la Roumélie", "2dc98228"], "d": ["Süleyman Pacha, fils aîné d'Orhan Bey et architecte des conquêtes de Roumélie, mourut à l'automne 1357, la date la plus généralement admise parmi celles que donnent les sources, 758 (1357), 759 et 760 (1359) : il tomba de cheval au cours d'une chasse. La mort du prince qui avait fondé la présence ottomane durable en Roumélie par ses passages de 1352-1354 laissa à son frère Murad le rang d'héritier présomptif. Le türbe de Süleyman Pacha, enseveli à Bolayır, est resté le plus ancien monument dynastique ottoman en Europe.", "1f780557"]},
"OLAYLAR_EK5:1361-01-01:0":{"b": ["Loi du pencik : fondation du corps des janissaires", "e5877c2d"], "d": ["À la suite des conquêtes de Roumélie, sur le conseil du savant Karamanlı Kara Rüstem, fut mis en vigueur le système du pencik, qui prévoyait de réserver à l'État le cinquième des prisonniers de guerre ou sa contre-valeur en argent. Les prisonniers ainsi choisis, élevés auprès de familles turques puis enrôlés, formèrent le noyau d'une force d'infanterie permanente rattachée directement au sultan, le corps des janissaires. C'est par cette disposition que commença la transformation d'un beylicat de marche, fondé sur la cavalerie tribale, en un État doté d'une armée centrale.", "f28873dd"]},
"OLAYLAR_EK5:1363-01-01:0":{"b": ["Descente en Thrace occidentale : conquête de Gümülcine", "9ef69221"], "d": ["Après la prise d'Edirne, les forces de marche qui s'étaient tournées vers l'ouest de la Maritza s'emparèrent, sous le commandement de Ghazi Evrenos Bey, de Gümülcine, centre de la Thrace occidentale. La ville devint le quartier avancé d'où Evrenos Bey porterait ses raids en Macédoine. La partie de la Thrace s'étendant jusqu'à la côte égéenne passa ainsi sous contrôle ottoman et la route de Salonique fut ouverte.", "0206d2bb"]},
"OLAYLAR_EK5:1373-01-01:0":{"b": ["À l'ouest de Plovdiv : rattachement de Tatarpazarcığı et d'İhtiman", "1664d0e1"], "d": ["Après la prise de Plovdiv en 1372, Tatarpazarcığı, à l'extrémité supérieure de la vallée de la Maritza, et İhtiman, qui tient le passage ouvrant sur Sofia, furent rattachées à l'administration ottomane. Cette ligne, aux mains de beys locaux devenus vassaux après la bataille de Çirmen, fut placée sous administration directe, rendant continu l'itinéraire Plovdiv-Sofia. Cette progression prépare la voie qui mènera, douze ans plus tard, à la conquête de Sofia.", "0e9acfa0"]},
"OLAYLAR_EK5:1373-05-15:0":{"b": ["Révolte de Savcı Bey : soulèvement commun d'un prince et de l'héritier byzantin", "75198c33"], "d": ["Savcı Bey, fils de Murad Ier, et Andronic Paléologue, fils de l'empereur byzantin Jean V, se soulevèrent contre leurs pères, au début de mai 1373, simultanément à Bursa et à Constantinople. Cette alliance, qui unissait les héritiers des deux dynasties, fut rapidement réprimée ; Savcı Bey, capturé, fut aveuglé puis exécuté. La date de 787 (1385) que donne la tradition ottomane pour la révolte est erronée ; l'événement se place juste après les années où Byzance devint vassale des Ottomans et montre à quel point les deux cours étaient imbriquées.", "9776426c"]},
"OLAYLAR_EK5:1374-01-01:0":{"b": ["Vallées de la Struma et de la Mesta : rattachement de Köstendil, Petritch, Nevrokop et Drama", "8c0980c4"], "d": ["Les vallées de la Struma et de la Mesta, aux mains de beys locaux serbes et bulgares qui payaient tribut aux Ottomans depuis la victoire de Çirmen, furent placées sous administration ottomane directe par l'avance des beys de marche. Avec le rattachement de Köstendil, Petritch, Nevrokop et Drama, la moitié orientale de la Macédoine fut ouverte et Salonique et Serrès entrèrent dans le cercle du siège. Sur la carte, l'expansion de la Roumélie vers le sud-ouest est le résultat de ces opérations.", "a50a02ad"]},
"OLAYLAR_EK5:1381-04-01:0":{"b": ["Tamerlan prend Hérat : fin de la dynastie kert et passage du Khorassan aux Timourides", "15f6019e"], "d": ["Le Khorassan était en 1380 morcelé par la lutte entre les Serbedarides, les Kert et les Muzaffarides. Après avoir envoyé son fils Mîrân Châh dans la région, Tamerlan marcha lui-même sur Hérat et, après l'avoir assiégée quelque temps, reçut la ville des mains du roi kert Ghiyâth al-Dîn Pîr Ali. La révolte qui éclata après son départ fut noyée dans le sang par Mîrân Châh, et la dynastie kert, qui régnait à Hérat depuis 1255, fut abolie. De Mechhed à Nichapour, tout le Khorassan passa à cette date sous l'administration timouride.", "6ae06d43"]},
"OLAYLAR_EK5:1381-10-01:0":{"b": ["Fin du beylicat d'Eretna et fondation de l'État de Kadı Burhâneddin", "60dcaf57"], "d": ["Les Eretnaoğulları, issus en 1335 d'un gouvernorat ilkhanide et qui avaient gouverné pendant quarante-six ans l'Anatolie centrale autour de Sivas et de Kayseri, se désagrégèrent sous l'effet des rivalités de palais. Devenu vizir en mai 1378, Kadı Burhâneddin, après avoir écarté ses rivaux Kılıcarslan et Hadji Chadgeldi, proclama son sultanat à l'automne 1381, mit fin au beylicat et fonda l'État qui porte son nom. Le voisin oriental des Ottomans changea ainsi de mains ; la ligne Sivas-Kayseri devait rester dix-sept ans aux mains de Kadı Burhâneddin.", "f5b2be0c"]},
"OLAYLAR_EK5:1385-01-01:0":{"b": ["Progression à l'intérieur de la Macédoine : conquête de Monastir et d'Ohrid", "63bb7838"], "d": ["Monastir, sur la Via Egnatia, et Ohrid, au bord du lac, passèrent sous administration ottomane au cours des raids menés en direction de l'Albanie. L'une et l'autre étaient des points clés de la route menant à l'Adriatique ; Ohrid était en outre le plus ancien siège archiépiscopal orthodoxe des Balkans. Le TDV note que l'on ne possède pas de renseignement certain sur la date de la conquête d'Ohrid, qu'il avance les dates de 787 (1385) et de 797 (1395), cette dernière postérieure à la mort de Marko Kraljević ; c'est ici 1385 qui est retenue. Monastir devait être, dans les siècles suivants, l'un des principaux centres militaires de la Roumélie.", "e5418654"]},
"OLAYLAR_EK5:1385-09-18:0":{"b": ["Bataille de Savra : les portes de l'Albanie s'ouvrent", "dda6671b"], "d": ["À l'appel du seigneur albanais Karl Thopia, pressé par la maison des Balsha, les forces ottomanes mirent en déroute dans la plaine de Savra l'armée de Balsha II, qui perdit la vie sur le champ de bataille. Cette guerre, entreprise à l'invitation d'un seigneur local, procura aux Ottomans leur première influence durable sur les terres albanaises qui s'étendent jusqu'aux côtes de l'Adriatique. Cette politique, qui tirait parti des dissensions entre les seigneurs de la région, devait être pendant tout le siècle suivant la méthode constante des conquêtes balkaniques.", "05382964"]},
"OLAYLAR_EK5:1386-01-01:0":{"b": ["La « campagne de trois ans » de Tamerlan : prise de l'Azerbaïdjan et de l'Iran du Nord", "2a98ec51"], "d": ["Ayant constaté de près, lors de ses campagnes du Khorassan, l'état de dispersion de l'Iran, Tamerlan marcha vers l'ouest en 788 (1386). Au cours des opérations de 1386-1388 dites « campagne de trois ans », il passa par le Mazandéran, le Luristan et la Géorgie jusqu'en Azerbaïdjan et atteignit le Karabagh ; Tabriz, Ardabil, Ourmia et Nakhitchevan passèrent sous administration timouride. Sa conquête de l'Iran du Nord et de l'Azerbaïdjan fut aussi, comme jadis entre l'ulus de Djötchi et les Ilkhanides, le début d'une longue querelle avec la Horde d'Or.", "aaf3b558"]},
"OLAYLAR_EK5:1386-06-01:0":{"b": ["Bataille de Frenkyazısı et siège de Konya : première campagne contre Karaman", "af4e5d77"], "d": ["Murad Ier partit en personne en campagne contre Karamanoğlu Alâeddin Ali Bey, son gendre, mais gêné par l'expansion ottomane en Anatolie occidentale ; dans la bataille livrée au lieu dit Frenk Yazısı, l'armée ottomane, bien exercée et expérimentée, battit les forces karamanides. La citadelle de Konya fut ensuite assiégée, mais le beylicat ne fut pas entièrement supprimé, Alâeddin Bey ayant été gracié. Cette campagne est le premier acte du long règlement de comptes entre les Ottomans et Karaman, qui devait durer un siècle et ne s'achever qu'avec l'annexion définitive de 1468.", "087a605a"]},
"OLAYLAR_EK5:1390-06-01:0":{"b": ["Fondation de l'arsenal de Gallipoli : naissance de la flotte ottomane", "47546241"], "d": ["Le premier arsenal organisé de l'État ottoman fut fondé en 1390 par Bayezid Yıldırım à Gallipoli, à l'emplacement de l'arsenal laissé par Byzance. Héritiers de la tradition maritime des beylicats d'Anatolie occidentale, les Ottomans devenaient ainsi pour la première fois une puissance navale construisant ses propres navires. Situé en un point clé du détroit des Dardanelles, l'arsenal servit pendant un siècle et demi de base principale de la flotte ottomane, du siège de Constantinople aux campagnes de l'Égée.", "f214717c"]},
"OLAYLAR_EK5:1391-01-01:0":{"b": ["Prise de Varna sur la côte de la mer Noire", "a84b2abf"], "d": ["Lors du resserrement des terres du tsarat bulgare entre le Danube et la mer Noire, Varna, le plus grand port de la côte, passa sous administration ottomane. La prise du port ouvrit la voie à la progression vers la Dobroudja et procura aux Ottomans leur premier grand débarcadère sur la côte occidentale de la mer Noire. Varna devait aussi être, cinquante-trois ans plus tard, le théâtre de la victoire de 1444, où l'armée des croisés fut anéantie.", "421a978f"]},
"OLAYLAR_EK5:1393-01-01:0":{"b": ["Fin de la dynastie muzaffaride : défaite de Châh Mansûr devant Chiraz", "5fd14eb8"], "d": ["Châh Mansûr, dernier souverain puissant des Muzaffarides, qui régnaient depuis 1318 à Yazd, au Fars, à Ispahan et au Kirman, s'unit à ses parents et se mit en campagne contre Tamerlan. Dans la bataille livrée près de Chiraz, l'un de ses émirs ayant passé à l'adversaire, il perdit la plupart de ses forces, fut vaincu et tué. Tamerlan ayant ensuite fait mettre à mort tous les membres de la dynastie, la domination muzaffaride prit fin, et le Fars et le Kirman furent rattachés à l'administration timouride.", "8e89c2dc"]},
"OLAYLAR_EK5:1393-06-01:0":{"b": ["Rattachement d'Amasya aux terres ottomanes", "fe2860cf"], "d": ["Au cours des opérations de Bayezid Yıldırım en Anatolie centrale, l'émir d'Amasya, assiégé, remit la ville aux Ottomans et Bayezid y entra en 1393. Le sultan en laissa l'administration à son fils Mehmed Çelebi ; devenue sandjak princier, Amasya devint dès lors l'un des plus importants foyers d'éducation de la dynastie ottomane. Ce choix devait être déterminant pendant le Fetret à venir : c'est de cette base d'Amasya que Mehmed Çelebi mènerait sa lutte pour réunifier l'État.", "389ab68d"]},
"OLAYLAR_EK5:1393-08-29:0":{"b": ["Tamerlan s'empare de Bagdad : les Djalayirides fuient en Anatolie", "4d5602b3"], "d": ["Tamerlan prit Bagdad après un long siège ; le maître de la ville, le sultan djalayiride Ahmed, s'enfuit vers l'ouest et se réfugia d'abord auprès des Mamelouks, puis à la cour ottomane. L'expansion de Tamerlan vers l'ouest entrait ainsi pour la première fois en contact direct avec la sphère d'influence ottomane. C'est de là que date le premier maillon de l'hostilité entre les deux souverains.", "2fac674f"]},
"OLAYLAR_EK5:1398-07-15:0":{"b": ["Chute de l'État de Kadı Burhâneddin", "b13391e3"], "d": ["Kadı Burhâneddin, tombé prisonnier du souverain aqqoyunlu Karayülük Osman Bey, offrit de se faire libérer en échange de la reddition de Sivas, mais la population de la ville résista et le sultan fut exécuté devant les remparts. Les notables de Sivas mirent à leur tête son fils Alâeddin Ali Çelebi, mais, devant la pression aqqoyunlu, ils demandèrent l'aide de Bayezid Yıldırım ; les forces ottomanes placées sous le commandement de Süleyman Çelebi battirent Karayülük et se rendirent maîtresses de la ville. L'État de Kadı Burhâneddin disparut ainsi de l'histoire, et Sivas, Tokat, Niksar et Kayseri furent rattachées aux terres ottomanes. Autres localités rattachées à la même date : Kırşehir, Çorum.", "2a0c7f3a"]},
"OLAYLAR_EK5:1399-11-01:0":{"b": ["Épreuve de force avec Tamerlan : refus de restituer les fugitifs", "33790bc8"], "d": ["Sous la pression de Tamerlan, le sultan djalayiride Ahmed et le chef qaraqoyunlu Qara Yûsuf se réfugièrent en territoire ottoman ; Tamerlan demanda l'extradition de ces deux fugitifs, Bayezid Yıldırım refusa. Là-dessus, les deux souverains commencèrent à échanger des lettres contenant de graves injures réciproques. Le terrain idéologique de la guerre fut établi par cette correspondance avant même qu'un seul soldat se fût mis en mouvement.", "ac66be59"]},
"OLAYLAR_EK5:1400-01-01:0":{"b": ["Le Darüşşifa de Yıldırım à Bursa : premier hôpital ottoman", "5f0dc59a"], "d": ["Dans les années où il faisait construire à Bursa la magnifique Grande Mosquée (Ulucami), Bayezid Yıldırım dota aussi la ville d'un dârüşşifa ; ce fut le maillon, consacré à la médecine, de son vaste programme de fondations pieuses comprenant un imaret, une médersa, un han et un pont. Premier hôpital fondé par l'État, cet édifice, qui faisait aussi office d'école de médecine formant des médecins, détermina le modèle des institutions de santé ottomanes. Achevée deux ans seulement avant le désastre d'Ankara, l'œuvre est l'un des derniers maillons du projet de Yıldırım de faire de Bursa une capitale impériale.", "5765ebac"]},
"OLAYLAR_EK5:1400-08-01:0":{"b": ["Tamerlan rase Sivas", "f4d79de6"], "d": ["Marchant sur Sivas sous la conduite de l'aqqoyunlu Karayülük Osman Bey et de l'émir d'Erzincan Mutahharten, Tamerlan assiégea la ville dix-huit jours, la reçut en promettant qu'aucun sang ne serait versé, puis y fit un grand massacre ; les défenseurs furent jetés dans des fossés et recouverts vivants. Les principaux monuments de la ville, à commencer par les remparts, furent détruits, et Sivas s'effondra démographiquement. Ce fut le premier grand coup porté par Tamerlan au territoire ottoman, deux ans avant la bataille d'Ankara.", "8ddb3e3a"]},
"OLAYLAR_EK5:1401-02-01:0":{"b": ["Bayezid Yıldırım reprend Erzincan et Kemah", "7047ca08"], "d": ["Profitant du départ de Tamerlan en campagne de Syrie, Bayezid Yıldırım prit Erzincan et Kemah à l'émir d'Erzincan Mutahharten, vassal de Tamerlan. Bien qu'il ne fût pas intervenu lors de la destruction de Sivas, ce geste revenait à défier directement la sphère d'influence de Tamerlan en Anatolie orientale. La rupture entre les deux souverains devint dès lors irréparable.", "2160d645"]},
"OLAYLAR_EK5:1402-03-13:0":{"b": ["Ultimatum de Tamerlan envoyé de Tabriz : quatre conditions", "3e1ac50e"], "d": ["Par un ambassadeur envoyé de Tabriz, Tamerlan fit connaître quatre conditions : la restitution de Kemah à Mutahharten, la restitution à leurs propriétaires des terres prises aux beys d'Anatolie, l'envoi en otage d'un prince ottoman avec acceptation du bonnet et de la ceinture comme signes de vassalité, et la livraison de Qara Yûsuf. Bayezid n'en accepta aucune ; malgré l'insistance des dignitaires et la médiation de Mutahharten, les pourparlers échouèrent. Tamerlan était résolu à clore définitivement la question anatolienne avant de partir en campagne contre la Chine.", "bd475bc3"]},
"OLAYLAR_EK5:1402-08-17:0":{"b": ["Reconstitution des Saruhanides : Manisa échappe aux Ottomans", "ac747b05"], "d": ["Trois semaines après la défaite d'Ankara, Orhan Bey prit, avec l'appui de Tamerlan, la tête du beylicat, et le pays de Saruhan redevint indépendant. La région centrée sur Manisa disparut de la carte douze ans après l'annexion ottomane de 1390. C'est l'une des premières applications, de date connue avec certitude, de la politique de Tamerlan consistant à rétablir les beylicats.", "9fe5744d"]},
"OLAYLAR_EK5:1402-08-20:0":{"b": ["L'émir Süleyman s'enfuit en Roumélie avec le trésor de l'État", "0a2b7363"], "d": ["Emmenant le trésor de l'État conservé à Bursa, les archives, sa famille et ses frères, l'émir Süleyman passa par mer de Gemlik à Güzelcehisar (Anadoluhisarı), gagna de là Gallipoli et se proclama souverain à Edirne. Le transfert des archives et du trésor de l'État en Roumélie marque le début du déplacement, pour une génération, du centre de gravité ottoman vers les Balkans. Sur la carte, la Roumélie est dessinée à partir de cette date dans la couleur propre de l'émir Süleyman.", "393aa053"]},
"OLAYLAR_EK5:1402-09-15:0":{"b": ["Tamerlan rétablit les beylicats d'Anatolie : l'unité turque se disloque", "15187774"], "d": ["Après la victoire d'Ankara, Tamerlan restitua à leurs anciennes terres les beys qui se trouvaient auprès de lui. Il donna à Karamanoğlu Mehmed et Ali Beys le pays de Karaman avec Kayseri, Kırşehir, Sivrihisar et Beyşehir ; à Germiyanoğlu Yâkub Bey II, Kütahya et le pays de Germiyan ; à Candaroğlu İsfendiyar Bey, outre la ligne Kastamonu-Sinope, Çankırı et Kalecik. Les pays d'Aydın, de Menteşe et de Teke revinrent eux aussi à leurs anciennes dynasties. L'unité turque d'Anatolie, que Bayezid Yıldırım avait édifiée en dix ans, se disloqua en un seul été ; sur la carte, ces beylicats réapparaissent dans leurs propres couleurs.", "3a86d489"]},
"OLAYLAR_EK5:1402-12-14:0":{"b": ["Tamerlan prend İzmir aux chevaliers de Saint-Jean", "66dd1dd4"], "d": ["Descendant vers l'ouest par Kütahya, Denizli, Aydın, Ayasuluk et Tire, Tamerlan assiégea et prit İzmir, ville côtière aux mains des chrétiens depuis 1344. Ayant enlevé en peu de temps cette forteresse que Bayezid Yıldırım n'avait pu prendre pendant des années, il s'empara aussi des forteresses environnantes, puis rendit le pays d'Aydın à ses anciens maîtres et se tourna vers l'est. La ville passa dès lors sous l'administration d'Aydınoğlu Cüneyd Bey.", "b6c372a5"]},
"OLAYLAR_EK5:1402-12-20:0":{"b": ["İsâ Çelebi s'empare de Bursa : naissance de la part anatolienne", "955128c1"], "d": ["İsâ Çelebi, qui s'était retiré du côté de Karesi après la défaite d'Ankara, s'empara de Bursa pendant que Tamerlan se trouvait à İzmir. Dans l'ancienne capitale, pillée et incendiée par les soldats de Tamerlan, il se proclama souverain et fit frapper monnaie à son nom ; en janvier 1403, il était reconnu en Anatolie comme souverain des « Turcs ». Sur la carte, cette part qui s'étend le long de la rive asiatique de la Marmara apparaît dans la couleur propre d'İsâ Çelebi.", "fdd5eed3"]},
"OLAYLAR_EK5:1403-03-15:0":{"b": ["Retrait de Tamerlan d'Anatolie", "93a98839"], "d": ["Informé de la mort de Bayezid Yıldırım à Akşehir, Tamerlan, tenant son œuvre en Anatolie pour achevée, se tourna vers l'est. Il laissa derrière lui des beylicats lui faisant allégeance et des princes ottomans dressés les uns contre les autres ; certaines villes, comme Sivas, furent laissées à des émirs vassaux de Tamerlan tels que Mezid Bey. Tamerlan ne revint plus en Anatolie, mais l'ordre morcelé qu'il avait établi dura dix ans.", "646cb1bc"]},
"OLAYLAR_EK5:1404-03-01:0":{"b": ["L'émir Süleyman passe en Anatolie : Bursa tombe entre ses mains", "9b27aa5f"], "d": ["Apprenant la défaite d'İsâ Çelebi, l'émir Süleyman passa en Anatolie avec une puissante armée aux côtés de Çandarlı Ali Pacha et s'empara de Bursa ; les documents de mars 1404 montrent que Karadeniz Ereğli était également sous son administration. Mehmed Çelebi ne put résister à Süleyman, qui domina en peu de temps à la fois la Roumélie et la plus grande partie de l'Anatolie. Sur la carte, de cette date jusqu'à la reprise de Bursa par Mehmed Çelebi (1410), les deux rives apparaissent d'une seule couleur, celle de la part de l'émir Süleyman.", "bca67f28"]},
"OLAYLAR_EK5:1405-01-01:0":{"b": ["Bataille de la plaine de Yenişehir : Mehmed Çelebi se retire à Amasya", "f1568288"], "d": ["Ayant perdu Bursa et Ankara, Mehmed Çelebi fut battu par l'émir Süleyman dans la plaine de Yenişehir, perdit tous ses gains d'Anatolie occidentale et se retira dans sa base de Tokat-Amasya. Après cette défaite, il évita l'affrontement direct et s'attacha à consolider son autorité à l'intérieur de l'Anatolie. Ainsi commença la plus longue phase silencieuse du Fetret.", "8c8a3c8c"]},
"OLAYLAR_EK5:1406-01-01:0":{"b": ["L'émir Süleyman prend Ankara à Mehmed Çelebi", "d6a2acd6"], "d": ["L'émir Süleyman assiégea en 1406 Ankara, restée aux mains de Mehmed Çelebi après le retrait de Tamerlan d'Anatolie. Le gardien de la forteresse, Yâkub Bey, résista quelque temps, mais remit la place à Süleyman grâce à une ruse du grand vizir Çandarlı Ali Pacha. Mehmed Çelebi s'entendit alors avec Karamanoğlu Mehmed Bey et se mit en campagne contre Süleyman.", "f2a18bf9"]},
"OLAYLAR_EK5:1408-06-01:0":{"b": ["Mehmed Çelebi reprend Sivas au timouride Mezid Bey", "90079b0c"], "d": ["Après l'invasion de Tamerlan, l'administration de Sivas avait été laissée à Mezid Bey, vassal de Tamerlan. Mehmed Çelebi, à Amasya, envoya son commandant Bayezid Pacha prendre la ville et, après une vive résistance, Sivas passa pour la seconde fois aux mains de la dynastie ottomane. Ainsi, six ans après la bataille d'Ankara, la part de Mehmed atteignit à l'est son ancienne frontière.", "22c266b9"]},
"OLAYLAR_EK5:1409-01-01:0":{"b": ["Fin de la dynastie artukide : Mardin remise aux Qaraqoyunlu", "15b06f33"], "d": ["Les Artukides, qui régnaient à Mardin depuis 1106 et dont c'était la branche la plus durable, ne purent tenir devant la pression aqqoyunlu. Comprenant qu'il ne pouvait défendre la ville, Melik Ahmed s'entendit avec le souverain qaraqoyunlu Qara Yûsuf et lui remit Mardin. La domination artukide, qui avait dépassé trois siècles, prit ainsi fin ; Mardin et ses environs furent le théâtre de la lutte entre Qaraqoyunlu et Aqqoyunlu jusqu'à ce qu'ils passent aux Ottomans, un siècle plus tard.", "52e31654"]},
"OLAYLAR_EK5:1410-02-13:0":{"b": ["Bataille de Yanbolu : Mûsâ Çelebi entre à Edirne", "8f978408"], "d": ["Passé en Roumélie par la Valachie, Mûsâ Çelebi mit en déroute les forces de l'émir Süleyman à Yanbolu, avec l'appui des Valaques et des Serbes, et entra à Edirne. Pendant le Fetret, la Roumélie échappa ainsi pour la première fois à l'émir Süleyman. Sa domination ne fut toutefois pas durable ; quatre mois plus tard, vaincu à Kosmidion, il devait se replier à l'intérieur des Balkans.", "e80e7126"]},
"OLAYLAR_EK5:1412-10-01:0":{"b": ["Bataille d'İnceğiz : première défaite de Mehmed Çelebi en Roumélie", "3c35cd43"], "d": ["Passé en Roumélie sur les navires byzantins, Mehmed Çelebi engagea le combat contre Mûsâ Çelebi à İnceğiz ; Mûsâ, avec les sept mille janissaires placés sous ses ordres, battit Mehmed, qui dut revenir en Anatolie. Cette défaite orienta Mehmed vers une stratégie consistant, au lieu de la guerre directe, à gagner à sa cause les beys de marche de Roumélie et le despotat serbe. C'est cette diplomatie qui prépara, neuf mois plus tard, le terrain de la victoire de Çamurlu.", "dd443a98"]},
"OLAYLAR_EK5:1415-03-01:0":{"b": ["Siège de Konya et traité avec les Karamanides : Hamîd-ili, Said-ili, Beyşehir, Seydişehir et Akşehir sont reprises", "0996257e"], "d": ["Contre les Karamanides, qui avaient attaqué le territoire ottoman pendant le Fetret et assiégé et incendié Bursa, Mehmed Çelebi organisa une grande campagne et assiégea Konya en Muharrem 818. Karamanoğlu Mehmed Bey II dut demander la paix ; par le traité, Hamîd-ili (région d'Isparta) et Said-ili furent de nouveau rattachés aux terres ottomanes, Beyşehir, Seydişehir et Akşehir furent restituées, et Sivrihisar, que Tamerlan avait donnée aux Karamanides en 1402, revint elle aussi aux Ottomans. Cette campagne, qui commença à recoudre l'unité anatolienne disloquée par la bataille d'Ankara, est l'une des raisons concrètes pour lesquelles Mehmed Çelebi est tenu pour le « second fondateur ».", "952c9f73"]},
"OLAYLAR_EK5:1415-06-01:0":{"b": ["Prise d'İzmir sur Aydınoğlu Cüneyd Bey", "2377ca51"], "d": ["İzmir, centre d'Aydınoğlu Cüneyd Bey, qui avait constamment changé de camp entre les princes pendant le Fetret, fut prise par Mehmed Çelebi après un siège de dix jours ; Cüneyd, gracié, fut envoyé comme sandjak beyi à Nicopolis. La ville que Tamerlan avait rendue aux Aydınoğlu en 1402 revint ainsi aux Ottomans treize ans plus tard. Cüneyd devait reprendre la ville en 1422, et la question ne fut close qu'en 1424-1426 par Murad II.", "41fefe61"]},
"OLAYLAR_EK5:1416-01-01:0":{"b": ["Exécution de Torlak Kemal : Saruhan définitivement ottomane", "8a09dbf1"], "d": ["Torlak Kemal, qui conduisait la branche ouest-anatolienne du mouvement du cheikh Bedreddin, fut battu et exécuté dans la région de Manisa. À partir de cette date, la région de Saruhan passa définitivement sous contrôle ottoman et le beylicat que Tamerlan avait ressuscité en 1402 disparut de l'histoire. Les dernières séquelles politiques du Fetret en Anatolie occidentale furent ainsi nettoyées.", "43bec619"]},
"OLAYLAR_EK5:1417-01-01:0":{"b": ["Conquête de Vlora, de Berat et de Kanina", "1e1949b8"], "d": ["En 1417, les Ottomans placèrent sous leur domination Vlora, sur la côte de l'Adriatique, avec la ville de Berat, à l'intérieur du pays, et la forteresse de Kanina. Un an plus tard, la tentative de Venise de reprendre la ville échoua et une organisation en sandjak y fut établie, rendant durable l'autorité ottomane. La prise de Vlora fit des Ottomans, pour la première fois, les possesseurs directs d'un port sur l'Adriatique et leur procura un tremplin outre-mer face à l'Italie.", "508b9927"]},
"OLAYLAR_EK5:1419-01-01:0":{"b": ["Reprise de l'Anatolie centrale : Kayseri et Kırşehir", "204eacb3"], "d": ["Les villes d'Anatolie centrale tombées aux mains des Karamanides pendant le Fetret revinrent sous administration ottomane lors des campagnes par lesquelles Mehmed Çelebi s'employait à reconstituer l'État. Avec le rattachement de Kayseri et de Kırşehir, le bassin du Kızılırmak, perdu à la bataille d'Ankara, fut en grande partie repris. Cette progression prolonge la politique de réorientation vers l'est ouverte par le siège de Konya quatre ans plus tôt.", "c663fc08"]},
"OLAYLAR_EK5:1423-01-01:0":{"b": ["Liquidation définitive des Tekeoğulları : prise d'Antalya", "e65565b2"], "d": ["Le beylicat des Tekeoğulları, rétabli après la bataille d'Ankara grâce à Tamerlan, prit fin lorsque les forces ottomanes placées sous le commandement de Hamza Bey assiégèrent Antalya ; Osman Çelebi, dernier homme important du beylicat, fut éliminé. Le pays de Teke, sur la côte méditerranéenne, fut ainsi définitivement rattaché à l'Empire ottoman après vingt et un ans de séparation. Le beylicat, branche détachée des Hamidoğulları, régnait à Antalya depuis 1321.", "6b81398d"]},
"OLAYLAR_EK5:1423-05-01:0":{"b": ["Campagne de Turahan Bey en Morée et destruction du mur de l'Hexamilion", "c6c2706d"], "d": ["Byzance ayant soutenu le prétendant rival Mustafa Çelebi, Murad II envoya Turahan Bey contre la Morée. Turahan Bey abattit le mur de l'Hexamilion, qui fermait de part en part l'isthme de Corinthe, pénétra dans la péninsule et y causa de grands ravages. La paix fut obtenue à la condition que le mur ne fût pas reconstruit et qu'un tribut annuel fût versé ; le despotat de Morée fut ainsi laissé militairement sans défense, et le terrain de la conquête définitive de 1460 fut préparé trente-sept ans à l'avance.", "3482eb23"]},
"OLAYLAR_EK5:1424-01-01:0":{"b": ["Les monastères du mont Athos passent sous protection ottomane", "562de5ea"], "d": ["Dans les années où Salonique était assiégée, la république monastique de l'Athos, sur le doigt oriental de la Chalcidique, s'adressa à Murad II pour demander sa protection et accepta la souveraineté ottomane. Les droits de propriété et de culte des moines furent garantis ; les monastères furent laissés libres dans leurs affaires intérieures moyennant un impôt. Ce régime devint l'exemple le plus durable de la relation de protection que les Ottomans établirent avec les institutions orthodoxes, et dura cinq siècles.", "6be1a9f2"]},
"OLAYLAR_EK5:1427-01-01:0":{"b": ["Annexion du beylicat des Tâceddinoğulları : Niksar", "370ffd47"], "d": ["Sous la pression de Yörgüç Pacha, beylerbey d'Amasya, Tâceddinoğlu Hüsâmeddin Hasan Bey remit en 830 (1427) les clés de son pays, dont le centre était Niksar ; il reçut un sandjak en Roumélie. Le beylicat, fondé dans la seconde moitié du XIVe siècle et dont les frontières s'étendirent par moments jusqu'à Kelkit, Amasya, Samsun, Ordu et Giresun, prit ainsi fin. La même année, les terres des Hacıemiroğulları furent elles aussi recensées et rattachées au sandjak de Canik ; l'ère des beylicats de la mer Noire centrale était close.", "06fa8222"]},
"OLAYLAR_EK5:1432-01-01:0":{"b": ["Mardin passe de la garnison qaraqoyunlu à l'aqqoyunlu Karayülük Osman Bey", "d82bc97f"], "d": ["Mardin, prise par Qara Yûsuf en 1409, fut administrée par des gouverneurs qaraqoyunlu ; l'émir Nâsır, laissé comme gardien, remit la ville en 835 (1432) à l'aqqoyunlu Karayülük Osman Bey. L'administration aqqoyunlu dura jusqu'au début du XVIe siècle.", "407382cb"]},
"OLAYLAR_EK5:1446-05-05:0":{"b": ["Incident de Buçuktepe : première révolte des janissaires et retour de Murad II sur le trône", "6388dda1"], "d": ["L'incident de Buçuktepe, qui éclata à Edirne et fut la première révolte de janissaires connue de l'histoire, commença par la revendication d'une augmentation d'un demi-akçe de leur solde (ulûfe) et aboutit à la déposition du jeune Mehmed II. Murad II partit en hâte de Manisa le 8 Safer 850 et commença son second règne. L'événement fut le premier signe que le corps des kapıkulu était devenu une force qui avait voix au chapitre sur le trône, et il façonna la prudence que Mehmed le Conquérant conserva toute sa vie envers les janissaires.", "c03ef4f8"]},
"OLAYLAR_EK5:1449-01-01:0":{"b": ["Rattachement de la côte d'Épire : Arta et Preveza", "796f7ecf"], "d": ["Dix-neuf ans après la reddition de Ioannina en 1430, Arta et Preveza, sur la partie côtière du despotat d'Épire, passèrent elles aussi sous administration ottomane. Le golfe d'Ambracie, ouvert sur la mer Ionienne, fut ainsi placé sous contrôle et la liaison maritime de Ioannina fut complétée. Preveza est le point clé de la baie qui devait donner son nom, quatre-vingt-dix ans plus tard, à la célèbre victoire de Barberousse.", "b5e95ae5"]},
"OLAYLAR_EK5:1451-02-18:0":{"b": ["Mort de Murad II et second avènement de Mehmed II", "8f8256ad"], "d": ["Tombé malade après le mariage de son fils, Murad II mourut à Edirne le 1er Muharrem 855 (3 février 1451). Mehmed II, âgé de dix-neuf ans, monta pour la seconde fois sur le trône ottoman le 16 Muharrem 855 (18 février 1451), cette fois définitivement. Le retour du jeune souverain, déposé cinq ans plus tôt à Buçuktepe, est le début d'un règne qui devait être couronné, deux ans plus tard, par la prise de Constantinople et qui transforma le beylicat ottoman en un empire mondial.", "5363b0f7"]},
"OLAYLAR_EK5:1454-07-14:0":{"b": ["Premier siège de Caffa par les forces ottomano-criméennes conjointes", "e346d163"], "d": ["Ayant conclu un accord avec le sultan Mehmed le Conquérant en juin 1454, le khan de Crimée Hadji Giray assiégea Caffa par terre avec 7 000 cavaliers ; une flotte ottomane de cinquante à soixante galères prit aussi position au large. Caffa la génoise fit lever le siège en versant un tribut, et la conquête définitive fut reportée à vingt et un ans plus tard, en 1475. Cette première opération commune fut le premier exemple de la coopération militaire ottomano-criméenne, qui devait se répéter lors de la conquête définitive de Caffa.", "bf590b3e"]},
"OLAYLAR_EK5:1455-01-01:0":{"b": ["Prise des îles de l'Égée septentrionale : Ténédos, Imbros et Thasos", "76575895"], "d": ["Aussitôt après la prise de Constantinople, le sultan Mehmed le Conquérant se tourna vers les îles situées à l'entrée égéenne des Dardanelles afin de garantir la route maritime de la nouvelle capitale ; Ténédos et Imbros furent prises à Byzance, Thasos à la famille Gattilusio, d'origine génoise. Ces îles qui verrouillaient les deux rives du détroit devinrent dès lors le premier maillon de la ligne de ravitaillement et de défense d'Istanbul. La domination oscilla quelque temps sous l'effet des interventions des flottes pontificale et vénitienne, et ne fut fixée qu'en 1459.", "9a34e8f0"]},
"OLAYLAR_EK5:1455-06-01:0":{"b": ["Conquête du Kosovo : prise de Pristina et de Novi Pazar", "d7ed2345"], "d": ["L'armée ottomane qui marchait contre le despotat serbe s'empara de Pristina, dans la plaine du Kosovo, et de Novi Pazar, centre de la région de Rascie ; au cours de la même campagne fut aussi prise Novo Brdo, célèbre pour ses mines d'argent. La moitié sud de la Serbie fut ainsi rattachée à l'administration ottomane directe et le despotat de Smederevo fut coupé de ses terres centrales. Cette conquête fut l'étape décisive sur la voie qui conduisit, quatre ans plus tard, à l'annexion complète de la Serbie.", "b2c7fcce"]},
"OLAYLAR_EK5:1456-01-01:0":{"b": ["Peć (İpek) passe sous administration ottomane : l'un des centres du sandjak de Dukagin", "19511588"], "d": ["En 1455, aussitôt après la campagne de Serbie du sultan Mehmed le Conquérant, Peć (İpek), siège du patriarcat serbe, passa sous administration ottomane ; les sources ottomanes ne contiennent aucune mention de ce passage. La bourgade devint avec le temps une petite ville musulmane et l'une des résidences du sandjak beyi dans le sandjak de Dukagin.", "4d7160f6"]},
"OLAYLAR_EK5:1456-01-24:0":{"b": ["Conquête d'Enez et de Samothrace : achèvement de la côte de Thrace occidentale", "106e723b"], "d": ["Enez, à l'embouchure de la Maritza, fut prise à la famille Gattilusio, d'origine génoise, qui la tenait depuis quatre-vingts ans ; l'île de Samothrace, qui en dépendait, fut prise au cours de la même campagne. Avec la chute d'Enez, la bande côtière de la Thrace occidentale, de Salonique à Gallipoli, devint un territoire ottoman continu. Il ne restait plus aux Gattilusio que Lesbos, qui devait être prise six ans plus tard.", "327297a0"]},
"OLAYLAR_EK5:1456-07-22:0":{"b": ["Échec du siège de Belgrade", "3d53a604"], "d": ["Après la prise de Constantinople, le sultan Mehmed le Conquérant assiégea Belgrade, tenue pour le verrou de l'Europe centrale ; mais les renforts amenés par Jean Hunyadi par le Danube et les volontaires rassemblés par le prédicateur de la croisade Capistran empêchèrent la chute de la place. Le sultan, malgré l'héroïsme personnel dont il fit preuve devant le siège, fut blessé et dut se retirer. Cet échec devait fermer pendant soixante-cinq ans la frontière hongroise à l'avance ottomane ; Belgrade ne put être prise qu'en 1521 par Soliman le Magnifique.", "036836cb"]},
"OLAYLAR_EK5:1458-05-01:0":{"b": ["Conquête de la Morée du Nord : Patras (Balyabadra)", "c08a8509"], "d": ["Les forces du sultan Mehmed le Conquérant, qui s'étaient tournées vers le despotat de Morée dans les mêmes années que l'annexion de la Serbie, s'emparèrent de Patras (Balyabadra), au nord-ouest de la péninsule. Ce port, qui tient l'entrée du golfe de Corinthe, est le verrou de l'accès terrestre à la Morée ; sa prise prépara le terrain de la conquête définitive deux ans plus tard. La ville était le dernier grand débarcadère par lequel les despotes byzantins communiquaient avec le monde latin.", "4490cc14"]},
"OLAYLAR_EK5:1459-06-20:0":{"b": ["Prise de la côte de la mer Noire occidentale : Amasra", "f43608fc"], "d": ["Amasra, colonie fortifiée de Gênes sur la mer Noire occidentale, se rendit sans résistance sous la pression conjointe de la flotte et des forces terrestres du sultan Mehmed le Conquérant. Ce port de la côte de Bartın-Zonguldak subsistait comme une poche latine entre les Candaroğulları et les terres ottomanes ; sa prise rendit la côte continue. La chute d'Amasra est le premier pas de la grande campagne de la mer Noire qui devait, deux ans plus tard (1461), se diriger vers Sinope et Trébizonde.", "b8b9f4f0"]},
"OLAYLAR_EK5:1462-09-17:0":{"b": ["Conquête de l'île de Lesbos", "fe17aeba"], "d": ["L'armée ottomane placée sous le commandement du sultan Mehmed le Conquérant prit Lesbos en Dhou'l-hidjdja 866, après un siège court mais violent, à la famille Gattilusio, d'origine génoise, et l'annexa. La chute de la plus grande île de l'Égée septentrionale liquida aussi la dernière base importante des Génois dans la région. Grâce à sa proximité de la côte anatolienne, l'île devait servir dès lors d'avant-poste à la flotte ottomane et entrer dans l'histoire maritime comme le lieu où se formèrent les frères Barberousse.", "453088e2"]},
"OLAYLAR_EK5:1463-07-28:0":{"b": ["Début de la guerre ottomano-vénitienne de seize ans", "563ddb68"], "d": ["Les Vénitiens commencèrent la guerre en 1463, après s'être alliés avec les souverains de Karaman et des Aqqoyunlu pour arrêter l'avance ottomane en Morée et dans l'Égée. Cette stratégie d'encerclement, constituée par Uzun Hasan à l'est, Venise à l'ouest et Karaman entre les deux, contraignit le Conquérant à combattre sur plusieurs fronts à la fois. La lutte de seize ans devait embrasser toutes les grandes opérations de l'époque, d'Otlukbeli aux campagnes d'Albanie, et ne prendre fin qu'avec le traité d'Istanbul de 1479.", "e70079e9"]},
"OLAYLAR_EK5:1466-01-01:0":{"b": ["Conquête de la plus grande partie de l'Herzégovine : Trebinje et Mostar", "f54c0100"], "d": ["Les terres de Stjepan Vukčić-Kosača, duc d'Herzégovine, qui avait constitué une administration distincte de la Bosnie, passèrent en grande partie sous administration ottomane trois ans après la chute du royaume de Bosnie : au sud, Trebinje fut prise en 1466 « avec presque toute la région d'Herzégovine ». Mostar, fondée autour des deux petites forteresses du pont de la Neretva, doit avoir été prise peu avant la conquête de Blagaj, centre de l'Herzégovine, en 1466-1468 ; elle est enregistrée sous le nom de « Köprülü Hisar » dans le recensement sommaire (icmal tahrir) de Bosnie de 1468-1469. La conquête de l'Herzégovine fut achevée en 1483 avec les forteresses restantes du duché.", "a7f22be7"]},
"OLAYLAR_EK5:1466-06-01:0":{"b": ["Deuxième campagne d'Albanie : marche personnelle du Conquérant contre Skanderbeg", "9cdd2bfa"], "d": ["Pour briser la résistance de Skanderbeg (İskender Bey), qui durait depuis plus d'un quart de siècle, le sultan Mehmed le Conquérant organisa en 1466-1467 de grandes campagnes qu'il commanda en personne. L'armée ottomane assiégea Akçahisar (Kruja) et construisit la forteresse d'Elbasan (İlbasan) afin de contrôler la région. La campagne brisa l'échine de la résistance albanaise sans réussir à faire tomber la forteresse ; la soumission complète de la région devait demander dix ans après la mort de Skanderbeg.", "00e75aca"]},
"OLAYLAR_EK5:1467-11-10:0":{"b": ["Effondrement de l'État qaraqoyunlu : mise à mort de Djihân Châh", "30bc6358"], "d": ["Djihân Châh, souverain qaraqoyunlu, surpris par une attaque alors qu'il rentrait d'une campagne contre Uzun Hasan, que l'hiver avait contraint à s'interrompre, fut tué en fuyant entre Bingöl et Kiği. L'État ne se remit pas de ce coup ; le dernier souverain, Hasan Ali, fut fait prisonnier et tué en 1469 par Uğurlu Mehmed, fils d'Uzun Hasan. La domination qaraqoyunlu, qui avait duré près d'un siècle en Anatolie orientale, en Azerbaïdjan et en Irak, passa ainsi aux Aqqoyunlu.", "5a5288e7"]},
"OLAYLAR_EK5:1468-01-17:0":{"b": ["Mort de Skanderbeg : extinction de la résistance albanaise", "9158c35f"], "d": ["Skanderbeg (İskender Bey), élevé à la cour ottomane, qui s'était révolté en 1444 après la défaite d'Izladi et avait résisté en Albanie plus d'un quart de siècle, mourut à Lezhë (Leş), où il s'était réfugié. Cette résistance, qui avait à maintes reprises occupé les armées ottomanes sous Murad II et sous le Conquérant, perdit avec sa mort sa direction centrale. Le front albanais, entretenu par la papauté et Venise, s'étant effondré, les Ottomans prirent en dix ans Akçahisar et Scutari et rattachèrent définitivement la région à leurs terres.", "5c7cffad"]},
"OLAYLAR_EK5:1475-01-10:0":{"b": ["Défaite de Racova (Vaslui) en Moldavie", "a1a74bf7"], "d": ["Le voïvode de Moldavie Étienne le Grand attira dans un terrain marécageux les forces ottomanes placées sous le commandement du beylerbey de Roumélie Hadım Süleyman Pacha et leur infligea une lourde défaite. L'une des plus lourdes défaites terrestres du règne du Conquérant, cette déroute eut un grand retentissement en Europe et valut à Étienne une renommée dans le monde de la croisade. Le sultan devait partir en personne en campagne l'année suivante pour se venger.", "3247c9fe"]},
"OLAYLAR_EK5:1476-07-26:0":{"b": ["Victoire d'Akdere (Valea Albă) : campagne de Moldavie", "45a66791"], "d": ["Parti en personne en campagne pour venger la déroute de Racova de l'année précédente, le sultan Mehmed le Conquérant infligea une grande défaite à l'armée ottomane et aux troupes moldaves au lieu dit Akdere et entra à Suceava, centre de la principauté. Les forteresses ne purent toutefois être prises ; à cause de la disette, de la peste qui se déclara parmi les janissaires et des préparatifs hongrois, l'armée dut se retirer. L'allégeance définitive de la Moldavie ne devait être obtenue que dans les années suivantes, avec la prise de Kilia et d'Akkerman en 1484.", "27b9dd1c"]},
"OLAYLAR_EK5:1478-06-15:0":{"b": ["Conquête d'Akçahisar (Kruja) et achèvement de l'Albanie", "559a79b4"], "d": ["Dix ans après la mort de Skanderbeg, la conquête de l'Albanie fut en grande partie achevée en 1478 avec la prise d'Akçahisar, de Drivasto, de Lezhë (Leş) et de Žabljak. La chute de la forteresse de Kruja, qui avait résisté des années aux armées ottomanes et symbolisait la résistance de Skanderbeg, signifiait la fin de l'alliance vénéto-albanaise dans la région. Quant à Scutari, la seule restante, elle devait être cédée aux Ottomans par le traité d'Istanbul signé l'année suivante.", "4f6059e8"]},
"OLAYLAR_EK5:1479-01-01:0":{"b": ["Rattachement de la presqu'île de Taman", "4ef917b8"], "d": ["Après la prise de Caffa et de Kertch en 1475, la flotte que le sultan Mehmed le Conquérant avait envoyée vers les côtes du Caucase s'empara, avec Anapa et Kopa, de Matrega (Tamatarkha), la colonie génoise de la presqu'île de Taman. Les deux rives du détroit furent ainsi placées sous contrôle et l'entrée de la mer d'Azov fut entièrement contrôlée. Taman fut rattachée au sandjak de Caffa en tant que porte ouverte sur le Caucase du Nord.", "74a0de9f"]},
"OLAYLAR_EK5:1480-07-28:0":{"b": ["Échec du siège de Rhodes", "35a85c28"], "d": ["Sur l'ordre du sultan Mehmed le Conquérant, une flotte de 160 bâtiments placée sous le commandement de Mesih Pacha assiégea Rhodes au printemps 885 (1480) et l'île resta bloquée trois mois. Les chevaliers de Saint-Jean, conduits par le grand maître Pierre d'Aubusson, résistèrent avec vigueur malgré de lourdes pertes ; l'assaut final du 20 Djumâdâ al-ûlâ 885 ayant lui aussi été repoussé, la flotte se retira le 3 août. Après cet échec, les remparts de la ville furent entièrement refaits et firent d'elle la place la plus forte d'Europe ; l'île ne put être prise qu'en 1522 par Soliman le Magnifique.", "23334bd0"]},
"OLAYLAR_EK5:1481-06-22:0":{"b": ["Bataille de Yenişehir : défaite de Djem Sultan", "c35abee2"], "d": ["Les deux frères qui s'étaient mis en mouvement pour le trône après la mort du Conquérant se trouvèrent face à face dans la plaine de Yenişehir, et Djem Sultan subit une défaite décisive. Le prince, qui avait régné dix-huit jours à Bursa et y avait fait lire la khutba en son nom, dut, après sa défaite, se réfugier d'abord à Konya, puis en terre mamelouke. Yenişehir ouvrit la crise dynastique la plus durable de l'histoire ottomane : la question de Djem devait paralyser pendant quatorze ans la politique extérieure ottomane face à l'Europe.", "9d30204e"]},
"OLAYLAR_EK5:1482-01-01:0":{"b": ["Annexion de l'Herzégovine", "bf247891"], "d": ["Après la conquête de la Bosnie en 1463, les terres du duché d'Herzégovine, resté debout, passèrent par étapes sous administration ottomane : Trebinje et Mostar furent prises en 1466, le sandjak d'Herzégovine fut constitué en 1470, et les dernières terres du duché sur la côte adriatique, avec Herceg Novi, furent conquises au début de 1482 et rattachées au sandjak. La région montagneuse située derrière l'Adriatique devint ainsi entièrement ottomane, et la Bosnie et l'Herzégovine formèrent une seule géographie administrative. Le fils du dernier duc, entré à la cour ottomane, est Hersekzâde Ahmed Pacha, qui devait s'élever jusqu'au grand vizirat.", "0522e47f"]},
"OLAYLAR_EK5:1482-07-29:0":{"b": ["Djem Sultan se réfugie à Rhodes", "2228d6da"], "d": ["Sa tentative de siège de Konya étant elle aussi restée sans résultat, Djem Sultan s'enfuit d'Anatolie avec une trentaine d'hommes, gagna Rhodes et fut accueilli en grande pompe par les chevaliers de Saint-Jean. L'hospitalité se transforma toutefois bientôt en captivité ; le prince, cédé d'abord à la France, puis à la papauté, devint un atout aux mains de la politique européenne. Bayezid II dut verser un paiement annuel en contrepartie de la détention de son frère, et les initiatives militaires ottomanes en direction de l'Occident furent suspendues jusqu'à la mort de Djem.", "05ca0dd6"]},
"OLAYLAR_EK5:1485-01-01:0":{"b": ["Début de la guerre ottomano-mamelouke (front de Cilicie)", "3fe3f0c7"], "d": ["La lutte d'influence sur les Dulkadıroğulları et l'hostilité laissée par le refuge de Djem Sultan en terre mamelouke déclenchèrent en 1485 une guerre de six ans entre les deux grandes puissances sunnites. Dans les combats qui se déroulèrent en Cilicie, autour d'Adana et de Tarse, aucune des parties ne put prendre l'avantage sur l'autre ; les armées ottomanes reçurent plusieurs coups sévères. Cette guerre est la première phase de la rupture des relations ottomano-mamelouks et ouvre le processus qui devait s'achever trente ans plus tard avec les campagnes de Selim Ier Yavuz à Mardj Dâbiq et à Ridâniyya.", "08141630"]},
"OLAYLAR_EK5:1491-05-01:0":{"b": ["Paix ottomano-mamelouke : médiation de Tunis", "60dd6719"], "d": ["Dans la guerre ottomano-mamelouke commencée en 1485, les parties ne purent remporter de victoire décisive ; un accord fut atteint en 1491 grâce à la médiation du souverain de Tunis, Osman le Hafside. Le traité ramena en grande partie les frontières à ce qu'elles étaient avant la guerre et le règlement de comptes entre les deux États islamiques fut ajourné pour une génération. Cette lutte d'usure de six ans est l'une des principales raisons de la politique extérieure prudente de Bayezid II et de l'accent qu'il mit sur les arrangements intérieurs plutôt que sur une orientation vers l'est.", "406d3b78"]},
"OLAYLAR_EK5:1492-08-01:0":{"b": ["Accueil dans l'Empire ottoman des Juifs séfarades expulsés d'Espagne", "5c2b5c24"], "d": ["Après la chute de Grenade, une partie des Juifs qui fuyaient les persécutions de l'Inquisition en Espagne se réfugièrent en terre ottomane et furent installés dans diverses villes. Sous l'administration ottomane, ces communautés séfarades jouirent d'une liberté qu'elles n'avaient jamais connue jusque-là : s'installer où elles le souhaitaient, vivre leur foi, ouvrir des établissements d'enseignement et construire de nouvelles synagogues. Cette migration, qui transforma la vie économique de Salonique et d'Istanbul grâce à l'imprimerie, à la médecine et aux connaissances financières que les Séfarades apportaient avec eux, devint l'exemple le plus commenté en Europe de l'ordre de tolérance ottoman.", "b5b4a53b"]},
"OLAYLAR_EK5:1495-02-25:0":{"b": ["Mort de Djem Sultan : fin d'un otage de quatorze ans", "f6588b70"], "d": ["Djem Sultan, cédé par la papauté au roi de France Charles VIII, mourut à Castel Capuana après avoir quitté Rome le 27 janvier 1495 ; les sources rapportent qu'il aurait pu être empoisonné par des milieux pontificaux. La mort du prince, que les États européens avaient tenu pendant quatorze ans comme une carte de menace contre l'Empire ottoman, libéra enfin les mains de Bayezid II. De fait, le sultan devait déclarer ensuite la guerre à Venise et conduire sa flotte à sa première grande victoire.", "8f2579d5"]},
"OLAYLAR_EK5:1499-08-28:0":{"b": ["Victoire navale de Sapienza (Zonchio) : premier grand succès naval en Méditerranée", "9754aaef"], "d": ["Bayezid II, qui avait les mains libres avec la fin de la question de Djem, déclara la guerre à Venise en 1499 ; la flotte ottomane battit la flotte vénitienne au large de Sapienza (Zonchio) et remporta ainsi la première grande victoire navale en Méditerranée. Par cette victoire, la flotte proclama qu'elle pouvait désormais tenir tête à Venise sur mer.", "5fa6989c"]},
"OLAYLAR_EK5:1502-03-01:0":{"b": ["Chute du khanat de la Horde d'Or et essor de la Crimée", "0d1dc515"], "d": ["Son dernier souverain, Cheikh Ahmed Khan (1481-1502), ne put sauver son pays de la crise dans laquelle il était tombé, et le khanat de la Horde d'Or disparut de l'histoire en 1502 sous le coup de Mengli Giray, khan de Crimée. À la suite des querelles de trône et du morcellement, les khanats de Crimée, de Kazan, des Nogaï, d'Astrakhan et de Sibir apparurent sur les anciennes terres de la Horde d'Or. Cette victoire de la Crimée, placée sous protection ottomane, rendit incontestable l'influence ottomane au nord de la mer Noire, tandis que Moscou devait combler au siècle suivant le vide né dans la région.", "9314f239"]},
"OLAYLAR_EK5:1502-12-14:0":{"b": ["Fin de la guerre ottomano-vénitienne et paix", "125b1526"], "d": ["La guerre commencée en 1499, qui avait ébranlé Venise par Sapienza, Lépante et la perte de Modon et de Coron, s'acheva par la paix en 1502. Venise, ayant perdu ses bases les plus importantes en Morée, dut reconnaître la supériorité ottomane en échange de la conservation de ses privilèges commerciaux en Méditerranée orientale. Le règne de Bayezid II, tenu pour prudent, avait par cette guerre élevé pour la première fois l'Empire ottoman au rang de véritable puissance navale en Méditerranée.", "3d102f53"]},
"OLAYLAR_EK5:1511-07-02:0":{"b": ["Révolte de Chahkulu : soulèvement kızılbaş s'étendant de la région de Teke à Sivas", "3beadca7"], "d": ["Chahkulu Baba Tekeli, qui avait ouvertement déclenché sa révolte en 1510 sous l'effet de la propagande séfévide en Anatolie, avait envahi en mars 1511 le marché d'Antalya et, en avril, battu les forces ottomanes à Kütahya et dans ses environs. Dans le dernier combat qu'il livra près de Sivas contre le grand vizir Hadım Ali Pacha, les deux camps subirent de lourdes pertes ; le grand vizir comme le chef de la révolte perdirent la vie. Ce soulèvement, qui ébranla l'autorité de l'État en Anatolie, révéla le vide du pouvoir dans les dernières années de Bayezid II et devint la raison la plus forte de la marche du prince Selim vers le trône.", "846180f5"]},
"OLAYLAR_EK5:1512-04-24:0":{"b": ["Abdication de Bayezid II et avènement de Selim Ier Yavuz", "c4cfab69"], "d": ["Dans la lutte pour le trône qu'il menait contre ses frères, le prince Selim, qui avait le soutien des janissaires, exerça une pression sous laquelle Bayezid II abdiqua le 24 avril 1512, et Selim Ier monta le même jour sur le trône, neuvième souverain ottoman. Le vieux sultan mourut en chemin, alors qu'il se rendait à Didymotique, où il était né, au village d'Abalar, près de Çorlu, le 25 Rabî' al-awwal 918 (10 juin 1512). Un règne prudent et replié sur lui-même de trente et un ans fut remplacé par l'ère de Yavuz, qui devait doubler en huit ans les frontières de l'Empire.", "7194b8c2"]},
"OLAYLAR_EK5:1513-04-01:0":{"b": ["Bataille de Yenişehir et élimination du prince Ahmed", "e2ed15dd"], "d": ["Le sultan Selim Ier Yavuz battit son frère aîné, le prince Ahmed, le plus puissant rival au trône, dans la plaine de Yenişehir près de Bursa, le fit prisonnier et l'élimina. La querelle fratricide qui durait depuis 1511 fut ainsi close et la division intérieure de l'Anatolie prit fin. Selim acquit la liberté de se tourner vers la question séfévide en s'étant assuré ses arrières.", "ed5f5ec0"]},
"OLAYLAR_EK5:1514-09-06:0":{"b": ["Entrée de Selim Ier Yavuz à Tabriz", "dad2e227"], "d": ["Après la victoire de Çaldıran, l'armée ottomane entra à Tabriz, capitale séfévide, et la khutba y fut lue au nom du sultan. Selim y resta une semaine et fit transférer à Istanbul une partie des artistes et des oulémas de Tabriz ; ce transfert devait profondément marquer l'art de cour ottoman. La ville fut abandonnée à l'approche de l'hiver et devant le mécontentement des janissaires, mais la supériorité séfévide en Orient était brisée. Les lieux qui passent aux Ottomans en ce jour ne sont pas contigus sur la carte, et c'est exact : Tabriz est une occupation militaire de neuf jours ; la plaine d'Erzincan s'était rendue sans combat pendant la campagne, mais la forteresse de Kemah, en son centre, résista du côté séfévide jusqu'au 19 mai 1515 ; Siirt fut reprise aux Séfévides par le prince de Hasankeyf Halil Bey, libéré de la prison de Chah Ismaïl à Tabriz, qui fit soumission aux Ottomans — Diyarbakır alentour resta séfévide jusqu'en 1515 et Hasankeyf jusqu'en 1517.", "3f65211e"]},
"OLAYLAR_EK5:1515-05-19:0":{"b": ["Conquête de la forteresse de Kemah sur les Séfévides", "73fd8671"], "d": ["Selim Ier Yavuz, qui avait passé l'hiver à Amasya à son retour de Çaldıran, chargea Bıyıklı Mehmed Pacha de la conquête de la forteresse fortifiée de Kemah, qui tient le point de passage de l'Euphrate. Au terme d'un siège auquel le sultan prit part en personne, la forteresse fut enlevée aux Séfévides et la porte de l'Anatolie orientale fut ouverte. Cette conquête est le premier pas concret qui transforma la victoire de Çaldıran en gain territorial durable.", "9e896ebe"]},
"OLAYLAR_EK5:1515-06-13:0":{"b": ["Victoire de Turnadağ : le beylicat de Dulkadir devient tributaire des Ottomans", "fd879145"], "d": ["Les forces ottomanes battirent au lieu dit Ördekli, entre Göksun et Andırın, le bey de Dulkadir Alâüddevle Bozkurt, qui avait adopté une attitude ambiguë durant la campagne de Çaldıran ; Alâüddevle fut tué dans cette bataille. Le beylicat ne fut pas annexé à cette date : après Alâüddevle, Şehsuvaroğlu Ali Bey fut placé par Selim Ier Yavuz à la tête du beylicat des Dulkadıroğulları, et le pays centré sur Marash et Elbistan subsista comme beylicat tributaire des Ottomans. Le tampon situé à la frontière mamelouke passa ainsi sous contrôle ottoman et la route de la campagne d'Égypte, deux ans plus tard, fut ouverte ; l'annexion ne devait avoir lieu qu'après la mise à mort d'Ali Bey.", "cf9c7460"]},
"OLAYLAR_EK5:1515-09-19:0":{"b": ["Conquête d'Âmid (Diyarbekir) et fondation du beylerbeylik de Diyarbekir", "a6867d5b"], "d": ["Après qu'İdrîs-i Bitlisî eut gagné à la cause ottomane les beys kurdes sunnites de la région, les forces séfévides ne purent résister à un long siège et les clés d'Âmid furent remises à Bıyıklı Mehmed Pacha. La ville fut faite centre du beylerbeylik de Diyarbekir, nouvellement créé. Le noyau administratif de la Haute-Mésopotamie passa ainsi aux mains des Ottomans.", "70169bcc"]},
"OLAYLAR_EK5:1516-03-26:0":{"b": ["Conquête de Harput : ouverture de la route de Diyarbekir", "564eb269"], "d": ["Hüsrev Pacha, beylerbey de Karaman, qui s'était mis en route pour délivrer du siège séfévide Diyarbekir, prise après Çaldıran, enleva, au terme d'un siège de trois jours, la forteresse de Harput, dont les environs avaient été précédemment conquis par Çerkez Hüseyin Bey. La route qui mène à Diyarbekir à l'est de l'Euphrate fut ainsi assurée.", "eb738178"]},
"OLAYLAR_EK5:1516-05-01:0":{"b": ["Bataille de Koçhisar (Kızıltepe) : défaite de Kara Han", "9ea9e843"], "d": ["L'armée ottomane placée sous le commandement de Bıyıklı Mehmed Pacha battit le gouverneur séfévide Kara Han dans une bataille rangée qui dura toute la journée, au lieu dit Koruk, dans la plaine de Dede Garkın, près de Koçhisar ; la tête coupée de Kara Han fut envoyée au camp du sultan. Les forces ottomanes entrèrent ensuite dans la ville de Mardin, mais n'y restèrent que quelques jours avant de la quitter ; la forteresse de Mardin, tenue par des garnisons séfévides, ne put être reçue qu'un an plus tard. Cette victoire, en assurant la frontière méridionale de Yavuz, rendit possible son orientation vers la campagne d'Égypte. Autres localités rattachées à la même date : Palu, Çemişgezek, Siverek.", "6bc19ce1"]},
"OLAYLAR_EK5:1516-06-05:0":{"b": ["Départ de Selim Ier Yavuz d'Istanbul pour la campagne d'Égypte", "ac258b4b"], "d": ["Selim Ier Yavuz quitta Istanbul sous l'apparence des préparatifs d'une nouvelle campagne vers l'est contre les Séfévides et se dirigea vers le sud par Akşehir. Le fait que le sultan mamelouk Qansuh al-Ghawri ait pris contact avec Chah Ismaïl et menacé le flanc oriental de l'Empire devait entraîner un prompt changement d'objectif. La campagne est le début des grandes opérations qui devaient durer deux ans et transformer l'Empire ottoman en un empire du Moyen-Orient.", "6b27f782"]},
"OLAYLAR_EK5:1516-06-20:0":{"b": ["Prise de Zabîd : première entrée des marins ottomans en mer Rouge", "38740e0c"], "d": ["Face à la pression portugaise dans l'océan Indien, les marins d'origine ottomane Hüseyin Bey et Selman Reis, envoyés en mer Rouge à la demande du sultan mamelouk Qansuh al-Ghawri, s'emparèrent de Zabîd avec leurs flottes. Cette opération, encore menée au service des Mamelouks, est la première présence effective de la marine ottomane sur la ligne mer Rouge-Inde. Un an plus tard, quand l'Égypte passa aux Ottomans, la même flotte devait être rattachée directement à Istanbul.", "f715b0aa"]},
"OLAYLAR_EK5:1516-07-30:0":{"b": ["Proclamation officielle des Mamelouks et d'Alep comme objectif de la campagne", "689e310d"], "d": ["Qansuh al-Ghawri s'étant entendu avec les Séfévides et ayant lancé son armée sur Alep, Selim Ier Yavuz déclara ouvertement que l'objectif de la campagne était le sultan mamelouk et Alep. La rivalité sourde qui durait depuis des années entre les deux États sunnites se transforma ainsi en guerre ouverte. Cette proclamation déclencha le compte à rebours de quatre semaines qui mène à Mardj Dâbiq.", "f2a137f3"]},
"OLAYLAR_EK5:1516-08-02:0":{"b": ["Échec du siège d'Aden : première tentative en mer Rouge contre les Portugais", "8ffd46f2"], "d": ["Selman Reis et Hüseyin Bey menèrent un siège de huit jours pour s'emparer d'Aden, porte de la mer Rouge ouverte sur l'océan Indien, mais durent se retirer devant les puissantes fortifications de la ville. L'impossibilité de prendre Aden devait entraver pendant de longues années la stratégie méridionale qui serait menée contre le Portugal. Cette tentative est la première épreuve de la politique ottomane dans l'océan.", "8b584b76"]},
"OLAYLAR_EK5:1516-08-24:0":{"b": ["Rattachement du beylicat des Ramazanoğulları à l'Empire ottoman", "cfaa3754"], "d": ["Lors des attributions faites après la victoire de Mardj Dâbiq, le beylicat des Ramazanoğulları, centré sur Adana, fut donné à Mahmud Bey et placé sous la souveraineté ottomane. Sorti de la suzeraineté mamelouke, le beylicat fut, au lieu d'être supprimé, laissé à la famille avec le statut d'« ocaklık » ; les Ramazanoğulları continuèrent à administrer la Cilicie en qualité de sandjak beyi ottoman. Ce régime privilégié dura jusqu'en 1608, année où Pîr Mansûr abandonna le beylicat. Autres localités rattachées à la même date : Malatya, Tarse, Mossoul, Antep.", "af7c4758"]},
"OLAYLAR_EK5:1516-08-28:0":{"b": ["Alep, Raqqa et Deir ez-Zor passent sous la souveraineté ottomane", "2088eb6a"], "d": ["Quatre jours après Mardj Dâbiq, Selim Ier Yavuz entra à Alep sans rencontrer de résistance et la khutba fut lue en son nom dans les mosquées de la ville. La chute si rapide d'Alep, tenue pour la capitale commerciale et administrative de la Syrie, montre que l'autorité mamelouke s'était effondrée dans la région. La prise de la ville ouvrit d'un coup la route de Damas et, au-delà, de l'Égypte. Autres localités rattachées à la même date : Antioche, Raqqa, Deir ez-Zor.", "6055ffc7"]},
"OLAYLAR_EK5:1516-08-29:0":{"b": ["Entrevue à Gökmeydan d'Alep avec le calife abbasside al-Mutawakkil III", "22979f42"], "d": ["Le calife abbasside du Caire al-Mutawakkil III, fait prisonnier à Mardj Dâbiq avec l'armée mamelouke, fut conduit à Gökmeydan, à Alep, en présence du sultan, et Selim Ier Yavuz lui témoigna un grand respect. Le califat du Caire, charge symbolique à l'ombre des sultans mamelouks depuis 1261, passa de fait par cette entrevue sous la protection ottomane. Le calife devait être emmené plus tard à Istanbul avec le sultan.", "b1490892"]},
"OLAYLAR_EK5:1516-09-26:0":{"b": ["Tripoli de Syrie et Hama passent sous administration ottomane", "a1e19a79"], "d": ["Après Alep et Hama, Tripoli de Syrie, sur la côte syrienne, passa elle aussi sans résistance sous administration ottomane. L'un des ports les plus actifs de la Méditerranée orientale, la ville était la porte de Damas ouverte sur la mer et le centre du commerce de la soie et du sucre. Avec sa prise, la bande côtière du Bilâd al-Châm changea entièrement de mains.", "57168655"]},
"OLAYLAR_EK5:1516-09-27:0":{"b": ["Damas (Dimachk) passe sous la souveraineté ottomane", "2b844d91"], "d": ["La voie lui étant ouverte par la reddition de Hama et de Homs après Alep, Selim Ier Yavuz atteignit Damas le 27 septembre ; il n'entra pas aussitôt dans la ville, dressa sa tente à l'extérieur, au lieu dit Mastaba, et y entra en grande cérémonie le douzième jour de son arrivée. Il demeura longtemps à Damas, y établit l'organisation administrative de la Syrie et fit construire le tombeau de Muhyî al-Dîn Ibn al-'Arabî. Le Bilâd al-Châm tout entier sortit ainsi de l'administration mamelouke. Autre localité rattachée à la même date : Beyrouth.", "7cd1cd2b"]},
"OLAYLAR_EK5:1516-10-10:0":{"b": ["Tûmân Bây proclamé sultan mamelouk au Caire", "6020d90d"], "d": ["À la mort de Qansuh al-Ghawri à Mardj Dâbiq, les émirs mamelouks portèrent sur le trône Tûmân Bây, qui devait être le dernier sultan de l'État. Le nouveau sultan, d'origine circassienne, hérita d'un État qui avait perdu la Syrie, dont le trésor était épuisé et qui était dépourvu d'armes à feu. Il devait néanmoins établir une ligne de défense devant Le Caire et organiser une dernière résistance à l'avance ottomane.", "c55b45e9"]},
"OLAYLAR_EK5:1516-12-21:0":{"b": ["Bataille de Gaza (Khan Yûnus) : défaite de Djanbirdi al-Ghazâlî", "9f1eb8cb"], "d": ["Selim Ier Yavuz envoya sur Gaza le grand vizir Hadım Sinan Pacha avec une avant-garde de quatre mille hommes. Djanbirdi al-Ghazâlî, nommé par Tûmân Bây naïb de Damas, tenta d'arrêter l'avant-garde ottomane sur la ligne Gaza-Khan Yûnus, mais subit une lourde défaite et s'enfuit en Égypte. La dispersion de la dernière force-tampon mamelouke en Palestine ouvrit entièrement la route du désert du Sinaï.", "042a934e"]},
"OLAYLAR_EK5:1516-12-28:0":{"b": ["À l'est du Jourdain : Amman passe sous administration ottomane", "9db62667"], "d": ["Après la bataille de Gaza, tandis que les forces ottomanes qui se préparaient à la campagne d'Égypte descendaient vers le sud, Amman, à l'est du Jourdain, passa elle aussi sous administration ottomane. Les villes côtières et intérieures de Palestine (Jaffa, Naplouse, Saïda, Acre, Jérusalem) avaient en revanche déjà changé de mains à l'automne 1516, après Mardj Dâbiq. Ces villes furent pendant quatre siècles administrées comme sandjaks de la province de Damas.", "fac75355"]},
"OLAYLAR_EK5:1516-12-29:0":{"b": ["Arrivée de Selim Ier Yavuz à Jérusalem", "66d7bfad"], "d": ["À Jérusalem, qui était passée sans résistance à l'administration ottomane après Mardj Dâbiq, Selim Ier Yavuz vint, après la bataille de Gaza, avec les dignitaires de l'État et des troupes. Le sultan visita le Dôme du Rocher et la mosquée al-Aqsa, confirmant le statut sacré de la ville. Jérusalem devait demeurer à partir de cette date, pendant quatre siècles pleins, jusqu'en décembre 1917, sous l'administration ottomane.", "42cf2ec1"]},
"OLAYLAR_EK5:1517-01-02:0":{"b": ["Entrée de Selim Ier Yavuz à Gaza et départ vers le désert du Sinaï", "2106bfc7"], "d": ["Après la défaite de Djanbirdi al-Ghazâlî à Khan Yûnus (21 décembre 1516), Gaza se trouvait aux mains de l'avant-garde. Le sultan entra à Gaza le 2 janvier 1517, y rejoignit Sinan Pacha, qui était à la tête de l'avant-garde, et l'armée fit ses derniers préparatifs pour le passage en Égypte. Dans le désert aride de Katya (Sinaï), de Gaza à Sâlihiyya, on devait marcher huit étapes en transportant l'eau à dos de chameau. Ce passage est la phase la plus risquée et la plus difficile sur le plan logistique de la campagne.", "5c3d7bc1"]},
"OLAYLAR_EK5:1517-01-24:0":{"b": ["Prise de Suez : porte ouverte sur la mer Rouge", "05f3324e"], "d": ["Lorsque, après la victoire de Ridâniyya, les troupes ottomanes entrèrent au Caire, Suez, à l'extrémité nord de la mer Rouge, passa elle aussi sous administration ottomane. Cet arsenal-port d'où les Mamelouks envoyaient une flotte dans l'océan Indien devint la base de la politique méridionale qui serait menée contre le Portugal. Suez est l'embouchure nord de la ligne où, trois siècles plus tard, le canal devait être ouvert.", "501facb1"]},
"OLAYLAR_EK5:1517-01-24:1":{"b": ["Première entrée des troupes ottomanes au Caire", "0a3f4f4d"], "d": ["Le lendemain de la victoire de Ridâniyya, les armées ottomanes furent autorisées à entrer au Caire et, le 24 janvier, les troupes s'établirent dans la ville. Cette entrée ne signifiait cependant pas le contrôle complet de la ville ; Tûmân Bây s'était retiré en Haute-Égypte et la résistance mamelouke n'était pas encore brisée. La conquête du Caire ne devait pas s'achever en un seul jour, mais au cours d'un processus sanglant s'étendant sur des semaines.", "32d9401c"]},
"OLAYLAR_EK5:1517-01-27:0":{"b": ["Raid de Tûmân Bây sur Le Caire et trois jours de combats de rues", "b83b6ce6"], "d": ["Tûmân Bây, qui s'était retiré en Haute-Égypte, entra soudain au Caire dans la nuit du 27 au 28 janvier avec environ sept mille hommes, engagea la résistance dans la ville et mit les troupes ottomanes dans une situation extrêmement difficile. Au cours de violents combats de rues qui durèrent trois jours, les Mamelouks tinrent provisoirement la plus grande partie de la ville. La résistance ne put être brisée que par l'intervention de l'artillerie ottomane et des renforts.", "98838d21"]},
"OLAYLAR_EK5:1517-02-08:0":{"b": ["Djanbirdi al-Ghazâlî entre au service des Ottomans", "a94ea459"], "d": ["L'ancien émir mamelouk Djanbirdi al-Ghazâlî, qui s'était retiré à Sâlihiyya après Ridâniyya, s'adressa au sultan et implora l'aman. Selim Ier Yavuz, pensant qu'il serait utile pour établir l'ordre en Égypte et en Syrie, l'accepta à son service. Ce choix est le premier grand exemple de la politique ottomane consistant à intégrer les cadres mamelouks au système plutôt qu'à les liquider.", "847c1e81"]},
"OLAYLAR_EK5:1517-02-15:0":{"b": ["Entrée solennelle de Selim Ier Yavuz au Caire et lecture de la khutba", "6d98080c"], "d": ["Après la répression des combats de rues, le sultan entra au Caire le 15 février 1517 au cours d'une très brillante cérémonie et la khutba fut lue en son nom dans les mosquées. La lecture de la khutba au Caire au nom du sultan ottoman est la proclamation de la fin juridique de la domination mamelouke, qui durait depuis 1250. Cette date est tenue pour le moment symbolique de l'achèvement de la conquête effective de l'Égypte.", "3f8589a3"]},
"OLAYLAR_EK5:1517-03-30:0":{"b": ["Capture à Terrûdja de Tûmân Bây, dernier sultan mamelouk", "7058e6ad"], "d": ["Après avoir quitté Le Caire, Tûmân Bây, qui se cachait dans le delta du Nil, fut dénoncé par les Bédouins qui lui donnaient asile et fut capturé dans la région de Terrûdja. Sa capture supprima le centre organisé de la résistance mamelouke. Le dernier sultan devait être dès lors retenu quatorze jours aux mains des Ottomans.", "5fc98f13"]},
"OLAYLAR_EK5:1517-04-13:0":{"b": ["Exécution de Tûmân Bây à Bâb Zuwayla et fin de l'État mamelouk", "ad9820be"], "d": ["Quatorze jours après sa capture, Tûmân Bây fut pendu à Bâb Zuwayla, la célèbre porte du Caire ; son corps fut ensuite inhumé dans la médersa que son oncle avait fait construire. Ainsi l'État mamelouk, qui dominait l'Égypte et la Syrie depuis 1250, disparut officiellement de l'histoire. Avec la brisure de la résistance, des villes de Haute-Égypte (Sa'îd) comme Assiout et Assouan furent elles aussi rattachées à l'administration ottomane.", "96555946"]},
"OLAYLAR_EK5:1517-04-18:0":{"b": ["Attaque de la flotte portugaise contre Djeddah et défense de Selman Reis", "52322cf5"], "d": ["Une flotte portugaise d'une trentaine de galères et de galions attaqua Djeddah ; Selman Reis dirigea la défense de la ville, empêcha l'ennemi de débarquer et coula plusieurs navires portugais. Cette défense évita que le port de La Mecque, et par là même la route du pèlerinage, ne tombât aux mains d'un État chrétien. Djeddah devait, quelques mois plus tard, être officiellement intégrée à l'administration ottomane par le serment d'allégeance du Hedjaz.", "a480f1f5"]},
"OLAYLAR_EK5:1517-05-19:0":{"b": ["Reddition d'Alexandrie à la flotte : achèvement de la conquête de l'Égypte", "386878fe"], "d": ["Exactement quatre mois après Ridâniyya et trente-six jours après l'exécution de Tûmân Bây, Alexandrie passa à l'administration ottomane à l'arrivée de la flotte ottomane placée sous la conduite de Câfer Bey au port ; des ports du delta comme Rachîd et Damiette furent rattachés au cours du même processus. Que ce grand port d'Égypte ouvert sur la Méditerranée ait été reçu des mois après la chute du Caire, et par mer et non par terre, montre clairement que la conquête n'avait pas été achevée par une seule guerre mais région par région. Alexandrie devait devenir dès lors le port vital reliant Istanbul et Le Caire. Autre localité rattachée à la même date : Rachîd (Rosette).", "52187c14"]},
"OLAYLAR_EK5:1517-07-06:0":{"b": ["Rattachement pacifique du Hedjaz : serment d'allégeance d'Abû Numayy, fils du chérif de La Mecque", "c13b98c7"], "d": ["Selim Ier Yavuz avait d'abord songé à envoyer des troupes pour prendre La Mecque et ses environs, mais y avait renoncé quand l'émir de La Mecque, le chérif Barakât, avait fait connaître sa soumission. Abû Numayy, fils de Barakât, âgé de douze ans, vint au Caire avec les présents de son père et les clés de La Mecque et fut reçu en présence du sultan. Ainsi le Hedjaz fut rattaché aux Ottomans non comme une conséquence automatique de Ridâniyya, mais cinq mois et demi plus tard, sans qu'un seul coup de feu fût tiré, par voie pacifique et par serment d'allégeance. Autre localité rattachée à la même date : Taïf.", "636183e3"]},
"OLAYLAR_EK5:1517-07-12:0":{"b": ["Adoption du titre de serviteur des Lieux saints et khutba à Médine", "63b32b59"], "d": ["Après la seconde réception de la délégation de La Mecque, Selim Ier Yavuz assuma officiellement la protection des Haramayn et commença à employer le titre de « Hâdim al-Haramayn al-Charîfayn ». Le chérif Barakât, revêtu de la robe d'honneur (hil'at) qui lui avait été envoyée, fit lire la khutba au nom du sultan ; la délégation de Médine s'étant elle aussi rendue à Istanbul, l'émirat de Barakât fut confirmé par un berat. Le sultan envoya aux habitants des Haramayn deux cent mille pièces d'or et d'abondantes provisions, inaugurant la tradition du surre, qui devait être répétée chaque année. Autres localités rattachées à la même date : Yanbu, Tabuk.", "3b3bfd8f"]},
"OLAYLAR_EK5:1517-08-28:0":{"b": ["Selman Reis entre au service ottoman et transfert de la politique de la mer Rouge", "771da99a"], "d": ["Selman Reis, qui avait défendu Djeddah contre les Portugais, vint au Caire et fut reçu en présence de Selim Ier Yavuz ; retenu quelque temps, il fut appelé à Istanbul en 1519 et s'engagea à préparer une trentaine de galères et quelques galiotes contre la menace portugaise. Cette entrevue est le début du processus par lequel la politique de la mer Rouge et de l'océan Indien, héritée des Mamelouks, fut rattachée directement à Istanbul. Outre sa qualité d'État méditerranéen, l'Empire ottoman était désormais une puissance menant aussi une politique océanique.", "c87580bd"]},
"OLAYLAR_EK5:1517-09-10:0":{"b": ["Départ de Selim Ier Yavuz du Caire et beylerbeylik de Khayr Bey", "8cd4fb23"], "d": ["Selim Ier Yavuz, qui avait passé environ huit mois en Égypte à en établir l'ordre administratif, financier et militaire, quitta Le Caire ; Khayr Bey, ancien naïb d'Alep, qui avait précipité la déroute mamelouke en retirant l'aile gauche à Mardj Dâbiq, commença à administrer l'Égypte depuis la Citadelle (Qal'at al-Djabal) en qualité de premier beylerbey ottoman d'Égypte. Le choix d'un gouverneur d'origine mamelouke était une politique de transition délibérée, qui évitait que la nouvelle administration parût étrangère à la population locale. Sur le chemin du retour, le sultan emmena à Istanbul le dernier calife abbasside al-Mutawakkil III, ainsi que des artistes et des savants éminents d'Égypte.", "c2b3bc7e"]},
"OLAYLAR_EK5:1517-09-11:0":{"b": ["Fin du califat abbasside du Caire : la tradition de la « cérémonie de transmission »", "1d357640"], "d": ["Lorsqu'il s'empara de l'Égypte, Selim Ier Yavuz emmena à Istanbul le dernier calife, al-Mutawakkil III 'Alâ Allâh, fait prisonnier à Mardj Dâbiq ; le califat abbasside du Caire, qui subsistait sans pouvoir effectif à l'ombre des sultans mamelouks depuis 1261, prit ainsi fin. En revanche, la célèbre tradition selon laquelle le califat aurait été transmis à Yavuz lors d'une cérémonie officielle à Sainte-Sophie apparaît pour la première fois à la fin du XVIIIe siècle dans l'œuvre de d'Ohsson et ne se trouve dans aucune des sources de l'époque de Yavuz. L'Encyclopédie islamique du TDV tient la tradition pour inventée, faute de source originale attestant la cérémonie ; elle note cependant aussi qu'une telle cérémonie de transmission n'était pas nécessaire, au regard de la loi religieuse, pour le transfert du califat.", "86efdf28"]},
"OLAYLAR_EK5:1518-01-01:0":{"b": ["Erzurum rattachée à l'administration ottomane : l'influence séfévide est brisée en Anatolie orientale", "78d1be02"], "d": ["Bien que l'influence ottomane dans la région se fût accrue après la victoire de Çaldıran (1514), la prise complète d'Erzurum fut retardée jusqu'à la rupture de l'influence iranienne ; la ville ne fut rattachée à l'administration ottomane qu'en 1518-19, après la campagne d'Égypte. Erzurum était passée sous la domination séfévide en 1502, lorsque Chah Ismaïl avait mis fin au beylicat des Aqqoyunlu ; cette période de seize ans se trouvait ainsi close. Le beylerbeylik d'Erzurum devait être fondé en 1534, lors de la campagne des deux Irak.", "e137cb2e"]},
"OLAYLAR_EK5:1519-03-01:0":{"b": ["Début des révoltes djalalis : soulèvement de Cheikh Djalâl de Bozok", "99bd8a99"], "d": ["Dans la région de Bozok, un certain Cheikh Djalâl proclama son mahdisme et se souleva aux alentours de Tokat ; la révolte fut réprimée, mais son nom désigna pendant un siècle tous les mouvements de brigandage et de soulèvement en Anatolie. Le djalalisme, en s'associant à la fin du XVIe siècle à la désagrégation du système du timar et à la pression démographique, se transforma en le plus durable des problèmes de sécurité intérieure de l'Empire. Les soulèvements provoquèrent en Anatolie des migrations massives appelées « grande fuite » (büyük kaçgunluk).", "ec33f73b"]},
"OLAYLAR_EK5:1519-09-01:0":{"b": ["Rattachement d'Alger à l'Empire ottoman", "b8eba4c1"], "d": ["Khayr al-Dîn Reis, qui résistait à la pression espagnole en Afrique du Nord, s'adressa à Istanbul pour tenir bon, offrit Alger au sultan, et la khutba fut lue au nom de Selim Ier Yavuz. Alger fut ainsi officiellement rattachée aux terres ottomanes ; des troupes et des canons furent envoyés à Khayr al-Dîn, avec le titre de beylerbey. Ce rattachement posa le fondement de la domination navale ottomane en Méditerranée occidentale, qui devait durer des siècles. Autres localités rattachées à la même date : Constantine, Cherchell, Médéa (Titteri), Sétif.", "42dac5d2"]},
"OLAYLAR_EK5:1520-09-21:0":{"b": ["Mort de Selim Ier Yavuz à Çorlu", "9fe83744"], "d": ["Selim Ier, qui avait en huit ans plus que doublé le territoire de l'État, quitta Istanbul le 18 juillet 1520 pour une nouvelle campagne ; une grosse tumeur apparue dans son dos l'empêcha d'aller plus loin que Çorlu. Malgré l'intervention des médecins, sa maladie s'aggrava et, après un traitement sans espoir de deux mois, il y mourut les 8-9 Chawwâl 926 (21-22 septembre 1520). Avec Çaldıran, Mardj Dâbiq et Ridâniyya, il avait arrêté l'Iran et supprimé l'État mamelouk, et apporté aux Ottomans le califat et le patronage des Haramayn. Il laissait pour seul fils : Soliman.", "39cccc63"]},
"OLAYLAR_EK5:1524-01-01:0":{"b": ["Révolte de Hâin Ahmed Pacha en Égypte", "b18bb805"], "d": ["Ahmed Pacha, envoyé gouverner l'Égypte alors qu'il attendait le grand vizirat, se proclama au Caire « al-Malik al-Mansûr Sultan Ahmed » et annonça son indépendance. La révolte fut réprimée en peu de temps et le pacha mis à mort, mais l'événement montra la fragilité du contrôle central sur la province la plus riche de l'Empire. İbrahim Pacha se rendit alors en Égypte et fit rédiger le célèbre Kanunnâme d'Égypte, qui réorganisa l'administration de la province.", "35eb542c"]},
"OLAYLAR_EK5:1529-09-08:0":{"b": ["Budin est prise et donnée à Zápolya", "fba4f89b"], "d": ["Sur la route de la campagne de Vienne, l'armée ottomane assiégea et reprit Budin, tombée aux mains de Ferdinand, et remit la ville au roi de Hongrie János Szapolyai, placé sous protection ottomane. Un modèle de royaume vassal tampon fut ainsi établi sur la Hongrie dans la rivalité habsbourgo-ottomane. Cet ordre devait durer jusqu'en 1541 ; après la mort de Zápolya, Budin devait être transformée en province ottomane directe.", "6777eb1d"]},
"OLAYLAR_EK5:1532-04-25:0":{"b": ["Soliman le Magnifique part en campagne d'Allemagne : défi à Charles Quint", "7c3d7055"], "d": ["Après l'échec du siège de Vienne et le nouveau siège de Budin par Ferdinand, le sultan partit d'Istanbul, cette fois pour attirer directement l'empereur Charles Quint en bataille rangée. L'armée devait être retardée en août par la résistance de la petite forteresse de Güns, et, l'empereur n'ayant pas offert le combat, la campagne se limiterait à des raids. Cette campagne prépara le terrain de la première paix conclue avec les Habsbourg l'année suivante.", "c3e6e378"]},
"OLAYLAR_EK5:1532-08-05:0":{"b": ["Campagne d'Allemagne et siège de Güns (Kőszeg)", "8aec937a"], "d": ["Soliman le Magnifique marcha avec son armée sur l'Autriche pour forcer Charles Quint à la bataille rangée ; la petite forteresse de Güns résista vingt-cinq jours et retarda l'avance de l'armée. L'empereur n'ayant pas offert le combat, les akıncı frappèrent les environs de Vienne et l'on rentra à l'avancée de la saison. La campagne n'apporta aucun gain territorial, mais en forçant les Habsbourg à s'asseoir à la table, elle prépara le terrain de la paix de l'année suivante.", "792fc40e"]},
"OLAYLAR_EK5:1533-01-01:0":{"b": ["Traité d'Istanbul : première paix avec les Habsbourg", "b085767a"], "d": ["Le sultan, ayant reçu l'envoyé de Ferdinand, Cornelius, consentit à un armistice, et le premier texte de paix officiel entre l'Empire ottoman et l'Autriche vit le jour. Par ce traité, Ferdinand accepta de payer un tribut annuel pour les terres hongroises qu'il tenait, et l'archiduc d'Autriche fut tenu dans le protocole pour l'égal du grand vizir. Ce statut inégal était l'expression ouverte de la prétention à la supériorité de la diplomatie ottomane au XVIe siècle.", "e51c434d"]},
"OLAYLAR_EK5:1534-09-22:0":{"b": ["Conquête de Tunis par Barberousse", "d8754216"], "d": ["Le kapudan pacha Barberousse Khayr al-Dîn Pacha, après avoir frappé les côtes d'Italie avec sa flotte, se dirigea vers Tunis, mit en fuite le souverain hafside Mulay Hasan et entra dans la ville. La prise de Tunis, par sa position qui contrôle le détroit de Sicile, retourna d'un coup l'équilibre des forces en Méditerranée occidentale en faveur des Ottomans. Cette domination ne devait toutefois pas durer : Charles Quint répondrait l'année suivante avec une grande flotte.", "b0aeb30e"]},
"OLAYLAR_EK5:1535-07-21:0":{"b": ["Perte de Tunis au profit de Charles Quint", "a691f0f8"], "d": ["Charles Quint, par une grande expédition soutenue par les flottes génoise et pontificale, s'empara de Tunis après avoir fait tomber La Goulette (Halq al-Wâdî), et rétablit Mulay Hasan sur le trône sous protection espagnole. Une garnison espagnole fut installée dans la ville, ce qui arrêta provisoirement l'avance ottomane en Méditerranée centrale. La conquête définitive de Tunis ne devait être possible que quarante ans plus tard, en 1574.", "cbb995cd"]},
"OLAYLAR_EK5:1536-03-15:0":{"b": ["Exécution d'İbrahim Pacha le Favori (Makbul)", "348aa7b8"], "d": ["İbrahim Pacha, grand vizir durant treize ans, plus proche ami de Soliman et de fait second personnage de l'État, fut étranglé et mis à mort sans qu'aucun motif fût donné au palais où il avait été convié à la rupture du jeûne. L'attitude qu'il avait adoptée lors de la campagne des deux Irak, son emploi du titre de « sultan serasker » et les équilibres au sein du palais sont tenus pour avoir joué dans sa mort. L'exécution est un tournant montrant que les grands vizirs ne jouissaient pas d'une sécurité absolue dans l'administration centrale ottomane.", "a780f3de"]},
"OLAYLAR_EK5:1537-03-12:0":{"b": ["Conquête de la forteresse de Klis et fondation du sandjak de Dalmatie", "6ffd4ebf"], "d": ["Murad Bey, kâhya de Ghazi Hüsrev Bey, converti d'origine croate, prit à Venise la forteresse stratégique de Klis, juste au nord de Split. Aussitôt après la conquête, Klis fut faite centre d'un nouveau sandjak et kaza englobant ses environs ; les limites de ce sandjak dessinèrent en grande partie le cadre de la Croatie ottomane. Cette conquête, survenue quinze ans après Knin, acheva l'ossature administrative de l'intérieur de la Dalmatie.", "8338f8aa"]},
"OLAYLAR_EK5:1537-08-25:0":{"b": ["Siège de Corfou et guerre avec Venise", "11af95bd"], "d": ["Après la campagne des Pouilles (Apulia), l'armée ottomane débarqua à Corfou et assiégea la puissante forteresse vénitienne de l'île. En raison de l'escarpement de la place, de lourdes pertes et des conditions saisonnières, le blocus fut levé et l'on se retira le 6 septembre. Le siège resta sans résultat, mais la guerre ouverte avec Venise devait aboutir au rattachement de nombreuses îles de l'Égée et de l'Adriatique à l'Empire ottoman et à la victoire de Préveza l'année suivante.", "f023c2b9"]},
"OLAYLAR_EK5:1538-09-01:0":{"b": ["Campagne de Moldavie et annexion de la région du Budjak (Bender)", "90a88a56"], "d": ["Dans la campagne dirigée contre le voïvode de Moldavie Pierre Rareș, qui n'avait pas rempli ses obligations envers les Ottomans, Suceava fut prise et la ville de Iași pillée par le khan de Crimée Sâhib Giray. Le sultan plaça Étienne Lăcustă (Çekirge Stefan) à la voïvodie et rattacha directement aux terres ottomanes la région de Budjak (Bessarabie du Sud) avec Bender. Cette annexion fut l'un des maillons qui firent du littoral nord-ouest de la mer Noire une mer intérieure ottomane. La Moldavie était déjà une voïvodie tributaire des Ottomans ; cette campagne ne prit pas la terre à un État étranger, mais retira seulement au voïvode l'administration intérieure de Bender et du Budjak pour la rattacher directement au sultan ; le reste de la voïvodie conserva son statut tributaire. La même structure devait être répétée en 1484 à Kilia et à Akkerman, et en 1713 à Khotin : les forteresses frontières directement, les terres de l'intérieur tributaires.", "96376de1"]},
"OLAYLAR_EK5:1543-08-10:0":{"b": ["Conquête d'Esztergom et de Székesfehérvár (Istolni Belgrad)", "efca9e05"], "d": ["Dans la campagne de Hongrie que Soliman le Magnifique conduisit en personne, Esztergom, centre religieux du royaume de Hongrie et siège archiépiscopal, passa sous administration ottomane après un siège de deux semaines et demie. Puis Istolni Belgrad, ville du couronnement des rois de Hongrie, fut prise à son tour, achevant la ceinture défensive de la province de Budin. Esztergom devait demeurer jusqu'en 1595 aux mains des Ottomans comme forteresse clé de la ligne du Danube.", "93577806"]},
"OLAYLAR_EK5:1547-06-18:0":{"b": ["Traité d'Istanbul : paix de cinq ans avec les Habsbourg", "41f81773"], "d": ["Une paix de cinq ans fut signée entre l'Empire ottoman et les Habsbourg ; Ferdinand accepta de payer 30 000 ducats par an pour les terres hongroises qu'il tenait. Le traité consacra juridiquement la situation de fait d'une Hongrie divisée en trois. La sécurisation du front occidental donna à Soliman la possibilité d'organiser de nouvelles campagnes contre l'Iran.", "36cfadaa"]},
"OLAYLAR_EK5:1552-07-27:0":{"b": ["Occupation des palankas du Banat méridional par les forces envoyées de Timişoara : Versec, Haram, Keve", "edca0921"], "d": ["Après la reddition de Timişoara à l'armée ottomane, les troupes détachées de l'armée de siège se dirigèrent vers les petites palankas du Banat ; selon le récit de Bánlaky, les palankas de Versec, Facset, Mehádia, Csákóvár, Haramvár et Keve furent occupées par ces forces. Haram, sur la rive du Danube, passa ainsi elle aussi aux mains des Ottomans.", "a5906d21"]},
"OLAYLAR_EK5:1553-02-01:0":{"b": ["Alliance ottomano-française : la flotte française passe sous les ordres ottomans", "a8e01b22"], "d": ["Par le traité du 1er février 1553, la flotte de France fut mise à la disposition de la flotte ottomane ; des opérations communes contre l'Espagne en Méditerranée occidentale étaient prévues. Après le traité, Dragut Reis partit en campagne le 15 juin 1553 avec quarante-cinq galères pour soutenir la France. Ce fut le premier traité d'alliance officiel à faire passer le terrain commercial des capitulations de 1536 à une coopération militaire.", "bfa2fc2d"]},
"OLAYLAR_EK5:1553-10-05:0":{"b": ["Exécution du prince Mustafa à Ereğli de Konya", "dec36858"], "d": ["Le prince Mustafa, qui était entré dans la tente de son père pour rejoindre l'armée réunie en vue de la campagne de Nakhitchevan, rencontra les bourreaux au moment de se présenter en audience et fut étranglé. Le meurtre de l'héritier présomptif, très aimé de l'armée, provoqua une profonde colère parmi les janissaires, et Rüstem Pacha fut révoqué du grand vizirat. L'événement est entré dans la littérature et la mémoire populaire comme l'un des tournants les plus controversés de la politique ottomane à l'égard des princes.", "ce2742ae"]},
"OLAYLAR_EK5:1559-05-30:0":{"b": ["Bataille des princes à Konya", "1c8de387"], "d": ["Le prince Bayezid, entré dans la lutte pour le trône, arriva devant Konya avec environ 30 000 hommes et fut vaincu en deux jours de combats par son frère, le prince Selim. Défait, Bayezid se réfugia en Iran, auprès de Chah Tahmasp, par Amasya. La bataille transforma la crise de succession des dernières années de Soliman en une question de politique extérieure.", "d466cfc5"]},
"OLAYLAR_EK5:1560-05-14:0":{"b": ["Victoire navale de Djerba", "c7b905c1"], "d": ["La flotte ottomane placée sous le commandement de Piyale Pacha dispersa devant Djerba, par une manœuvre de division en deux, la flotte alliée hispano-génoise-maltaise réunie pour reprendre Tripoli. Les alliés perdirent la plus grande partie de leurs flottes, et la forteresse de l'île tomba peu après. Djerba est tenue pour la seconde grande victoire navale, après Préveza, à avoir consolidé la supériorité ottomane en Méditerranée.", "e987b794"]},
"OLAYLAR_EK5:1562-07-23:0":{"b": ["Exécution du prince Bayezid à Qazvin", "a759de14"], "d": ["Le prince Bayezid, réfugié en Iran, fut, au terme de longs marchandages, livré par Chah Tahmasp à la délégation ottomane et étranglé avec ses quatre fils. En contrepartie de cette remise, les Séfévides obtinrent d'importantes concessions matérielles et des garanties de frontière. Avec cette exécution, le dernier obstacle à l'avènement de Selim II fut levé et l'ordre de paix du traité d'Amasya fut préservé.", "cf625eb3"]},
"OLAYLAR_EK5:1567-04-01:0":{"b": ["Révolte du Yémen et campagne du Yémen de Koca Sinan Pacha", "c8218d8e"], "d": ["L'imam zaydite al-Mutahhar se souleva, au motif que les impôts étaient levés de force, et chassa l'administration ottomane de la plus grande partie du Yémen. Koca Sinan Pacha, envoyé d'Istanbul, rétablit la domination ottomane dans la région par les opérations qu'il mena de 1568 à 1570, en prenant Kawkabân après un long siège. La campagne eut une importance vitale pour conserver le contrôle de la porte méridionale de la mer Rouge et de la route commerciale de l'océan Indien.", "d4771f85"]},
"OLAYLAR_EK5:1567-10-01:0":{"b": ["Alliance défensive avec le sultanat d'Atjèh et aide dans l'océan Indien", "8e835f24"], "d": ["Les envoyés d'Atjèh, qui avaient demandé l'aide de Soliman face aux attaques portugaises, présentèrent leur allégeance à Selim II à la mort du sultan à Szigetvár, et une alliance défensive fut signée avec lui. Le sultan ordonna l'envoi d'Alexandrie de canons, de fusils, de munitions et d'artisans ; dix-sept navires de guerre furent préparés pour être dirigés vers les eaux indiennes. L'aggravation de la révolte du Yémen empêcha la flotte de partir, mais les artilleurs et artisans ottomans qui parvinrent à Atjèh laissèrent une trace durable dans la région.", "65c41562"]},
"OLAYLAR_EK5:1570-09-09:0":{"b": ["Conquête de Nicosie", "413d866b"], "d": ["Après un siège commencé le 25 juillet 1570 et qui dura quarante-cinq jours, Nicosie, capitale de Chypre sous administration vénitienne, se rendit à l'armée ottomane. La chute du centre de l'île resserra la résistance vénitienne dans la forteresse de Famagouste. La conquête eut un grand retentissement en Occident et hâta le processus menant à la constitution de la flotte de la Sainte Ligue sous la direction du pape.", "1ef832d4"]},
"OLAYLAR_EK5:1572-06-01:0":{"b": ["Reconstruction de la flotte après Lépante", "db51fe44"], "d": ["La première tâche de Kılıç Ali Pacha, nommé kapudan pacha après le désastre de Lépante, fut de reconstruire la flotte, qui avait subi de lourdes pertes ; les arsenaux travaillèrent sans interruption durant l'hiver 1571-1572. En juin 1572, une nouvelle flotte d'environ 250 galères et 300 galères de reis volontaires prit la mer en Méditerranée. Ce rapide redressement montra que Lépante n'avait pas brisé durablement la puissance navale ottomane.", "324f2d99"]},
"OLAYLAR_EK5:1573-03-07:0":{"b": ["Traité d'Istanbul avec Venise : reconnaissance de Chypre", "4d08ef50"], "d": ["Venise, restée seule après la dissolution de la Sainte Ligue, conclut une paix séparée avec l'Empire ottoman, reconnut officiellement que Chypre appartenait aux Ottomans et consentit à payer une indemnité de guerre. Le traité révéla clairement que la victoire de Lépante n'avait procuré aucun gain politique au monde chrétien. Venise devait éviter pendant soixante-dix ans d'entrer directement en guerre avec l'Empire ottoman.", "de6151ba"]},
"OLAYLAR_EK5:1574-12-13:0":{"b": ["Mort de Selim II", "c289f5ee"], "d": ["Selim II, après être tombé, ne put paraître au divan pendant environ deux mois, puis mourut. Sa mort fut tenue secrète au palais pendant douze jours, jusqu'à ce que son fils aîné Murad, de Manisa, arrive à Istanbul. Les sources divergent sur le jour de la mort : Selânikî dit le 15 décembre ; Gerlach, Mehmed b. Mehmed et Cenâbî disent le 13 décembre.", "e9e279ab"]},
"OLAYLAR_EK5:1574-12-22:0":{"b": ["Annonce de la mort de Selim II et avènement de Murad III", "84334d70"], "d": ["La mort de Selim II et l'avènement de Murad III, amené de Manisa, furent officiellement annoncés le 22 décembre 1574. Le nouveau sultan devait rester vingt et un ans sur le trône, et son règne serait marqué à l'est par de longues guerres d'Iran, à l'ouest par la veille de la Longue Guerre et, à l'intérieur, par l'altération de l'akçe. Jusqu'à la mort de Sokollu Mehmed Pacha en 1579, l'ancien ordre se maintint dans la conduite de l'État.", "3e1ec091"]},
"OLAYLAR_EK5:1578-08-04:0":{"b": ["Bataille de l'oued al-Makhâzin (Ksar el-Kébir) : Abd al-Malik, soutenu par les Ottomans, anéantit l'armée portugaise", "21280dac"], "d": ["Abd al-Malik, installé sur le trône du Maroc avec l'appui ottoman, anéantit à l'oued al-Makhâzin la grande armée du roi de Portugal Sébastien ; comme trois souverains moururent à la fois dans cette bataille, elle est appelée dans les sources occidentales « bataille des Trois Rois ». La puissance militaire du Portugal s'effondra et le pays passa peu après aux mains de l'Espagne. Abd al-Malik mourut lui aussi dans la bataille ; son frère Ahmed al-Mansûr, qui lui succéda, annonça la victoire à Istanbul par une délégation. Les relations entre les deux États restèrent au niveau d'un échange d'ambassadeurs et de présents, non d'un tribut ni d'une sujétion, et se tendirent peu après à propos de la question des présents.", "0ddf3962"]},
"OLAYLAR_EK5:1592-06-19:0":{"b": ["Conquête de Bihać", "651a7275"], "d": ["Le beylerbey de Bosnie Telli Hasan Pacha, après avoir pris en novembre 1591 Ripač, avant-poste de Bihać, s'empara en 1592 de la ville et de la forteresse elles-mêmes ; au terme d'un siège de dix jours, le commandant Lamberg se rendit. Cette conquête repoussa la frontière de la Bosnie le long de la rivière Una et fut le dernier grand gain ottoman à la veille de la Longue Guerre, qui devait éclater un an plus tard avec la mort de Telli Hasan Pacha devant Kupa.", "b6814991"]},
"OLAYLAR_EK5:1593-07-01:0":{"b": ["Début de la « Longue Guerre » ottomano-autrichienne", "bd22c392"], "d": ["À la suite de la défaite et de la mort en martyr du beylerbey de Bosnie Telli Hasan Pacha devant Kupa (Sisak), l'Empire ottoman déclara la guerre à l'Autriche et la Longue Guerre, qui devait durer treize ans, commença. Cette guerre, où l'infanterie à armes à feu fut déterminante, accéléra dans l'armée ottomane l'emploi de sekban et de soldats à fusil et approfondit le déclin du sipahi à timar. La guerre devait prendre fin en 1606 par le traité de Zsitvatorok.", "f309a27f"]},
"OLAYLAR_EK5:1593-07-19:0":{"b": ["Koca Sinan Pacha part en campagne contre l'Autriche : première campagne de la Longue Guerre", "d4a2f46d"], "d": ["Après la défaite et la mort en martyr du beylerbey de Bosnie Hasan Pacha devant Siska (Sisak), le grand vizir Koca Sinan Pacha, par de brillants discours et promesses, convainquit le sultan d'entrer en guerre et se mit en route avec 12 000 janissaires et d'autres troupes. S'ouvrit ainsi la première campagne de la guerre ottomano-autrichienne, qui devait durer treize ans.", "0f217276"]},
"OLAYLAR_EK5:1594-09-27:0":{"b": ["Conquête de Yanıkkale (Győr)", "14b75207"], "d": ["Le grand vizir Koca Sinan Pacha reçut la reddition de Yanıkkale, tenue pour le verrou de la route de Vienne, après un siège de plus d'un mois. La chute de la forteresse provoqua une grande panique en Europe et fut le plus brillant gain ottoman de la Longue Guerre. La place ne devait toutefois être conservée que quatre ans.", "a634af40"]},
"OLAYLAR_EK5:1595-01-17:0":{"b": ["Mort de Murad III", "1b62e886"], "d": ["Après un règne de vingt et un ans, Murad III mourut au moment où l'armée de Valachie incendiait Brăila et s'étendait jusqu'à Silistra, et il fut inhumé dans le cimetière de Sainte-Sophie. Son fils Mehmed III, appelé de Manisa, parvint à Istanbul dix jours plus tard et monta sur le trône (27 janvier 1595).", "1deabc61"]},
"OLAYLAR_EK5:1595-09-02:0":{"b": ["Perte d'Esztergom au profit de l'Autriche", "f420d333"], "d": ["N'ayant pas reçu de secours suffisant lors du siège dirigé par Karl von Mansfeld, la garnison d'Esztergom remit la forteresse à l'archiduc Matthias. Avec la fin d'une domination ottomane de cinquante-deux ans, la chaîne défensive de la ligne du Danube fut rompue et Budin se trouva directement menacée. La forteresse ne put être reprise que dix ans plus tard, en 1605.", "7617d6f2"]},
"OLAYLAR_EK5:1596-10-12:0":{"b": ["Conquête de la forteresse d'Eger", "3e511629"], "d": ["Après trois semaines de lutte, la puissante forteresse d'Eger, que les Ottomans n'avaient jamais pu prendre, tomba par la reddition de la garnison. Cette conquête, à laquelle le sultan assista en personne, répara dans une certaine mesure le moral entamé par la perte d'Esztergom, et la province d'Eger fut fondée. Avec la victoire de Mezőkeresztes remportée deux semaines plus tard, 1596 fut l'année la plus réussie de la Longue Guerre pour les Ottomans.", "5dc53fa9"]},
"OLAYLAR_EK5:1598-03-29:0":{"b": ["Perte de Yanıkkale (Győr)", "b4ccc679"], "d": ["Les troupes commandées par Miklós Pálffy et Adolf von Schwarzenberg reprirent Yanıkkale en faisant sauter les portes de la forteresse par un coup de main. La perte de cette forteresse, que Koca Sinan Pacha avait obtenue quatre ans plus tôt au prix de grands efforts, fit s'effondrer la ligne avancée ottomane en Hongrie. Bien que les forces ennemies qui assiégèrent Budin la même année aient été repoussées, l'équilibre de la guerre se transformait peu à peu en une guerre d'usure.", "80bf88e0"]},
"OLAYLAR_EK5:1599-01-01:0":{"b": ["Révolte de Karayazıcı Abdülhalim", "30493b0d"], "d": ["Karayazıcı Abdülhalim, qui rassemblait les sekban et les levend ayant déserté l'armée pendant la Longue Guerre, prit sous son contrôle une vaste région d'Anatolie centrale, s'empara de la forteresse d'Urfa (novembre 1599), proclama sa souveraineté sous le titre de « Halim Châh » et envoya des firmans portant sa propre tughra. Premier chef de la grande vague djalali, Karayazıcı mourut en 1602 et son mouvement fut poursuivi par son frère Deli Hasan. La révolte est le début de la période de la « grande fuite », où les paysans d'Anatolie abandonnèrent leurs terres en masse.", "ceda9161"]},
"OLAYLAR_EK5:1601-09-10:0":{"b": ["Défense de Kanije par Tiryaki Hasan Pacha", "d56a5e6a"], "d": ["L'archiduc Ferdinand et ses alliés, qui voulaient reprendre Kanije, conquise un an plus tôt, assiégèrent la forteresse plus de deux mois ; Tiryaki Hasan Pacha résista avec ses 9 000 hommes. Bien que n'ayant reçu aucune aide de l'extérieur, il repoussa les assauts généraux et, par des sorties, contraignit l'ennemi à se retirer en subissant de lourdes pertes. La défense est devenue une épopée dans l'historiographie ottomane, et le « Siège de Kanije » est devenu à lui seul un genre littéraire.", "edc6d7b6"]},
"OLAYLAR_EK5:1603-12-20:0":{"b": ["Mort de Mehmed III et avènement d'Ahmed Ier", "da735fde"], "d": ["À la mort de Mehmed III le 20 décembre, son fils Ahmed Ier, âgé de quatorze ans, monta sur le trône. Qu'il fût le premier sultan à s'asseoir sur le trône étant enfant et sans avoir été envoyé en sandjak montre que l'usage consistant à former les princes en province avait de fait pris fin. Sous le règne d'Ahmed Ier, le fratricide fut abandonné au profit du principe d'« ekberiyet » (accession du plus âgé des membres masculins de la dynastie).", "a5f7151a"]},
"OLAYLAR_EK5:1605-10-03:0":{"b": ["Reprise d'Esztergom", "7330f273"], "d": ["Le grand vizir Lala Mehmed Pacha assiégea Esztergom, perdue dix ans plus tôt, et la rattacha de nouveau à l'administration ottomane. Au cours de la même campagne, Pest et Vác furent également reprises et les Ottomans redressèrent leur ligne en Hongrie. Ce succès permit de s'asseoir à la table de Zsitvatorok l'année suivante en position relativement forte ; Esztergom devait demeurer aux mains des Ottomans jusqu'en 1683.", "242d3547"]},
"OLAYLAR_EK5:1607-10-24:0":{"b": ["Victoire de la plaine d'Oruç et répression de la révolte de Canbolatoğlu", "30f93532"], "d": ["Canbolatoğlu Ali Pacha, qui avait fondé à Alep un beylicat indépendant et recherchait une alliance avec la Toscane, subit une lourde défaite dans la plaine d'Oruç face au grand vizir Kuyucu Murad Pacha. Avec le rétablissement de l'autorité centrale en Syrie, la branche la plus dangereuse de la vague djalali fut brisée. La liquidation impitoyable menée par Kuyucu Murad Pacha pendant deux ans rétablit l'ordre en Anatolie, ne fût-ce que provisoirement.", "6e620c57"]},
"OLAYLAR_EK5:1608-08-09:0":{"b": ["Victoire d'Alaçayır et répression de la révolte de Kalenderoğlu", "55db0485"], "d": ["Kalenderoğlu, chef djalali qui mettait à tribut les régions de Manisa et de Bursa, fut battu à Alaçayır par Kuyucu Murad Pacha et dut s'enfuir en Iran. Par cette victoire, la dernière des grandes armées djalalis d'Anatolie fut dispersée. La dure liquidation de Kuyucu Murad Pacha, dont on rapporte qu'il fit jeter les rebelles qu'il avait fait tuer dans des puits qu'il avait fait creuser, rétablit l'ordre à court terme, mais ne put compenser les pertes de population et de production de l'Anatolie.", "dc332b4b"]},
"OLAYLAR_EK5:1612-07-06:0":{"b": ["Premières capitulations accordées aux Pays-Bas", "5d9d117e"], "d": ["L'envoyé de la République des Provinces-Unies, Cornelis Haga, parvint à obtenir d'Ahmed Ier une capitulation (ahidnâme) de même portée que celles qui avaient été accordées à la France et à l'Angleterre. Les Pays-Bas acquirent ainsi le droit d'ouvrir une ambassade à Istanbul, des consulats dans les échelles ottomanes et de commercer sous leur propre pavillon. Cette capitulation symbolise l'entrée sur le marché ottoman des puissances maritimes du nord, qui prirent la place de Venise dans le commerce de la Méditerranée.", "7991027b"]},
"OLAYLAR_EK5:1617-11-22:0":{"b": ["Mort d'Ahmed Ier et avènement de Mustafa Ier : le principe d'ekberiyet", "9901c09e"], "d": ["Après une maladie d'estomac de cinquante et un jours, Ahmed Ier mourut à vingt-huit ans, et c'est son frère Mustafa Ier, et non son fils, qui fut porté sur le trône. Le principe de succession de père en fils fut ainsi abandonné et l'on passa de fait au système de l'« ekberiyet », où le plus âgé des membres masculins de la dynastie accède au trône. Ce premier règne, qui dura quatre-vingt-seize jours, marque aussi le début de l'ère où les princes furent élevés dans le « kafes ».", "1f866a67"]},
"OLAYLAR_EK5:1618-02-26:0":{"b": ["Déposition de Mustafa Ier et avènement d'Osman le Jeune (Osman II)", "e0f552f2"], "d": ["Mustafa Ier fut déposé au bout de quatre-vingt-seize jours au motif que sa santé mentale n'était pas bonne, et Osman II, fils d'Ahmed Ier, âgé de quatorze ans, devint sultan. Selon la tradition remontant à Hasanbeyzâde, le Kızlar Ağası Mustafa Ağa joua un rôle dans cette décision de déposition. Osman le Jeune est tenu pour le premier nom radical des débats de réforme ottomans, avec son projet d'abolir le corps des janissaires et de créer une nouvelle armée. Ce projet devait lui coûter la vie quatre ans plus tard.", "4d655aca"]},
"OLAYLAR_EK5:1618-09-26:0":{"b": ["Traité de Sérab : renouvellement de la paix avec l'Iran", "e778aca8"], "d": ["Le traité de Sérab, conclu avec l'Iran après la défaite de Pûl-i Chikasta, confirma en grande partie les clauses du traité de Nasuh Pacha de 1612 ; la quantité annuelle de soie que devaient envoyer les Séfévides fut ramenée de deux cents à cent charges. La seconde phase des guerres d'Orient, qui duraient depuis 1603, fut ainsi close. La paix ne devait pas durer : avec la perte de Bagdad en 1623, la guerre devait se rallumer.", "f14d72aa"]},
"OLAYLAR_EK5:1621-10-09:0":{"b": ["Campagne de Khotin et traité de Khotin", "bc4c823c"], "d": ["L'armée considérable que commandait en personne Osman II ne put franchir le camp fortifié établi par Chodkiewicz devant Khotin, et des mois d'assauts n'aboutirent à aucun résultat. Par le traité signé le 9 octobre, le Dniestr fut reconnu comme frontière, et les Polonais s'engagèrent à empêcher les raids cosaques. Bien que présentée comme une victoire, la campagne, restée sans résultat, renforça la méfiance du jeune sultan envers les janissaires et son intention de liquider le corps.", "7d812c58"]},
"OLAYLAR_EK5:1623-09-10:0":{"b": ["Seconde déposition de Mustafa Ier et avènement de Murad IV", "1b3a9e74"], "d": ["Mustafa Ier, remis sur le trône pour la seconde fois après le meurtre d'Osman II, fut déposé de nouveau au bout d'un an et trois mois, et Murad IV, âgé de onze ans, fut proclamé sultan. Pendant les neuf premières années, l'État fut gouverné de fait par sa mère Kösem Sultan et les notables du palais. À partir de 1632, Murad IV devait prendre personnellement le pouvoir et ouvrir une période de dure centralisation.", "6dea0fec"]},
"OLAYLAR_EK5:1623-11-28:0":{"b": ["Perte de Bagdad au profit des Séfévides", "db81be0c"], "d": ["À l'issue des marchandages que Bekir Subaşı, qui s'était soulevé à Bagdad, entama avec les Séfévides, son fils Derviş Mehmed, qui défendait la citadelle, remit la ville aux forces de Chah Abbas. La perte de l'une des villes symboles de l'héritage califal et d'une grande partie de l'Irak suscita une vive indignation à Istanbul. Reprendre Bagdad devait être pendant quinze ans le seul objectif de la politique orientale ottomane.", "ef09360d"]},
"OLAYLAR_EK5:1628-09-22:0":{"b": ["Répression de la révolte d'Abaza Mehmed Pacha, centrée sur Erzurum", "e6da2729"], "d": ["Abaza Mehmed Pacha, beylerbey d'Erzurum, qui s'était soulevé contre les janissaires en prétendant venger le meurtre d'Osman II, tint des années l'Anatolie orientale sous son contrôle et résista au centre. Contraint de se rendre à la suite du siège d'Erzurum par le grand vizir Hüsrev Pacha, il fut gracié et nommé en Bosnie. La fin de la révolte était la condition préalable pour que Murad IV pût partir en campagne contre l'Iran.", "68311e29"]},
"OLAYLAR_EK5:1634-01-08:0":{"b": ["Première exécution d'un cheikh al-islam : Ahîzâde Hüseyin Efendi", "a60a58c5"], "d": ["Le cheikh al-islam Ahîzâde Hüseyin Efendi fut exécuté près de Büyükçekmece, au motif qu'il avait joué les médiateurs dans le désordre militaire et envoyé au sultan un avertissement écrit sur la procédure judiciaire. Qu'il fût le premier cheikh al-islam ottoman à être exécuté brisa la tradition ancienne selon laquelle la peine la plus lourde pour les membres de l'ilmiye était l'exil. L'événement est tenu pour le symbole de l'autorité durcie de Murad IV et de la rupture de l'équilibre entre l'État et les oulémas.", "2822f303"]},
"OLAYLAR_EK5:1635-08-08:0":{"b": ["Conquête d'Erevan (Revan) par Murad IV", "b65a9b73"], "d": ["Parti d'Istanbul le 28 mars 1635, Murad IV assiégea Erevan les 28-29 juillet et reçut la forteresse le 8 août ; il entra ensuite dans Tabriz évacuée et la fit détruire. Le sultan fit construire au palais de Topkapı, en souvenir de la victoire, le kiosque d'Erevan. Cette campagne fut la première grande opération orientale commandée en personne par le sultan après une interruption de trente ans.", "2da4da04"]},
"OLAYLAR_EK5:1636-04-01:0":{"b": ["Perte d'Erevan (Revan) au profit des Séfévides", "fbb8dd25"], "d": ["Après le retrait de l'armée ottomane, les forces du chah Séfi assiégèrent Erevan et la reprirent en huit mois. La perte si rapide de la forteresse montra combien une domination durable était difficile à soutenir logistiquement dans le Caucase. Erevan devait aussi être laissée à l'Iran par le traité de Qasr-i Chirin de 1639, et l'Empire ottoman devait renoncer à sa prétention sur l'Azerbaïdjan.", "f90cb004"]},
"OLAYLAR_EK5:1638-12-24:0":{"b": ["Reconquête de Bagdad", "4d2f27f3"], "d": ["Murad IV, parti d'Istanbul le 8 mai 1638, reprit Bagdad, qui était depuis quinze ans aux mains des Séfévides, après un siège violent de quarante jours ; le vizir Tayyar Mehmed Pacha tomba en martyr pendant le siège. Avec la conquête de la ville, l'administration ottomane fut rétablie en Irak et le sultan prit le titre de « Conquérant de Bagdad ». La conquête, rendue durable par le traité de Qasr-i Chirin de l'année suivante, posa le fondement de l'actuelle frontière turco-iranienne.", "bb99d1fb"]},
"OLAYLAR_EK5:1640-02-09:0":{"b": ["Mort de Murad IV et avènement du sultan Ibrahim", "e2ca1ca0"], "d": ["À la mort de Murad IV, âgé de vingt-huit ans, son frère Ibrahim, seul membre masculin survivant de la dynastie, monta sur le trône. Sous le règne du nouveau sultan, qui avait longtemps vécu au kafes, les dépenses du palais et les luttes d'influence au sein du palais ébranlèrent l'ordre de l'État. Huit ans plus tard, sa déposition et son meurtre devaient donner dans l'histoire ottomane le deuxième meurtre d'un sultan.", "4c336200"]},
"OLAYLAR_EK5:1642-02-26:0":{"b": ["Reprise de la forteresse d'Azov aux cosaques", "e5fcf160"], "d": ["La forteresse d'Azov, prise par les cosaques du Don en 1637, fut évacuée devant l'opération conjointe de Sultanzâde Mehmed Pacha et du khan de Crimée Mehmed IV Giray ; les cosaques se retirèrent en incendiant la forteresse. La reprise de la porte septentrionale de la mer Noire clôt la période dangereuse où les raids cosaques s'étendaient jusqu'au Bosphore. La forteresse devait cette fois être perdue en 1696 au profit du tsar russe Pierre Ier.", "39448f1f"]},
"OLAYLAR_EK5:1645-08-22:0":{"b": ["Début de la campagne de Crète et conquête de La Canée", "a1b0c77f"], "d": ["La guerre fut déclarée à Venise sous le prétexte que des corsaires maltais avaient attaqué un navire ottoman de pèlerins et s'étaient réfugiés en Crète, et la flotte placée sous le commandement de Yûsuf Pacha débarqua des troupes dans l'île. Après un siège de cinquante-quatre jours, la forteresse de La Canée fut prise, et la première base ottomane durable fut établie en Crète. Ainsi commença la plus longue guerre de l'histoire ottomane ; l'île ne devait être entièrement conquise que vingt-quatre ans plus tard, en 1669.", "2809708a"]},
"OLAYLAR_EK5:1648-03-31:0":{"b": ["Perte de Klis au profit de Venise", "5473c22c"], "d": ["Sur le front dalmate de la guerre de Crète (Candie), la contre-attaque du commandant vénitien Leonardo Foscolo englobait aussi Klis, centre du sandjak depuis 1537 ; la forteresse passa à Venise. La concentration de toutes les forces ottomanes sur la Crète rendit impossible la reprise de cette perte à la frontière dalmate — Klis ne devait plus jamais revenir à l'administration ottomane ; le centre du sandjak fut transféré à Livno.", "d0ec59d4"]},
"OLAYLAR_EK5:1648-05-01:0":{"b": ["Début du siège de Candie", "13016b10"], "d": ["Après la prise de La Canée et de Rethymnon, l'armée ottomane mit le siège devant Candie, dernier grand point d'appui de Venise dans l'île. Ce blocus, qui devait durer vingt et un ans, est entré dans l'histoire comme l'un des plus longs sièges de l'histoire militaire mondiale. Au cours du siège, les tentatives de la flotte vénitienne pour fermer les Dardanelles portèrent la guerre au cœur de l'Égée.", "8a35e8f9"]},
"OLAYLAR_EK5:1651-09-02:0":{"b": ["Assassinat de la Grande Validé Kösem Sultan", "9d763f79"], "d": ["Kösem Sultan, âgée d'environ soixante-deux ans, fut trouvée dans une pièce du harem et tuée par le Başlala Uzun Süleyman Ağa et ses hommes, qui agissaient sur ordre de Turhan Sultan, mère de Mehmed IV. La mort de cette puissante femme de la dynastie, qui avait dirigé la politique de l'État sous trois règnes, est tenue pour la fin de fait de la période dite du « Sultanat des femmes ». L'autorité ainsi libérée ouvrit, cinq ans plus tard, la voie à l'accession de Köprülü Mehmed Pacha au grand vizirat avec des pouvoirs exceptionnels.", "d1ff09cb"]},
"OLAYLAR_EK5:1656-07-13:0":{"b": ["Désastre des Dardanelles et perte de Ténédos et de Lemnos", "e01a1f7e"], "d": ["La grande victoire navale que l'amiral vénitien Mocenigo remporta en juin 1656 devant les Dardanelles anéantit presque entièrement la flotte ottomane ; Ténédos, Lemnos et Samothrace furent ensuite occupées. Le détroit étant tombé sous le blocus vénitien, les prix des denrées s'envolèrent à Istanbul et la crainte d'une attaque contre la capitale se répandit. Ce désastre fut la cause directe de l'accession de Köprülü Mehmed Pacha au grand vizirat, en septembre 1656, avec des pouvoirs conditionnels et exceptionnels.", "31f7a914"]},
"OLAYLAR_EK5:1657-08-25:0":{"b": ["Victoire des Dardanelles et reprise de Ténédos", "603da863"], "d": ["La flotte mobilisée par Köprülü Mehmed Pacha battit la flotte vénitienne devant le détroit le 19 juillet 1657 ; les forces placées sous le commandement de Kurd Pacha reprirent ensuite Ténédos le 25 août, et le 30 août les Vénitiens évacuèrent entièrement l'île. En novembre, Lemnos fut aussi libérée, le blocus des Dardanelles fut brisé et la route de ravitaillement d'Istanbul fut rouverte. Köprülü passa en personne dans l'île pour faire réparer les fortifications ; ce succès est le premier grand gain militaire de l'ère des Köprülü.", "af4d7bfd"]},
"OLAYLAR_EK5:1658-08-27:0":{"b": ["Conquête de Yanova (Ineu) et campagne de Transylvanie", "d1089616"], "d": ["Köprülü Mehmed Pacha, parti en campagne pour châtier le prince de Transylvanie György Rákóczi II, qui avait violé la protection ottomane en partant sans autorisation en campagne contre la Pologne, marcha par Belgrade et prit la forteresse stratégique de Yanova. Un nouveau prince fut nommé en Transylvanie, et le lien de vassalité fut rappelé avec rudesse. Cette campagne fut le premier maillon de la tentative ottomane de rétablir son autorité en Europe centrale. La Transylvanie était déjà une principauté tributaire des Ottomans ; la prise de Yanova ne fut pas la conquête sur un État étranger, mais le retrait de cette forteresse de la Transylvanie tributaire à l'administration princière pour la rattacher directement à un sandjak ottoman ; le reste de la principauté demeura dans le statut tributaire.", "4e24d834"]},
"OLAYLAR_EK5:1659-02-16:0":{"b": ["Répression de la révolte d'Abaza Hasan Pacha", "4ba74321"], "d": ["Abaza Hasan Pacha, qui avait derrière lui les beylerbeys d'Anatolie et les agas des sekban contre les dures épurations de Köprülü Mehmed Pacha, déclencha un grand soulèvement en exigeant la révocation du grand vizir. La révolte fut réprimée à Alep et les meneurs furent éliminés ; ce fut la dernière résistance collective des pachas de province au centre. L'autorité de Köprülü devint ainsi incontestée, et la charge de grand vizir s'éleva de nouveau à la position de véritable centre exécutif de l'État.", "900e66b5"]},
"OLAYLAR_EK5:1660-08-27:0":{"b": ["Conquête de Varad (Oradea)", "0e6ad300"], "d": ["La forteresse et la ville de Varad furent prises dans le cadre de la campagne organisée contre le prince de Transylvanie György Rákóczi II, qui avait déclaré la guerre à l'Empire ottoman. Avec la chute de l'une des forteresses clés de la Transylvanie, une nouvelle province ottomane (la province de Varad) fut fondée dans la région. La conquête alarma les Habsbourg et fut l'une des causes directes de la guerre ottomano-autrichienne qui devait commencer trois ans plus tard. Autre localité rattachée à la même date : Varat. Ici encore, la terre ne fut pas prise à un État étranger : la Transylvanie était déjà une principauté ottomane tributaire ; le fait que Varad devienne une province retira seulement l'administration de cette ville à la principauté tributaire pour la rattacher directement au sultan, comme à Yanova deux ans plus tôt.", "991162de"]},
"OLAYLAR_EK5:1664-08-01:0":{"b": ["Bataille de Saint-Gotthard", "61ebc1f2"], "d": ["Les forces ottomanes qui avaient franchi la Raab furent arrêtées par l'armée européenne alliée placée sous le commandement de Montecuccoli et subirent de lourdes pertes. La bataille est tenue pour un tournant de l'histoire militaire, en ce qu'elle montra pour la première fois ouvertement la supériorité des tirs de l'infanterie disciplinée à armes à feu sur la charge de la cavalerie ottomane. Malgré la défaite, l'Empire ottoman réussit à obtenir des conditions avantageuses dans le traité de Vasvár signé neuf jours plus tard.", "4ab743fc"]},
"OLAYLAR_EK5:1664-08-09:0":{"b": ["Traité de Vasvár", "089c978c"], "d": ["Le traité, signé malgré la défaite de Saint-Gotthard, stipula que Uyvar et Varad resteraient aux Ottomans, que la Transylvanie serait laissée neutre sous protection ottomane, et que l'Autriche paierait un « présent » de 200 000 kuruş. Cette paix de vingt ans est l'un des rares exemples où le perdant d'une guerre a gagné à la table. Le mécontentement que le traité suscita dans l'opinion habsbourgeoise devait alimenter le mouvement hongrois central et, indirectement, la campagne de Vienne de 1683.", "61ca5d47"]},
"OLAYLAR_EK5:1671-01-01:0":{"b": ["Début du régime des deys à Alger", "e99faa51"], "d": ["L'odjak d'Alger et la taïfa des raïs (capitaines corsaires) déposèrent le dernier agha et élurent Hadji Mehmed dey à vie. À partir de cette date, Alger fut gouvernée non plus par un beylerbey nommé par Istanbul, mais par un dey que l'odjak local choisissait en son sein ; le lien ottoman se limita à la mention du nom du sultan dans la khutba, au sandjak et à l'obligation de campagne. Alger passa ainsi du statut de province à celui d'odjak ; la même transformation fut vécue par Tunis en 1705 avec les Husaynides, et par la Tripolitaine en 1711 avec les Karamanlis.", "b8decd95"]},
"OLAYLAR_EK5:1672-06-04:0":{"b": ["Début de la campagne de Pologne : Mehmed IV et Fâzıl Ahmed Pacha à la tête de l'armée", "75e15a39"], "d": ["Les attaques de la Pologne contre l'hetman d'Ukraine Petro Doroshenko, passé sous protection ottomane, se poursuivant, Istanbul demanda au roi de Pologne d'y renoncer ; faute de réponse favorable, la décision fut prise de partir en campagne contre la Pologne. Le grand vizir Fâzıl Ahmed Pacha se mit en route pour la Pologne le 4 juin 1672 avec l'armée, où se trouvait aussi le sultan. La campagne devait aboutir à la conquête de Kamaniçe et au traité de Buchach.", "7340721a"]},
"OLAYLAR_EK5:1672-08-27:0":{"b": ["Conquête de Kamaniçe et fondation de la province de Podolie", "c3f4f6d0"], "d": ["Après un siège de neuf jours, Kamaniçe, tenue pour la plus puissante forteresse de la Pologne à l'est, fut reçue ; le 2 septembre, Mehmed IV fit la première prière du vendredi dans la mosquée transformée à partir de la cathédrale. La forteresse fut faite centre et la province de Podolie fut fondée ; le drapeau ottoman atteignit son point le plus septentrional sur le territoire de l'actuelle Ukraine. Kamaniçe devait rester l'extrémité nord-ouest de l'Empire jusqu'au traité de Karlowitz de 1699.", "d89c513a"]},
"OLAYLAR_EK5:1674-08-03:0":{"b": ["Kara Mustafa Pacha reçoit Uman de la Pologne", "0d3543a0"], "d": ["Kara Mustafa Pacha, envoyé contre la Pologne, reçut Uman, l'une des forteresses aux mains des Polonais ; la ville demeura sous administration ottomane jusqu'à Karlowitz.", "bdb8e553"]},
"OLAYLAR_EK5:1678-08-21:0":{"b": ["Conquête de la forteresse de Tchyhyryn (Çehrin)", "a17cedd0"], "d": ["Après l'opération de l'année précédente, où Melek İbrahim Pacha n'avait obtenu aucun résultat, le grand vizir Merzifonlu Kara Mustafa Pacha commanda en personne, assiégea la forteresse fortifiée de Çehrin (19/21 juillet) et s'en empara le 21 août. La chute de la forteresse, symbole de la rivalité ottomano-russe sur l'hetmanat cosaque d'Ukraine, contraignit la Russie à la paix. Ce succès fut l'une des sources de l'assurance de Merzifonlu qui devait se tourner vers Vienne.", "aee53ec4"]},
"OLAYLAR_EK5:1681-02-13:0":{"b": ["Traité de Bakhtchissaraï : première paix officielle avec la Russie", "df82bc0b"], "d": ["À l'issue de négociations menées par l'intermédiaire du khan de Crimée après les campagnes de Çehrin, une paix de vingt ans fut signée entre l'Empire ottoman et la Russie, le Dniepr (Özü) étant reconnu comme frontière. C'est, comme premier traité d'ampleur entre les deux États, le document inaugural des relations ottomano-russes. Cette paix permit de sécuriser le front oriental et de diriger l'armée vers l'Europe centrale.", "56f57388"]},
"OLAYLAR_EK5:1682-09-16:0":{"b": ["Octroi à Imre Thököly du berat de royaume de Hongrie centrale", "3cd8d51d"], "d": ["Imre Thököly, noble hongrois protestant qui s'était soulevé contre la pression des Habsbourg, fut considéré à partir d'avril 1682 comme le « roi élu de la Hongrie centrale », et le 16 septembre le beylerbey de Budin, İbrahim Pacha, lui présenta les insignes de principauté. Un nouvel État hongrois vassal fut ainsi établi sous protection ottomane. Cette intervention rendit la guerre avec l'Autriche inévitable et amorça la chaîne qui mène au second siège de Vienne de l'année suivante.", "6f7f5236"]},
"OLAYLAR_EK5:1684-08-06:0":{"b": ["Perte d'Ayamavra (Leucade) au profit de Venise", "e6905fee"], "d": ["La flotte de Venise, entrée dans la Sainte Ligue, bombarda la ville puis occupa l'île d'Ayamavra, en mer Ionienne. Avec la chute de Préveza la même année, le contrôle ottoman à l'entrée de l'Adriatique fut brisé. Ces pertes furent les premières étapes de l'opération par laquelle Morosini devait s'emparer de toute la Morée en trois ans.", "8fe34c55"]},
"OLAYLAR_EK5:1685-08-11:0":{"b": ["Perte de Coron au profit de Venise", "2ed762bc"], "d": ["Les forces vénitiennes placées sous le commandement de Morosini s'emparèrent de la forteresse de Coron, à l'extrémité sud-ouest de la péninsule de Morée ; la ville devait rester dès lors trente ans sous administration vénitienne. La chute de Coron fut le premier grand gain de l'opération vénitienne en vue de la conquête de la Morée. La forteresse ne put être reprise qu'en 1715 par l'armée ottomane placée sous le commandement de Silâhdar Ali Pacha.", "506cf83e"]},
"OLAYLAR_EK5:1688-10-20:0":{"b": ["Siège de Négrepont par Venise repoussé", "aae7e6a0"], "d": ["Morosini, qui s'était tourné vers l'Égée après avoir pris la Morée, tenta de prendre Négrepont par un siège de plus de trois mois ; mais, devant les fortifications renforcées durant l'hiver 1687-1688 et la résistance de la garnison, il dut se retirer en subissant de lourdes pertes. Cet échec arrêta l'avance vénitienne dans l'Égée et ébranla le prestige militaire de Morosini. Négrepont devait aussi rester aux mains des Ottomans à Karlowitz.", "ea8430a3"]},
"OLAYLAR_EK5:1690-04-23:0":{"b": ["Perte de la forteresse de Kanije au profit de l'Autriche", "553b45f3"], "d": ["Kanije, soumise depuis janvier 1690 au blocus serré d'une armée habsbourgeoise de 60 000 hommes, après avoir résisté des mois sans recevoir de secours, fut perdue par l'accord de reddition que signa son dernier gardien, Mustafa Pacha. La domination ottomane, vieille de quatre-vingt-dix ans, prit ainsi fin dans la forteresse qu'on rappelait par la défense épique de Tiryaki Hasan Pacha. La perte de Kanije fut l'effondrement du dernier grand point d'appui ottoman à l'ouest de la Hongrie.", "dc630d57"]},
"OLAYLAR_EK5:1691-06-23:0":{"b": ["Avènement d'Ahmed II", "52947b14"], "d": ["À la mort de Süleyman II, son frère Ahmed II, âgé de quarante-neuf ans, monta sur le trône à Edirne. Son règne correspondit aux années les plus lourdes des guerres de la Sainte Ligue ; deux mois après son avènement, le grand vizir Fâzıl Mustafa Pacha tomba en martyr à Salankamen. En revanche, le système du mâlikâne mis en pratique sous son règne fut l'une des dispositions les plus importantes qui changèrent la structure à long terme des finances ottomanes.", "d3441b14"]},
"OLAYLAR_EK5:1700-07-14:0":{"b": ["Traité d'Istanbul : cession d'Azov à la Russie", "79db4724"], "d": ["À Karlowitz, on n'avait pu conclure avec la Russie qu'une trêve de deux ans seulement ; la paix durable fut signée à Istanbul après un an et demi de rudes négociations. L'Empire ottoman céda officiellement à la Russie la forteresse d'Azov, perdue en 1696, et ses environs, et renonça au tribut annuel que le khan de Crimée recevait de Moscou. En contrepartie, la Russie obtint le droit d'avoir un ambassadeur permanent à Istanbul ; la présence russe sur la côte nord de la mer Noire fut ainsi juridiquement consacrée.", "a3a5a803"]},
"OLAYLAR_EK5:1704-01-01:0":{"b": ["Début de l'administration kölemen (mamelouke) à Bagdad", "abe52618"], "d": ["Avec la nomination de Hasan Pacha, d'origine géorgienne, au gouvernement de Bagdad, commença en Irak une période où, au lieu de gouverneurs nommés par le centre, dominait un groupe dirigeant formé à partir de ses propres esclaves. Avec le gouvernement de Süleyman Pacha en 1749, le système s'enracina tout à fait, et la Sublime Porte fut contrainte de nommer non plus la personne qu'elle voulait, mais l'un des kölemen qui s'étaient emparés de l'influence. Cette structure semi-autonome, utile pour la défense de la frontière iranienne, affaiblit pendant un siècle et demi le contrôle de l'autorité centrale sur l'Irak.", "7cf655d4"]},
"OLAYLAR_EK5:1705-07-12:0":{"b": ["Fondation de la dynastie husaynide à Tunis", "cb1a98f9"], "d": ["Dans le vide d'autorité apparu après l'invasion de Tunis par les forces d'Alger, Hüseyin b. Ali, agha des sipahis d'origine turque, s'empara du beylicat et acquit sa légitimité en déclarant son allégeance au sultan ottoman. La dynastie qu'il fonda gouverna Tunis de 1705 à 1735 et de 1756 à 1957 ; un régime de beylicat se transmettant de père en fils remplaça l'administration de l'odjak. Ainsi naquit le premier exemple, dans les odjaks du Maghreb, de structures dynastiques rattachées au centre mais de fait autonomes.", "941c7858"]},
"OLAYLAR_EK5:1708-04-04:0":{"b": ["Prise d'Oran (Vahran) et de Mers el-Kébir sur les Espagnols", "b67ce06a"], "d": ["Les forces du beylerbey de l'odjak d'Alger s'emparèrent, après un long siège, d'Oran, aux mains d'une garnison espagnole depuis deux siècles, et de son port, Mers el-Kébir. Ce fut le plus grand succès remporté contre l'Espagne en Méditerranée occidentale par les odjaks du Maghreb placés sous protection ottomane, et il assura le flanc ouest d'Alger. La ville devait de nouveau subir l'occupation espagnole en 1732, mais être définitivement reprise en 1792.", "33d9da74"]},
"OLAYLAR_EK5:1711-07-21:0":{"b": ["Traité du Prut : reprise d'Azov et de Taganrog", "bac5d2a1"], "d": ["Le traité en sept articles, signé après la reddition de l'armée russe encerclée sur le Prut, stipula la restitution aux Ottomans de la forteresse d'Azov avec son territoire et ses munitions. Les fortifications de Taganrog, Kamenka et Yenikale devaient être détruites, et les parties ne devaient pas construire de nouvelles forteresses dans ces régions. L'ordre de flotte et de bases que Pierre Ier avait établi pendant seize ans à Voronej et à Azov s'effondra ; l'accès de la Russie à la mer Noire fut retardé d'environ cinquante ans.", "657d45ff"]},
"OLAYLAR_EK5:1711-07-29:0":{"b": ["Fondation de la dynastie karamanli à Tripoli de Barbarie", "e1105d4a"], "d": ["À Tripoli de Barbarie, accablée par les querelles des agas de l'odjak, Ahmed Karamanlı, officier de cavalerie, s'empara de l'administration et officialisa sa situation par le berat de beylerbey reçu d'Istanbul. Par Ahmed Pacha, son fils Mehmed Pacha et son petit-fils Yûsuf Pacha naquit une dynastie qui dura de 1711 à 1835 ; il en résulta une structure semi-indépendante, qui fonda sa propre flotte et signa directement des traités avec les États européens. Cette période ne devait prendre fin qu'en 1835, avec le rattachement direct de la province au centre.", "b1c3dd0a"]},
"OLAYLAR_EK5:1713-06-24:0":{"b": ["Traité d'Edirne avec la Russie", "14901a70"], "d": ["Les promesses faites au Prut n'ayant pas été tenues, la guerre fut déclarée deux fois encore ; enfin, les Russes ayant accepté leurs engagements, une paix durable fut signée à Edirne. Le traité confirma les conditions du Prut ; la Russie ne devait pas s'immiscer dans les affaires de Pologne, devait se retirer des terres cosaques et ne pas faire obstacle au retour dans son pays du roi de Suède Charles XII, dit Demirbaş. La fermeture du front nord permit à l'Empire ottoman de tourner son attention vers la Morée et le front vénitien. Autre localité rattachée à la même date : Khotin.", "34010e06"]},
"OLAYLAR_EK5:1714-12-08:0":{"b": ["Déclaration de guerre à Venise : préparation de la campagne de Morée", "d970b122"], "d": ["Au motif que Venise soutenait les insurgés du Monténégro, saisissait des navires de commerce ottomans et accablait de lourds impôts la Morée qu'elle avait obtenue à Karlowitz, la décision de guerre fut prise au Divan. La campagne que prépara le grand vizir Silâhdar Damad Ali Pacha devait aboutir, l'année suivante, à la reprise de toute la péninsule de Morée en moins de cent jours. Mais ce succès devait mettre l'Autriche en mouvement et ouvrir en 1716 la porte à une guerre beaucoup plus lourde.", "ef2edb5f"]},
"OLAYLAR_EK5:1716-04-13:0":{"b": ["Alliance de l'Autriche et de Venise : ouverture de la guerre ottomano-autrichienne de 1716-1718", "99511ca2"], "d": ["Après la reprise de la Morée sur Venise par les Ottomans, l'Autriche, prétendant que le traité de Karlowitz avait été violé, signa un traité d'alliance avec Venise ; le prince Eugène, dans une lettre adressée au grand vizir, demanda la restitution des lieux pris à Venise. Lors de la consultation tenue au camp de Davutpaşa, la guerre fut déclarée à l'Autriche sous la pression du grand vizir Ali Pacha, et une fetva fut pour cela demandée au cheikh al-islam.", "4a2089d7"]},
"OLAYLAR_EK5:1716-04-24:0":{"b": ["Le grand vizir Ali Pacha part en campagne contre l'Autriche", "2fbdce42"], "d": ["La guerre ayant été déclarée à l'Autriche, le serdâr-i ekrem Ali Pacha partit en campagne contre l'Autriche avec une armée de plus de 100 000 hommes ; la flotte, elle, se dirigea le même été vers Corfou. L'armée devait marcher de Belgrade sur Varadin, et le grand vizir devait tomber en martyr dans la défaite du début d'août.", "02a5590b"]},
"OLAYLAR_EK5:1716-08-05:0":{"b": ["Défaite de Varadin (Petrovaradin) : martyre de Damad Ali Pacha", "265c1d81"], "d": ["L'armée ottomane, qui avait franchi le Danube par Belgrade, rencontra devant Varadin les forces autrichiennes placées sous le commandement du prince Eugène ; si, au premier élan, la charge des janissaires força les tranchées ennemies, les rangs se rompirent avec l'effondrement de l'aile de cavalerie. Le grand vizir Silâhdar Damad Ali Pacha, frappé au front, tomba en martyr, et le camp et le train d'artillerie tombèrent entièrement aux mains de l'ennemi. Cette défaite, que les chroniques ottomanes appellent « l'année de Varadin », fut le premier maillon de la chaîne qui mène à la perte de Timişoara et, l'année suivante, de Belgrade.", "ad21a2c3"]},
"OLAYLAR_EK5:1716-08-20:0":{"b": ["Échec du siège de Corfou", "b2aa7011"], "d": ["Le séraskier de Morée Kara Mustafa Pacha par terre et le kapudan pacha Canım Hoca Mehmed Pacha par mer attaquèrent Corfou, île qui était la base clé de Venise sur l'Adriatique. Mais les fortifications extrêmement puissantes de la forteresse, les renforts qu'amena la flotte vénitienne et la nouvelle de la défaite du front du Danube conduisirent à la levée du siège. L'impossibilité de prendre Corfou éteignit l'élan né de la reconquête de la Morée et déplaça le centre de gravité de la guerre vers la Hongrie.", "4589579c"]},
"OLAYLAR_EK5:1716-10-13:0":{"b": ["Perte de Timişoara (Temeşvar) au profit de l'Autriche", "27fe1365"], "d": ["Après la défaite de Varadin, le prince Eugène marcha directement sur Timişoara, et la forteresse fut remise par capitulation (vire) au terme d'un siège de plus de quarante jours. La ville, conquise en 1552 sous Soliman et qui était pendant cent soixante-quatre ans un centre de beylerbeylik et le pilier oriental de la défense de la Hongrie, échappa ainsi aux Ottomans. Avec la chute de Timişoara, tout le Banat passa à l'Autriche et la frontière ottomane fut repoussée au sud du Danube.", "3f3368fd"]},
"OLAYLAR_EK5:1716-11-16:0":{"b": ["Remise aux Autrichiens de la forteresse de Haram (Yeni Palanka) : la rive danubienne du Banat est perdue", "38ee4c6d"], "d": ["Après la chute de Timişoara, le général de cavalerie autrichien Mercy, chargé de prendre le reste du Banat, marcha le 14 novembre sur Haram (Yeni Palanka), sur la rive du Danube ; arrivé à la forteresse le 16 novembre, la garnison ottomane de 200 hommes se rendit en levant le drapeau blanc, à la condition de se retirer librement. Ainsi, la ligne du Danube du Banat méridional, aux mains des Ottomans depuis 1552, passa elle aussi à l'Autriche.", "8026e3e4"]},
"OLAYLAR_EK5:1723-06-15:0":{"b": ["Campagne d'Orient : prise de Tiflis et début de la guerre d'Iran", "78343dc2"], "d": ["L'État séfévide s'étant effondré sous l'invasion afghane et la Russie descendant sur les rives de la Caspienne, l'Empire ottoman envoya une armée vers l'est pour que le vide ne tombe pas entièrement à l'influence russe. Tiflis fut prise et la Géorgie rattachée à l'administration ottomane ; l'avance se poursuivit ensuite en direction de Gandja, d'Erevan et de Nakhitchevan. Menée derrière l'apparence pacifique de l'Ère des tulipes, cette campagne fut le début d'une longue aventure orientale qui devait durer treize ans et s'achever par la restitution de tout ce qui avait été gagné.", "5c412d91"]},
"OLAYLAR_EK5:1724-06-24:0":{"b": ["Traité de partage d'Istanbul : partage de l'Iran avec la Russie", "fce8eec2"], "d": ["Pour éviter que l'Empire ottoman et la Russie ne se retrouvent face à face sur le territoire séfévide en ruine, un traité de partage fut signé par la médiation de l'ambassadeur de France. Les rives occidentale et méridionale de la Caspienne furent laissées à la Russie, la Géorgie, le Chirvan, l'Azerbaïdjan et les villes de l'Iran occidental à l'Empire ottoman. Ce partage, qui semblait sur le papier un grand gain, devait être rendu de fait caduc peu après par l'essor de Nadir Chah.", "36a04f61"]},
"OLAYLAR_EK:1300-01-01:0":{"b": ["Prise de Köprühisar et préparation de la fondation de Yenişehir", "39abff03"], "d": ["Les forteresses de passage entre Bursa et Nicée furent réduites, et l'on posa les fondations d'un quartier général avancé destiné à encercler les deux villes.", "72fa9808"]},
"OLAYLAR_EK:1301-01-01:0":{"b": ["Fondation de Yenişehir", "d3275837"], "d": ["La première garnison-établissement ottomane régulière fut fondée pour diriger les sièges de Bursa et de Nicée ; Orhan Gazi y naquit.", "39c98a4b"]},
"OLAYLAR_EK:1302-08-01:0":{"b": ["Premier siège de Nicée et conquête de Marmaracık", "cdca2349"], "d": ["Nicée fut assiégée pour la première fois, mais ne put être réduite (la conquête définitive date de 1331) ; la forteresse voisine de Marmaracık fut prise à cette occasion.", "31c4c65f"]},
"OLAYLAR_EK:1305-06-01:0":{"b": ["Expédition des Catalans en Anatolie", "4fd940d5"], "d": ["La compagnie catalane engagée par Byzance pour arrêter la progression turque remporta des succès provisoires, mais ne put s'inscrire dans la durée ; avec son retrait, la progression des principautés marchesques s'accéléra.", "89381e71"]},
"OLAYLAR_EK:1313-01-01:0":{"b": ["Köse Mihal se convertit à l'islam et rejoint les Ottomans", "ca0d86e1"], "d": ["Köse Mihal, tekfur de Harmankaya, se convertit à l'islam et rejoignit Osman Gazi avec sa forteresse et ses hommes ; il devint le premier commandant ottoman d'origine byzantine.", "327b4cdc"]},
"OLAYLAR_EK:1320-01-01:0":{"b": ["Orhan Bey prend en main la conduite effective", "6dadbefc"], "d": ["En raison de la vieillesse et de la maladie d'Osman Gazi, la direction et la conduite effectives du siège de Bursa et des campagnes passèrent à son fils Orhan Bey (l'accession officielle au trône date de 1326).", "280c6e0d"]},
"OLAYLAR_EK:1321-01-01:0":{"b": ["Blocus du port de Mudanya", "9aa4520c"], "d": ["Le port qui ravitaillait Bursa par mer fut coupé, ce qui ouvrit le dernier acte du long siège.", "97d6f814"]},
"OLAYLAR_EK:1321-04-01:0":{"b": ["Prise de Mudanya", "0a623368"], "d": ["Mudanya, le port de Bursa, fut prise, ce qui coupa la ville de la mer ; le siège de Bursa entra dans sa phase d'étranglement.", "c13020d5"]},
"OLAYLAR_EK:1323-01-01:0":{"b": ["Rattachement de Yalova et de Karamürsel", "133cb07a"], "d": ["Les bourgs portuaires de la rive sud du golfe furent pris afin de compléter le siège de Bursa.", "6588050d"]},
"OLAYLAR_EK:1324-01-01:0":{"b": ["Conquête d'Akyazı et de l'île d'İmralı", "d041b0c8"], "d": ["Akyazı, au nord de la Sakarya, fut prise ; avec la saisie de l'île d'İmralı, les Ottomans devinrent pour la première fois voisins de l'île de Marmara.", "591424a4"]},
"OLAYLAR_EK:1324-03-01:0":{"b": ["Conquête de Gemlik (Kios) et d'Armutlu", "682d3bac"], "d": ["La dernière liaison maritime de Bursa fut elle aussi coupée, ce qui prépara la ville à la reddition de 1326.", "c2b80b4a"]},
"OLAYLAR_EK:1326-01-01:0":{"b": ["Akça Koca s'empare de Kandıra et de ses environs", "341bb97e"], "d": ["Akça Koca, l'un des beys marchesques d'Orhan Gazi, tandis qu'il menait des raids vers la région d'İzmit depuis son quartier général à l'ouest du lac de Sapanca, s'empara vers 1326 de Kandıra et de ses environs. İzmit était encore aux mains des Byzantins ; la ville ne devait tomber qu'en 1337.", "ed042ad1"]},
"OLAYLAR_EK:1328-01-01:0":{"b": ["Akça Koca prend Aydos et la forteresse de Samandıra", "ce4daa8a"], "d": ["Après la prise de Kandıra, Akça Koca, avec Konuralp et Gazi Abdurrahman, prit la forteresse d'Aydos, près de Kartal, puis la forteresse de Samandıra, au nord ; la région de Samandıra lui fut donnée en propriété (mülk). Akça Koca mourut en 1328 près de Kandıra ; le beylik marchesque de la région fut donné au prince Murad.", "f2ef1bde"]},
"OLAYLAR_EK:1330-01-01:0":{"b": ["Alliance ottomano-aydınide-saruhanide", "9df6bb74"], "d": ["Les trois principautés agirent de concert contre Byzance ; la flotte du bey aydınide Umur Bey épuisa Byzance sur un second front par ses raids contre les côtes de Thrace.", "32ca49ea"]},
"OLAYLAR_EK:1346-06-01:0":{"b": ["Mariage d'Orhan Gazi et de Théodora : alliance byzantine", "9b67a590"], "d": ["Orhan Gazi, qui avait soutenu Cantacuzène dans la lutte pour le trône byzantin, épousa sa fille Théodora ; cette alliance permit aux forces ottomanes de bien connaître la Roumélie.", "4f8f52d9"]},
"OLAYLAR_EK:1354-08-01:0":{"b": ["Prise d'Ankara", "49bf1f6d"], "d": ["Ankara, alors sous administration ahie, passa sous l'administration ottomane ; la route d'Anatolie centrale fut ouverte. Autres lieux rattachés à la même date : Sivrihisar, Çankırı.", "eec5d13e"]},
"OLAYLAR_EK:1357-01-01:0":{"b": ["Progression en Thrace sous Süleyman Pacha : Malkara, İpsala et Tekirdağ", "fb31cf02"], "d": ["Une fois la tête de pont établie à Gallipoli, Süleyman Pacha monta de la péninsule vers le nord et s'empara pas à pas de la plaine comprise entre la côte de la Marmara et l'embouchure de la Maritsa. Malkara, İpsala et Rodosçuk (Tekirdağ) formèrent ainsi un couloir continu reliant Gallipoli à la vallée de la Maritsa. Sans l'établissement de ce couloir, on ne pouvait marcher sur Andrinople ; la progression, arrêtée par la mort soudaine du prince en 1357, devait être poursuivie par Lala Şahin et Hacı İlbey.", "721cac95"]},
"OLAYLAR_EK:1357-08-01:0":{"b": ["Enlèvement du prince Halil", "b52ac3d7"], "d": ["Halil, le jeune fils d'Orhan Gazi, fut enlevé par des corsaires de Phocée ; la crise de la rançon occupa pendant des années les relations ottomano-byzantines.", "812e3cb6"]},
"OLAYLAR_EK:1360-01-01:0":{"b": ["Coupure des voies de secours d'Andrinople : forteresses de Çorlu, de Lüleburgaz, de Babaeski et de Keşan", "8e8ad485"], "d": ["Le prince Murad, qui reprit les opérations de conquête après la libération de Halil, envoya des akıncı jusque devant Constantinople afin d'isoler Andrinople (Edirne) de tout secours extérieur. Les forteresses de Çorlu, de Lüleburgaz et de Babaeski, sur la route Constantinople–Andrinople, ainsi que Keşan, au carrefour routier de la Thrace méridionale, furent prises. La reddition d'Andrinople ne vint qu'une fois ce cercle de siège achevé.", "fb171002"]},
"OLAYLAR_EK:1361-01-01:0":{"b": ["Prise de Didymotique (Dimetoka) — ouverture de la vallée de la Maritsa", "b59aee83"], "d": ["Dimetoka, forteresse clé de la vallée de la Maritsa, fut prise ; la voie menant à la conquête d'Andrinople s'ouvrait ainsi. Il était impossible de marcher sur Andrinople sans que fût achevé le couloir s'étendant de Gallipoli vers le nord ; c'est pourquoi cette forteresse précède Andrinople dans l'ordre des conquêtes de Roumélie. La ville devint pour un temps le quartier général des sultans en Roumélie. Les forces qui prirent Dimetoka placèrent ensuite sous leur contrôle toute la région de la Maritsa moyenne, avec de petites forteresses telles que Kuleli Burgaz (Pythion).", "88f995b6"]},
"OLAYLAR_EK:1366-08-01:0":{"b": ["Perte de Gallipoli (croisade de Savoie)", "00e7e415"], "d": ["La flotte d'Amédée de Savoie, cousin de l'empereur byzantin, prit Gallipoli et la remit à Byzance ; la tête de pont ottomane en Roumélie fut dirigée pendant dix ans depuis l'autre rive du détroit. Autres établissements perdus à la même date : Çimpe.", "b0c24ccd"]},
"OLAYLAR_EK:1371-09-26:0":{"b": ["Bataille de la Maritsa (Çirmen) — contrôle de la vallée de la Maritsa", "cd738d8d"], "d": ["L'armée des seigneurs serbes fut dispersée lors d'une attaque nocturne ; les seigneurs locaux serbes et bulgares de Macédoine et des Rhodopes commencèrent un à un à payer tribut aux Ottomans — non une conquête directe, mais le début d'une vague de vassalisation. Dans la tradition ottomane, cette bataille est en outre racontée sous le nom de « Sırpsındığı » et à l'année 1364, comme l'attaque nocturne de Hacı İlbey contre l'armée croisée venue reprendre Andrinople ; le TDV signale que cette date est fausse et que les deux récits se rapportent à la même bataille.", "7b2779cd"]},
"OLAYLAR_EK:1372-06-01:0":{"b": ["Conquête de Plovdiv (Filibe) et de Stara Zagora (Eski Zağra)", "e780c9ae"], "d": ["Plovdiv (Filibe), en amont de la vallée de la Maritsa, et Stara Zagora (Eski Zağra), au nord, furent prises ; le tsarat bulgare fut placé sous tribut. L'itinéraire de Tatarpazarcığı et d'İhtiman, entre Plovdiv et Sofia, resta aux mains des seigneurs locaux devenus vassaux après Çirmen.", "b8131db8"]},
"OLAYLAR_EK:1373-05-01:0":{"b": ["Byzance vassale : Jean V dans l'armée de Murad Ier (conséquence de la victoire de la Maritsa de 1371)", "13ffe568"], "d": ["Selon le TDV, après la victoire de la Maritsa (Çirmen) du 26 septembre 1371, l'Empire byzantin avait reconnu la domination ottomane et était tombé dans la situation d'État vassal, ayant accepté de payer un tribut et de servir dans l'armée ottomane. L'empereur Jean V, en vertu de cette obligation, rejoignit en 1373 l'armée de Murad Ier ; son fils Andronic IV, qu'il avait laissé à Constantinople, se révolta contre son père avec le prince Savcı Bey, qui se trouvait à Bursa.", "3fe5b636"]},
"OLAYLAR_EK:1376-09-01:0":{"b": ["Reprise de Gallipoli", "5f96c0a5"], "d": ["Andronic IV, qui avait obtenu l'appui ottoman dans la querelle byzantine pour le trône, restitua Gallipoli en contrepartie ; le pont entre la Roumélie et l'Anatolie fut rétabli. Autres lieux rattachés à la même date : Çimpe.", "fc79cd5d"]},
"OLAYLAR_EK:1381-01-01:0":{"b": ["La dot de Germiyan : rattachement de Kütahya", "d6a6fe61"], "d": ["Lors du mariage de Devletşah Hatun, fille du Germiyanoğlu Süleyman Şah, avec Bayezid le Foudre, Kütahya, Simav, Tavşanlı et Eğrigöz passèrent à l'Empire ottoman à titre de dot — exemple classique d'expansion sans guerre. Autres lieux rattachés à la même date : Afyon.", "3321bbba"]},
"OLAYLAR_EK:1381-06-01:0":{"b": ["Achat du pays de Hamîd : rattachement d'Isparta", "4a1b6047"], "d": ["Le bey hamîdide Hüseyin Bey vendit à Murad Ier, contre argent comptant, une partie de sa principauté (Akşehir-Beyşehir-Isparta) ; le reste du pays de Hamîd devait être annexé en 1391 par le Foudre.", "d316dea5"]},
"OLAYLAR_EK:1383-09-19:0":{"b": ["Conquête de Serrès", "d4d28b60"], "d": ["Serrès, clé de la Macédoine orientale, fut prise ; Thessalonique entra dans le cercle du siège. La ligne Köstendil–Petriç–Nevrokop–Drama, entre Sofia et Serrès, n'était pas encore directement rattachée à cette date : elle passa, par étapes, au statut de vassale entre les années 1370 et 1383, puis à l'administration directe après 1383.", "573cc19c"]},
"OLAYLAR_EK:1385-09-01:0":{"b": ["Conquête de Sofia", "96d5f01f"], "d": ["Les passes occidentales des Balkans furent placées sous contrôle ; à cette date, Serrès étant déjà tenue depuis 1383, les terres de Thrace et de Macédoine formaient un ensemble ininterrompu.", "f358b568"]},
"OLAYLAR_EK:1386-01-01:0":{"b": ["Conquête de Niš", "77f5d632"], "d": ["Avec la prise de Niš, clé de la vallée de la Morava, le despotat serbe fut directement menacé.", "15f52aaf"]},
"OLAYLAR_EK:1387-04-09:0":{"b": ["Première reddition de Thessalonique", "96010ee9"], "d": ["Après un long blocus, la ville se rendit (elle devait être rendue à Byzance en 1403 et définitivement conquise en 1430). Autres lieux rattachés à la même date : Kavala.", "5ef8bffd"]},
"OLAYLAR_EK:1387-06-08:0":{"b": ["Ahidname ottomano-génois — renouvellement du traité de 1352", "be11d17a"], "d": ["Avec les ambassadeurs génois venus de Péra, le traité commercial de 1352, hérité de l'époque d'Orhan Gazi, fut renouvelé ; les taxes entre les deux États, le traitement des prisonniers et la liberté du commerce furent de nouveau fixés. C'est considéré comme le premier ahidname d'amitié et de commerce officiellement connu entre les Ottomans et les Génois — non une alliance militaire, mais un accord purement commercial.", "46b0f65b"]},
"OLAYLAR_EK:1388-01-01:0":{"b": ["Campagne de Bulgarie de Çandarlı Ali Pacha : prise de Şumnu et de Rusçuk", "2781c3a9"], "d": ["Les forteresses du tsarat de Bulgarie situées le long du Danube furent reçues en reddition lors d'une seule campagne ; il ne faut pas la confondre avec la défaite subie la même année à Bileća, en Bosnie — ce fut un succès simultané sur un front distinct. Tărnovo et Vidin étaient les derniers centres bulgares encore tenus.", "d6eaf4cd"]},
"OLAYLAR_EK:1388-08-27:0":{"b": ["Défaite de Bileća", "89ba0a64"], "d": ["La force d'akıncı qui s'avançait vers la Bosnie fut prise en embuscade à Bileća et anéantie ; ce premier grand revers balkanique encouragea la coalition qui menait à Kosovo.", "9960a7a5"]},
"OLAYLAR_EK:1390-01-01:0":{"b": ["Annexion des principautés d'Anatolie occidentale : Saruhan, Aydın, Menteşe", "dcc33b71"], "d": ["Les trois principautés furent rattachées en une seule fois : Manisa, centre des Saruhanoğulları ; Aydın, centre des Aydınoğulları (y compris la haute forteresse d'Izmir, mais le port et la ville basse restaient aux chevaliers de Saint-Jean — jusqu'en 1402) ; Muğla-Milas, centre des Menteşeoğulları, y compris la bande côtière Datça-Bodrum-Marmaris-Fethiye. Les côtes de l'Égée étaient pour la première fois réunies en une seule main. Autres lieux rattachés à la même date : Söke.", "7f3094f2"]},
"OLAYLAR_EK:1391-10-01:0":{"b": ["Début du premier blocus de Constantinople", "4441a9e7"], "d": ["Bayezid le Foudre tint Constantinople en état de blocus par intermittence pendant dix ans ; la ville ne fut sauvée que par l'approche de Tamerlan.", "504fcb33"]},
"OLAYLAR_EK:1392-01-01:0":{"b": ["Annexion du pays de Teke : rattachement d'Antalya", "fdbeee5c"], "d": ["Le pays de Teke, sur la côte méditerranéenne, fut rattaché aux terres ottomanes. Les Tekeoğulları sont une branche détachée des Hamîdoğulları : Feleküddin Dündar Bey avait laissé Antalya, qu'il avait conquise, à son frère Yûnus Bey, et une principauté distincte était née vers 1321. C'est pourquoi Antalya et ses environs figurent sur la carte, après 1321, à la couleur des Tekeoğulları et non des Hamîdoğulları. La principauté fut rétablie après la bataille d'Ankara et ne fut définitivement liquidée qu'en 1423.", "09a83d97"]},
"OLAYLAR_EK:1392-01-06:0":{"b": ["Conquête de Skopje", "9e5a1af5"], "d": ["Le centre de la Macédoine du Vardar fut pris ; Skopje devint l'un des principaux centres marchesques de la Roumélie.", "8722b1dd"]},
"OLAYLAR_EK:1392-11-01:0":{"b": ["Annexion de Kastamonu", "876330ba"], "d": ["La branche de Kastamonu des Candaroğulları fut liquidée ; la branche de Sinope subsista comme vassale. Autres lieux rattachés à la même date : Bartın, Safranbolu.", "34d8e600"]},
"OLAYLAR_EK:1393-06-17:0":{"b": ["Chute de Tărnovo — annexion de la Bulgarie", "ff666977"], "d": ["La capitale du tsarat bulgare tomba ; la Bulgarie passa sous administration ottomane directe. Autres lieux rattachés à la même date : Plevne, Lovech (Lofça).", "182028e2"]},
"OLAYLAR_EK:1393-06-17:1":{"b": ["La forteresse de Lovech (Lofça) passe aux Ottomans", "a55e87a0"], "d": ["Lovech (Lofça), l'une des forteresses du tsar bulgare Ivan Chichman, fut rattachée aux terres ottomanes avec les autres provinces de Chichman lors de la campagne de 1393 où tomba Tărnovo. La source ne se prononce pas de manière certaine : on « pense » que la conquête eut lieu cette année-là.", "9430a123"]},
"OLAYLAR_EK:1393-09-01:0":{"b": ["Rattachement de la Dobroudja", "478e36f2"], "d": ["Les terres de la Dobroudja, qui s'étendent jusqu'au delta du Danube, furent rattachées. Autres lieux rattachés à la même date : Silistra, Constanța (Köstence).", "05bdabb4"]},
"OLAYLAR_EK:1394-01-01:0":{"b": ["Descente en Thessalie", "8bec60dd"], "d": ["La plaine de Thessalie, centrée sur Yenişehir (Larissa), fut placée sous administration ottomane. Autres lieux rattachés à la même date : Trikala (Tırhala), Izdin (Lamia).", "d9f2128c"]},
"OLAYLAR_EK:1395-01-01:0":{"b": ["Conquête de Nicopolis", "b9791717"], "d": ["Après la bataille de Rovine de 1395 contre les Valaques, Bayezid le Foudre prit la forteresse de Nicopolis, sur le Danube ; certaines chroniques bulgares anonymes indiquent que la conquête eut lieu le 3 juin 1395. La date de la conquête n'est pas unique dans les sources : l'article « Niğbolu Savaşı » du TDV İslâm Ansiklopedisi écrit que Bayezid s'empara de Silistra et de Nicopolis lors d'une campagne du Danube en 1394. La forteresse devait être assiégée lors de la célèbre croisade de 1396, sans tomber. Autres lieux rattachés à la même date : Ohrid.", "bc450a9f"]},
"OLAYLAR_EK:1395-05-17:0":{"b": ["Bataille de Rovine — campagne de Valachie", "343ae7a9"], "d": ["À la suite d'une bataille sanglante et à l'issue discutée contre le voïvode de Valachie Mircea, la Valachie accepta de payer tribut aux Ottomans ; l'ordre de vassalité au nord du Danube fut établi.", "dd69200f"]},
"OLAYLAR_EK:1395-08-01:0":{"b": ["Construction d'Anadolu Hisarı", "aa259b00"], "d": ["Pour soutenir le blocus de Constantinople, Güzelcehisar (Anadolu Hisarı) fut édifié sur la rive anatolienne du Bosphore — première étape durable du contrôle du détroit.", "a1b2f889"]},
"OLAYLAR_EK:1396-10-01:0":{"b": ["Annexion de Vidin", "ee1ae44b"], "d": ["Après la victoire de Nicopolis, Vidin, dernière principauté bulgare, fut elle aussi annexée.", "28f4258d"]},
"OLAYLAR_EK:1397-07-01:0":{"b": ["Première annexion du Karaman", "3cf07876"], "d": ["Par la victoire d'Akçay, les terres des Karamanoğulları furent pour la première fois rattachées à l'Empire ottoman (elles seraient rétablies pendant l'Interrègne).", "788bdca3"]},
"OLAYLAR_EK:1398-07-01:0":{"b": ["Rattachement des côtes de Canik : Samsun", "af9c40fa"], "d": ["Dans le vide créé par la captivité de Kadı Burhâneddin aux mains de l'Aqqoyunlu Karayülük Osman Bey, Bayezid le Foudre plaça d'abord sous administration ottomane la région de Canik, sur la côte de la mer Noire. Samsun et ses environs devinrent ainsi le premier port de la dynastie sur la mer Noire. La ligne intérieure Sivas-Tokat-Kayseri devait être rattachée deux semaines plus tard, avec la dissolution de fait de l'État de Kadı Burhâneddin.", "4b2f9a80"]},
"OLAYLAR_EK:1399-09-01:0":{"b": ["Prise de Malatya", "7cb6ae16"], "d": ["Malatya, sur la frontière mamelouke, fut prise — l'une des démarches qui accrurent la tension avec Tamerlan.", "3b7ba002"]},
"OLAYLAR_EK:1400-01-01:0":{"b": ["Tamerlan prend Malatya et la laisse à Karayülük Osman — au départ de Tamerlan, les Dulkadirides la reprennent", "ad2ce7d8"], "d": ["Bayezid le Foudre avait laissé Malatya, prise en 1399, au Dulkadiroğlu Nasreddin Mehmed et était retourné à Bursa. Tamerlan, qui entra en Anatolie en 1400, prit d'abord Sivas et Elbistan, puis Malatya ; la ville et ses environs furent pillés, et son administration fut confiée à Karayülük Osman, qui se trouvait auprès de Tamerlan. Quand Tamerlan quitta la région, les Dulkadirides dominèrent de nouveau Malatya ; la domination ottomane y prit ainsi fin avant Ankara.", "5889cce9"]},
"OLAYLAR_EK:1403-06-01:0":{"b": ["Traité de Süleyman Çelebi avec Byzance : restitution de Thessalonique", "cc503cc2"], "d": ["Süleyman Çelebi, qui dominait la Roumélie pendant l'Interrègne, s'entendit avec Byzance et les États latins et leur abandonna Thessalonique ainsi que les rivages de la mer Noire jusqu'à Misivri (Mésembrie) (TDV « fetret-devri » : traité de Gallipoli, février 1403) — sur la carte, İğneada, Rezve et Ahtapolu passent à Byzance ; sur la carte, Thessalonique sort de l'Empire ottoman à cette date.", "ac791637"]},
"OLAYLAR_EK:1416-05-29:0":{"b": ["Défaite navale de Gallipoli (Venise)", "b71d4d68"], "d": ["La flotte vénitienne infligea une lourde défaite à la flotte ottomane devant Gallipoli ; l'événement montra les limites de la marine ottomane des origines.", "7166c255"]},
"OLAYLAR_EK:1421-08-15:0":{"b": ["Soulèvement du faux Mustafa (Düzmece Mustafa)", "0ec43138"], "d": ["Mustafa Çelebi, qui se prétendait fils du Foudre, se proclama sultan en Roumélie avec l'appui de Byzance ; Murad II réprima le soulèvement en 1422 et fit exécuter son rival.", "9bae8d0d"]},
"OLAYLAR_EK:1422-06-10:0":{"b": ["Siège de Constantinople par Murad II", "4b9d9fba"], "d": ["En réponse au soutien de Byzance au faux Mustafa, Murad II assiégea Constantinople ; le siège fut levé lorsque son frère, le petit Mustafa, fut soulevé en Anatolie.", "bc254acf"]},
"OLAYLAR_EK:1423-09-14:0":{"b": ["Cession de Thessalonique à Venise", "bfa6c4a0"], "d": ["Le gouverneur byzantin, sous la pression ottomane, céda la ville à Venise ; la rivalité ottomano-vénitienne, qui devait durer sept ans, commença.", "da60fe5f"]},
"OLAYLAR_EK:1425-06-01:0":{"b": ["Nouvelle annexion des principautés d'Anatolie occidentale : Menteşe et Aydın", "aca30a48"], "d": ["Les deux principautés de l'Égée, rétablies pendant l'Interrègne, furent définitivement rattachées aux terres ottomanes sous Murad II. Selon l'article « Menteşeoğulları » du TDV, Murad II s'empara du pays de Menteşe en 827 (1424) et fit emprisonner les deux frères à la tête de la principauté. Selon l'article « Aydınoğulları », le beylerbey d'Anatolie Hamza Bey fit capturer Cüneyd Bey, de nouveau sorti de l'obéissance, et le fit exécuter avec sa famille (829/1425-26), et le pays d'Aydın passa aux Ottomans. Les chevaliers de Saint-Jean, qui tenaient la forteresse portuaire d'Izmir depuis 1344, l'avaient perdue en 1402 au profit de Tamerlan, et la région était revenue sous le contrôle des Aydınoğulları ; par cette annexion, elle fut aussi rattachée à l'Empire ottoman. Le pays de Teke (Antalya) n'est pas l'objet de cet article : les Tekeoğulları avaient été liquidés séparément en 1423. Quant à Germiyan, il devait être rattaché en 1429 par testament.", "92fa8d97"]},
"OLAYLAR_EK:1429-01-01:0":{"b": ["Annexion de Germiyan par testament", "9eb86b77"], "d": ["Yakub II, bey de Germiyan, mort sans enfant, légua son pays aux Ottomans — exemple d'annexion sans guerre entré dans les manuels. Autres lieux rattachés à la même date : Karahisâr-ı Sâhib (Afyon).", "9173c7b2"]},
"OLAYLAR_EK:1430-03-29:0":{"b": ["Conquête définitive de Thessalonique", "bc021768"], "d": ["La ville, sous administration vénitienne, fut prise d'assaut ; le deuxième grand port de la Roumélie devint définitivement ottoman. Autres lieux rattachés à la même date : Kassandra (Kesendire).", "8853e257"]},
"OLAYLAR_EK:1430-10-09:0":{"b": ["Reddition de Ioannina", "ee45cb52"], "d": ["Ioannina (Yanya), centre de l'Épire, se rendit par traité.", "1aad46c0"]},
"OLAYLAR_EK:1439-08-27:0":{"b": ["Première prise de Smederevo", "c11ca17d"], "d": ["La capitale du despotat serbe fut prise après un siège de trois mois et la Serbie fut annexée pour la première fois (elle devait être restituée par le traité d'Edirne-Szeged de 1444).", "3dc4dfe5"]},
"OLAYLAR_EK:1440-04-01:0":{"b": ["Siège de Belgrade (infructueux)", "3e05f425"], "d": ["Le premier grand siège de Belgrade, qui dura six mois, resta sans résultat ; la forteresse demeura pendant quatre-vingts ans un verrou devant la progression ottomane.", "2a88be8a"]},
"OLAYLAR_EK:1443-11-24:0":{"b": ["Déroute de Zlatica (İzladi) — la « Longue Campagne »", "97df1466"], "d": ["L'armée que Hunyadi fit entrer dans les Balkans au cœur de l'hiver dépassa Niš et Sofia et atteignit Zlatica (İzladi) ; la défense ottomane tint avec peine. Ce climat de déroute amena sur la table la paix d'Edirne-Szeged.", "cf103982"]},
"OLAYLAR_EK:1444-06-12:0":{"b": ["Traité d'Edirne-Szeged", "0aa4e0de"], "d": ["Paix de dix ans : le despotat serbe fut restitué, le Danube fut reconnu comme frontière. La rupture du traité en quelques mois, sous l'incitation de la papauté, conduisit au désastre de Varna.", "46b3ced6"]},
"OLAYLAR_EK:1444-08-15:0":{"b": ["Restitution de Smederevo et des forteresses serbes à la Serbie", "cda3cf9e"], "d": ["La disposition du traité d'Edirne-Szeged fut mise en application : Murad II rendit, le 15 août 1444, Smederevo avec ses vingt-quatre forteresses importantes et les autres terres serbes occupées à Đurađ Branković (TDV « semendire ») ; Niš (TDV « nis »), Alacahisar (TDV « alacahisar »), Şehirköy (TDV « sehirkoy ») et Priština (TDV « pristine ») furent aussi laissées aux Serbes. Vidin n'étant pas terre serbe, elle n'entra pas dans la restitution — c'est la source de la perte territoriale du nord-ouest visible sur la carte vers l'époque de la victoire de Varna ; quelques mois plus tard, avec la déroute de Varna, le traité devait de toute façon devenir caduc.", "19c68a1f"]},
"OLAYLAR_EK:1452-08-31:0":{"b": ["Achèvement de Rumeli Hisarı — « Boğazkesen »", "480e8a76"], "d": ["Selon les sources, la forteresse fut achevée par une construction extraordinairement rapide, de quatre à cinq mois ; avec elle, le contrôle du Bosphore passa entièrement aux Ottomans, et la voie de secours de la mer Noire vers Constantinople fut fermée. Elle est tenue pour la première étape effective du siège.", "1d84cd36"]},
"OLAYLAR_EK:1453-04-06:0":{"b": ["Début du siège de Constantinople", "8af50742"], "d": ["L'armée s'installa devant les murailles ; dans le siège de 54 jours qui allait suivre, des canons gigantesques furent pour la première fois utilisés de manière systématique contre les murs d'une capitale.", "6d71da31"]},
"OLAYLAR_EK:1453-04-22:0":{"b": ["Les navires descendus par voie terrestre dans la Corne d'Or", "4f2ba07c"], "d": ["Environ 70 navires de la flotte, qui ne pouvait entrer dans la Corne d'Or fermée par une chaîne, furent halés par-dessus les hauteurs de Galata sur des glissières graissées et mis à l'eau dans la Corne d'Or en une seule nuit ; la défense fut divisée en deux fronts.", "2eb65d41"]},
"OLAYLAR_EK:1456-06-04:0":{"b": ["Conquête d'Athènes", "4f0f1bb2"], "d": ["Le duché d'Athènes prit fin ; l'étendard ottoman fut hissé sur l'Acropole. Autres lieux rattachés à la même date : Thèbes (İstefe), Livadia.", "a912625d"]},
"OLAYLAR_EK:1459-06-20:0":{"b": ["Annexion de la Serbie (chute de Smederevo)", "75fd0a62"], "d": ["Smederevo (Semendire), capitale du despotat serbe, se rendit ; la Serbie devint un sandjak ottoman.", "29bd2888"]},
"OLAYLAR_EK:1460-05-29:0":{"b": ["Conquête de la Morée", "7d5a3c18"], "d": ["Le despotat de Morée fut liquidé ; la péninsule (à l'exception des forteresses vénitiennes) passa sous administration ottomane.", "14aba74c"]},
"OLAYLAR_EK:1461-06-01:0":{"b": ["Rattachement de Sinope", "e03c2739"], "d": ["Le Candaroğlu remit Sinope sans combat ; la voie de la campagne de Trébizonde était ouverte. Autres lieux rattachés à la même date : Kastamonu, Bartın, Safranbolu.", "4fa22834"]},
"OLAYLAR_EK:1463-06-01:0":{"b": ["Chute du royaume de Bosnie — campagne de Bosnie de Mehmed le Conquérant", "5362e3f2"], "d": ["Le dernier roi de Bosnie, Stjepan Tomašević (1461-1463), ayant refusé de payer le tribut en comptant sur l'appui de l'Occident, fut tenu pour avoir cessé d'être un souverain vassal, et l'armée placée sous le commandement du sultan Mehmed le Conquérant liquida le royaume de Bosnie en une seule campagne. Le roi fut capturé et exécuté, le royaume disparut et le sandjak de Bosnie fut créé dans la région. Mais la chute du royaume n'est pas la même chose que la conquête de la Bosnie. L'administration ottomane était déjà présente dans la plaine depuis quinze ans — Hodidjed et la plaine de Sarajevo avaient été prises en 1448, et la marche d'Îsâ Bey avait été établie au milieu du royaume. La conquête ne s'acheva pas non plus en 1463 : Foča fut prise en 1465, Livno en 1469, le duché d'Herzégovine en 1483, le banat de Srebrenik en 1512, et le nord, Jajce et Banja Luka, ne purent l'être qu'après Mohács, en 1528 — les Hongrois avaient établi après 1463 un banat qui se maintint soixante-cinq ans au nord de la Bosnie. Le lieu qui changea directement de mains à cette date est Travnik ; quant à Jajce, elle passa à cette date non aux Ottomans, mais à la Hongrie.", "5ac16344"]},
"OLAYLAR_EK:1468-01-01:0":{"b": ["Annexion définitive du Karaman", "f1dcecaa"], "d": ["Les terres centrales des Karamanoğulları furent définitivement rattachées ; les querelles intestines se prolongèrent jusque dans les années 1470. Autres lieux rattachés à la même date : Niğde, Mostar, Beyşehir.", "da6cfd4c"]},
"OLAYLAR_EK:1470-07-12:0":{"b": ["Conquête de Négrepont (Eğriboz)", "5c97daf3"], "d": ["Négrepont, principale base de Venise dans l'Égée, tomba.", "189cc474"]},
"OLAYLAR_EK:1471-01-01:0":{"b": ["Annexion d'Alanya, d'Anamur et de Silifke (İçel)", "a0b9d461"], "d": ["La bande côtière de l'İçel, dépendante des Karamanoğulları (toute la Méditerranée entre Antalya et Mersin), fut rattachée par la campagne navale de Gedik Ahmed Pacha ; Alanya était importante par son arsenal stratégique datant de l'époque seldjoukide.", "8302df58"]},
"OLAYLAR_EK:1479-01-25:0":{"b": ["Traité d'Istanbul — Albanie et Scutari", "b09652f7"], "d": ["La guerre ottomano-vénitienne de 16 ans prit fin ; Scutari (İşkodra) et les côtes albanaises restèrent aux Ottomans. Autres lieux rattachés à la même date : Lemnos, Samos, Bozbaba (Aghios Efstratios).", "bc2aebf2"]},
"OLAYLAR_EK:1480-08-11:0":{"b": ["Débarquement d'Otrante", "7916b89d"], "d": ["Les forces ottomanes débarquées sur la côte de Calabre assiégèrent et prirent la forteresse d'Otrante ; la ville ayant été enlevée de vive force, une partie des notables qui avaient résisté furent exécutés et une autre partie fut faite prisonnière. La tradition de l'Église commémore les morts comme les « martyrs d'Otrante », au nombre d'environ 800 ; le TDV attribue l'exagération de ce chiffre à la propagande de l'Église. Seuls la forteresse, à l'extrémité de la péninsule du Salento, et ses abords immédiats furent tenus ; les autres terres du royaume de Naples sur la ligne Tarente-Brindisi-Lecce ne furent pas perdues — cette tête de pont ouverte sur l'Italie devait durer un an.", "f60d286a"]},
"OLAYLAR_EK:1481-09-10:0":{"b": ["Évacuation d'Otrante", "37371bb0"], "d": ["À la mort de Mehmed le Conquérant (3 mai 1481), la garnison d'Otrante, qui n'avait plus d'espoir de renfort, évacua la forteresse par accord devant le siège du prince héritier de Naples, Alphonse ; l'unique tête de pont ottomane en Italie fut ainsi perdue un an plus tard.", "961ef9c3"]},
"OLAYLAR_EK:1500-08-09:0":{"b": ["Conquête de Modon et de Coron", "38b608c4"], "d": ["Modon et Coron, les « deux yeux » de Venise en Morée, furent prises.", "a11c09d0"]},
"OLAYLAR_EK:1501-08-17:0":{"b": ["Conquête de Durrës", "1f231b98"], "d": ["Pendant la guerre ottomano-vénitienne de 1499-1503, les forces placées sous le commandement de Mehmed Bey prirent Durrës (Draç), dernier grand port albanais de Venise sur l'Adriatique. Après Scutari (1479) et Valona (1417), cette conquête fit passer toute la bande côtière albanaise sous contrôle ottoman.", "ad635bca"]},
"OLAYLAR_EK:1515-09-15:0":{"b": ["Rattachement de l'Anatolie orientale", "e0cb8f8f"], "d": ["Après Çaldıran, Diyarbakır et ses environs furent rattachés ; les principautés kurdes furent liées aux Ottomans par l'entremise d'İdrîs-i Bitlisî.", "025d3ddc"]},
"OLAYLAR_EK:1526-07-27:0":{"b": ["Conquête de la forteresse de Petrovaradin (Varadin)", "abf392a5"], "d": ["L'armée partie pour la campagne de Mohács passa de Belgrade en terre hongroise ; les faubourgs de Petrovaradin (Varadin) furent d'abord pris, puis la forteresse tomba après un siège de quatorze jours. Soliman ordonna de ne pas brûler les villages sur la route, car ils étaient désormais considérés comme terre ottomane.", "60a4ae4e"]},
"OLAYLAR_EK:1526-09-01:0":{"b": ["Reddition de Bude après Mohács — deux rois pour le trône de Hongrie", "9d3568a0"], "d": ["Les clés de la ville furent présentées au sultan le 11 septembre 1526, devant l'armée ottomane qui marchait sur Bude après la victoire de Mohács ; mais Soliman ne conserva pas Bude et retira son armée. Dans la Hongrie sans roi, les nobles élurent deux rois distincts : János Szapolyai le 10 novembre 1526, le Habsbourg Ferdinand Ier le 17 décembre 1526. Ferdinand prit Bude en août 1527. L'installation de Szapolyai à Bude comme roi sous protection ottomane devait avoir lieu lors de la campagne de 1529 (voir l'entrée de 1529), et l'administration ottomane directe être établie en 1541.", "d68817d3"]},
"OLAYLAR_EK:1526-11-10:0":{"b": ["János Szapolyai élu roi de Hongrie — l'Empire ottoman reconnaît son royaume à condition qu'il lui soit vassal", "32bc6baf"], "d": ["Au trône de Hongrie, laissé vacant par la mort du roi à Mohács, une partie de la noblesse élut le voïvode de Transylvanie János Szapolyai ; Szapolyai fut couronné à Székesfehérvár (İstolni Belgrad). Les Ottomans, qui avaient évacué Bude, reconnurent le royaume de Szapolyai à condition qu'il leur fût vassal, afin de maintenir la région en zone tampon. Sur la carte, les lieux dépendant de Szapolyai figurent à partir de cette date comme vassaux de l'Empire ottoman.", "1d697cbd"]},
"OLAYLAR_EK:1526-12-17:0":{"b": ["Ferdinand Ier proclamé roi de Hongrie — l'ouest et le nord de la Hongrie à la couronne des Habsbourg", "b3910a2f"], "d": ["L'archiduc Ferdinand de Habsbourg revendiqua le trône de Hongrie en vertu du mariage de sa sœur avec Louis II (Lajos) et fut proclamé roi par une partie de la noblesse. La Hongrie fut ainsi partagée entre deux rois ; ses parties occidentale et septentrionale reconnurent Ferdinand. Les nobles croates l'élurent à part au début de 1527.", "1484af4c"]},
"OLAYLAR_EK:1530-01-01:0":{"b": ["Querelle des deux rois : Esztergom sous protection des Habsbourg, Szeged à Szapolyai", "da92dee5"], "d": ["Esztergom (Estergon), qui changeait de mains entre les deux rois depuis 1526, passa sous la protection des Habsbourg après que l'archevêque fut parti vers le nord avec ses archives et son trésor. Szeged (Segedin) resta sous la souveraineté de Szapolyai de cette année jusqu'en 1541.", "4317e319"]},
"OLAYLAR_EK:1532-01-01:0":{"b": ["La population de Pécs passe du côté de Szapolyai", "3fc4e7f2"], "d": ["Pécs (Peçuy), qui avait obtenu un privilège de Ferdinand en 1528, passa peu après du côté de Szapolyai ; le roi János séjourna un temps dans la ville en 1533. Avec la chute de Bude en 1541, la ville revint du côté de Ferdinand.", "af03d9f3"]},
"OLAYLAR_EK:1551-08-15:0":{"b": ["Conquête de Tripoli de Barbarie", "8c659986"], "d": ["Tripoli fut prise aux chevaliers de Saint-Jean ; la côte centrale de l'Afrique du Nord devint ottomane. Autres lieux rattachés à la même date : Misrata.", "f3a5310d"]},
"OLAYLAR_EK:1552-07-27:0":{"b": ["Conquête de Timișoara", "e9fd4995"], "d": ["La région du Banat fut prise et le beylerbeylik de Timișoara (Temeşvar) fut créé.", "1b99085d"]},
"OLAYLAR_EK:1574-08-25:0":{"b": ["Conquête définitive de Tunis", "7bbd11bc"], "d": ["Tunis, sous contrôle hispano-hafside, passa définitivement sous l'administration ottomane ; la ligne nord-africaine était achevée. Autres lieux rattachés à la même date : Kairouan, Gabès, Sfax.", "a92c818a"]},
"OLAYLAR_EK:1600-10-20:0":{"b": ["Conquête de Kanizsa", "0c7b6aa3"], "d": ["Kanizsa fut prise pendant la Longue Guerre ; l'année suivante, la défense de Tiryâki Hasan Pacha devint légendaire.", "12042d94"]},
"OLAYLAR_EK:1663-04-13:0":{"b": ["Début de la campagne d'Uyvar — Fâzıl Ahmed Pacha marche d'Edirne contre l'Autriche", "306a86db"], "d": ["L'Autriche ayant attaqué la Transylvanie et pris les forteresses de Székelyhíd et de Cluj (Kolojvar), Istanbul décida une campagne contre les Habsbourg. Le grand vizir Köprülüzâde Fâzıl Ahmed Pacha partit d'Edirne le 13 avril 1663. À Belgrade, une demande de paix autrichienne arriva, mais lors de deux entrevues à Osijek (Ösek), les conditions ottomanes furent rejetées. Lors de la consultation tenue à Bude, l'objectif fut également fixé sur Uyvar.", "f77c2f04"]},
"OLAYLAR_EK:1663-09-24:0":{"b": ["Conquête d'Uyvar", "ce289470"], "d": ["Uyvar (Nové Zámky), forteresse clé du nord de la Hongrie, fut prise ; l'expression « fort comme un Turc devant Uyvar » passa dans les langues européennes. Après Uyvar, Nitra et Léva se rendirent elles aussi après une brève résistance ; De Souches les reprit toutes deux au printemps de 1664.", "80ef48fc"]},
"OLAYLAR_EK:1715-07-01:0":{"b": ["Reprise de la Morée", "9b6460f1"], "d": ["La Morée, cédée à Venise à Karlowitz, fut reprise en une seule campagne. Autres lieux rattachés à la même date : Patras (Balyabadra), Lépante (İnebahtı).", "56dc13ce"]},
"OLAYLAR_EK:1717-08-18:0":{"b": ["Seconde perte de Belgrade — siège du prince Eugène", "6a194354"], "d": ["Après la déroute de Petrovaradin (Varadin) et la perte de Timișoara, le prince Eugène assiégea Belgrade ; l'armée de secours venue délivrer la ville ayant elle aussi été mise en déroute, la forteresse se rendit. La ville, reprise en 1690 après Karlowitz, fut ainsi perdue de nouveau et la ligne de défense du Danube s'effondra. Belgrade ne devait pouvoir être reprise que vingt-deux ans plus tard, par le traité de Belgrade de 1739. Autres établissements perdus à la même date : Smederevo (Semendire).", "3bf3f600"]},
"OLAYLAR_EK:1788-12-17:0":{"b": ["Chute d'Otchakov (Özi)", "90a67a6c"], "d": ["Otchakov (Özi), forteresse clé au nord de la mer Noire, tomba aux mains de la Russie à la suite d'un assaut sanglant ; la population de la ville fut passée au fil de l'épée.", "9d37026c"]},
"OLAYLAR_EK:1812-05-28:0":{"b": ["Traité de Bucarest — perte de la Bessarabie", "932da4d6"], "d": ["Par le traité qui mit fin à la guerre russe de 1806-1812, l'est du Prut (la Bessarabie) fut cédé à la Russie. Autres établissements perdus à la même date : Akkerman, Kilia (Kili), Khotin (Hotin), Bender, Ismaïl.", "a4c3a1fb"]},
"OLAYLAR_EK:1829-09-14:0":{"b": ["Traité d'Edirne", "b3a8fe4c"], "d": ["À l'issue de la guerre au cours de laquelle l'armée russe entra à Edirne, le delta du Danube fut perdu ; l'autonomie/indépendance de la Grèce fut reconnue de fait. Autres établissements perdus à la même date : Brăila (İbrail), Anapa, Akhaltsikhé (Ahıska). Bien que le traité ait restitué les terres, il ne mit pas fin immédiatement à l'occupation : la Valachie-Moldavie et Silistra restèrent en gage sous administration russe jusqu'au paiement de l'indemnité de guerre — c'est pourquoi ces lieux figurent sur la carte comme occupés même après 1829.", "d09a34fb"]},
"OLAYLAR_EK:1830-10-17:0":{"b": ["Hatt d'autonomie pour la Serbie — knèze héréditaire et clause de garnison", "6a5d901d"], "d": ["Le hatt-ı hümâyun promulgué en application de la disposition du traité d'Edirne concernant la Serbie reconnut Miloš Obrenović comme knèze héréditaire et fit de la Serbie une principauté autonome, libre dans ses affaires intérieures et rattachée à l'Empire ottoman à l'extérieur. Dispositions : la dignité de knèze se transmettrait de père en fils, un tribut annuel forfaitaire serait payé, l'assemblée serbe établirait sa propre administration intérieure, l'Église serait autonome ; en contrepartie, des garnisons ottomanes demeureraient dans les forteresses de Belgrade, de Smederevo, de Šabac, de Soko (Böğürdelen) et de Kladovo (Fethülislâm). Cette structure double dura jusqu'au retrait des garnisons en 1867. Sur la carte, la ville de Belgrade est rattachée à la Serbie autonome à cette date ; la forteresse de Kalemegdan figure sous garnison ottomane jusqu'en 1867.", "b71abc85"]},
"OLAYLAR_EK:1878-06-04:0":{"b": ["Cession de l'administration de Chypre à la Grande-Bretagne", "423da3ee"], "d": ["En échange d'une alliance contre la menace russe, l'administration de Chypre fut cédée à l'Angleterre ; juridiquement, l'île resta terre ottomane. Autres établissements perdus à la même date : Nicosie (Lefkoşa), Famagouste (Magosa).", "04ce99ee"]},
"OLAYLAR_EK:1881-07-02:0":{"b": ["Cession de la Thessalie à la Grèce", "ac614d24"], "d": ["Conformément aux décisions du Congrès de Berlin, la Thessalie et les environs d'Arta (Narda) furent cédés à la Grèce. Autres établissements perdus à la même date : Arta, Yenişehir (Larissa), Trikala (Tırhala), Izdin (Lamia).", "850edaa2"]},
"OLAYLAR_EK:1885-09-18:0":{"b": ["Rattachement de la Roumélie orientale à la Bulgarie", "ee43f137"], "d": ["La province autonome de Roumélie orientale fut rattachée à la Bulgarie par un coup de force ; la Sublime Porte accepta le fait accompli.", "41e57063"]},
"OLAYLAR_EK:1897-05-17:0":{"b": ["Bataille de Domokos", "9c6f29a5"], "d": ["Dans la guerre gréco-ottomane de 1897, l'armée remporta une victoire décisive à Domokos ; sous la pression diplomatique, les gains territoriaux restèrent limités.", "aff8be0b"]},
"OLAYLAR_EK:1898-12-22:0":{"b": ["Autonomie de la Crète", "2e764881"], "d": ["Bien que la guerre gréco-ottomane se fût achevée par une victoire ottomane, l'Angleterre, la Russie, la France et l'Italie proclamèrent le 18 décembre 1897 l'autonomie de la Crète ; l'île devait être une province neutre et autonome sous la souveraineté ottomane. Après le 6 novembre 1898, le drapeau turc ne fut plus hissé à Candie et à Kissamos ; lorsque le prince George, fils du roi de Grèce, entra en fonction le 22 décembre 1898 comme haut-commissaire, la Crète sortit de fait de l'administration ottomane (elle s'en détacha officiellement en 1913). Autres établissements perdus à la même date : Candie (Crète), La Canée (Hanya).", "bc35b2a6"]},
"OLAYLAR_EK:1908-10-05:0":{"b": ["Indépendance de la Bulgarie et annexion de la Bosnie", "393feaa4"], "d": ["Dans la confusion de la monarchie constitutionnelle, la Bulgarie proclama son indépendance et l'Autriche-Hongrie annexa la Bosnie-Herzégovine.", "6b7e2450"]},
"OLAYLAR_EK:1913-07-21:0":{"b": ["Reprise d'Edirne", "536e5599"], "d": ["Lors de la seconde guerre des Balkans, l'armée franchit la Maritsa et reprit Edirne sans combat. Autres lieux rattachés à la même date : Kırklareli, Tekirdağ.", "e5420880"]},
"OLAYLAR_EK:1916-04-29:0":{"b": ["Victoire de Kut al-Amara (Kûtülamâre)", "98b972bc"], "d": ["À Kut, la division britannique assiégée se rendit avec son commandant et ses 13 000 soldats — l'une des plus grandes victoires ottomanes de la Première Guerre mondiale.", "20105888"]},
"OLAYLAR_EK:1917-03-11:0":{"b": ["Perte de Bagdad", "2c18a816"], "d": ["Bagdad, ottomane depuis 383 ans, passa à l'armée britannique. Autres établissements perdus à la même date : Kerbela.", "4add66da"]},
"OLAYLAR_EK:1917-12-09:0":{"b": ["Perte de Jérusalem", "94067617"], "d": ["Jérusalem, ottomane depuis 401 ans, fut remise sans pouvoir être défendue.", "f2738a38"]},
"OLAYLAR_EK:1918-10-01:0":{"b": ["Perte de Damas", "ed177b68"], "d": ["Avec l'effondrement du front de Palestine, Damas fut évacuée ; la domination ottomane de quatre siècles en Syrie prit fin. Autres établissements perdus à la même date : Hama, Homs.", "ff6aea3f"]},
"OLAYLAR_EK:1919-01-10:0":{"b": ["Reddition de Médine", "76b505f6"], "d": ["72 jours après l'armistice, la résistance de Fahreddin Pacha, le « Tigre du désert », prit fin sur ordre du sultan ; la dernière unité ottomane du Hedjaz déposa les armes.", "06b180d9"]},
"OLAYLAR_EK:1919-05-15:0":{"b": ["Occupation d'Izmir", "e32e5e77"], "d": ["L'armée grecque débarqua à Izmir ; la résistance née du premier coup de feu alluma la mèche de la Lutte nationale. Aydın fut quant à elle occupée le 27 mai 1919 (entrée distincte).", "4cc27e6b"]},
"OLAYLAR_EK:1920-03-16:0":{"b": ["Occupation officielle d'Istanbul", "a8e98ada"], "d": ["Les forces de l'Entente occupèrent officiellement Istanbul et le Meclis-i Meb'ûsan fut dissous ; les députés se dirigèrent vers Ankara.", "09ed005b"]},
"OLAYLAR_EK:1921-10-13:0":{"b": ["Traité de Kars", "bb32d4e0"], "d": ["Entre la Grande Assemblée nationale de Turquie et les républiques du Caucase, la frontière orientale fut tracée telle qu'elle est aujourd'hui.", "fe736259"]}
});
